/* 令和7年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r07.committeeSessions.push(...[{"id":"r07-20250924-9","meetingId":"r07-cm09","date":"2025年9月24日","dateIso":"2025-09-24","committee":"文教委員会","time":"午前１０時００分～午後 ３時２０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を77件抜き出しています。","topics":[{"id":"topic-01","title":"教育委員会ＳＮＳの開設","agenda":"教育委員会ＳＮＳの開設","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、ＳＮＳをインスタグラムとフェイスブックで実施するということで、この２つにした理由を伺いたいのと、あと、例として、研修の紹介とかも書いてありますが、これは研修をやっている様子、中身を紹介するということですか。どういった形かということを伺いたいと思います。","respondent":"舩木庶務課長","answer":"１つ、掲載のコンテンツ例に研修等の紹介がありますけれども、具体的な情報の掲載の在り方については、いろいろ検討したいと考えておりますが、主には、区の教育現場で、教職員向けの様々な研修を行うことで、いろいろ教育の内容に関することであったり。","id":"exchange-001"},{"speaker":"横山委員","kind":"質問","question":"先ほど、開設目的のご説明があったのですけれども、こちらのメインターゲットのイメージとしては、教員数を増やす目的のもと、教員を目指す大学生であったり、社会人の方であったりというようなイメージでよろしいのでしょうか。教育委員会のＳＮＳの運用指針は設定されているのでしょうか。","respondent":"舩木庶務課長","answer":"３点目のいろいろな他区の例も踏まえた上で、コンテンツの例のうちの１つに、教育委員会の活動ということで、もちろん家庭教育学級や、いろいろ行っている、発信をすることが有意義である、効果的であると見込まれるコンテンツについては、第一義的には。","id":"exchange-002"},{"speaker":"まつざわ委員","kind":"質問","question":"すごくすばらしい取組だと、私もすぐに登録しました。炎上のガイドラインもそうですけれども、戦略広報課があるので、例えばそこら辺としっかりと連携してやっていくほうが、より強固になると個人的に思ったので、そこら辺を教えてください。","respondent":"舩木庶務課長","answer":"対応につきましては、それぞれ学校ごとにこの配信の対応をするのか、あるいは事務局で、ある程度一括してというところですけれども、現時点では、教育委員会事務局、これは庶務課にはなりますけれども、情報素材をお寄せいただく中で、しっかりとその情報の整理、そして。","id":"exchange-003"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"例えば、講習とかもすごく大事で、学校行事の報告もいいのですけれども、やはりそういう現場の先生のしたほうがいいとか、これが大変だとかでもいいと思うのですけれども、逆にそういうものを発信していただけると、それが一番、先生になりたい人たちの気になるところだと思っていて、ぜひそういったものも積極的にアプローチしていただきたいと思いますけれども、いかがでしょうか。","respondent":"舩木庶務課長","answer":"この教育委員会ＳＮＳを運用開始してまだ一月しかたっておりませんけれども、今後、先々、委員がおっしゃいますように、検証の仕方、まさにＳＮＳがきっかけで品川区の教育現場を志望したというようなことをおっしゃっていただくのは、本当にこれは何よりのことでございまして。","id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ですから、その辺は、これ、すばらしいですよ、ということは、もちろん発信していただきたいのですが、当然いろいろなことが起きるわけで、それに対してきちんと対応しているということも、ここで発信していくのが大事だと思うのですが、例の中になかったので、その辺りはいかがでしょうか。","respondent":"舩木庶務課長","answer":"今後、掲載する素材については、今、委員がご指摘のようなところも含めて今後の検討課題と認識しておりますが、現時点では、やはり何よりも第一義的には区の教育施策であったり。","id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"質問","question":"そういうことも言えれば、マイナスのことが起きたときに、きちんとフォローしているということを示す必要があると思うのですが、その点についてはいかがですか。","respondent":"舩木庶務課長","answer":"様々な危機管理対応にしっかりと教育委員会で対応できていることを発信することで、それがひいては教員を目指される方々にとっても有意義な情報というようなこととして受け止めましたが、そこも踏まえて、そういったことも載せていくかということは、先々。","id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これで最後ですけれども、いいことをＰＲする大本営発表だけしても、本当の品川区の教育がきちんとしていることにはならないと思うので、ぜひ、現時点ではということですから、そういったきちんとした対応も発信していく必要があると思うので、これは要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"筒井副委員長","kind":"質問","question":"私からは、掲載コンテンツについて、ただし書で、各校共通の行事については、掲載対象外とするとありますけれど、これは、いちいちそれを取り上げていたらボリュームが多過ぎる、そうした理由なのでしょうか。このただし書の掲載対象外とした理由をお知らせください。","respondent":"舩木庶務課長","answer":"第一義的には、各学校で行っているような、より特色のある教育活動をアピールすることを予定しておりまして、各校共通の行事が、委員から今ございましたように、例えば運動会にしても、どこの学校でも運動会は、各学校でも学校のホームページを持っておりますので。","id":"exchange-008"},{"speaker":"横山委員","kind":"質問・要望","question":"１点だけ気になったのですけれども、先ほど、コンテンツの部分の議論がありましたけれども、現場の先生方、実際の教職員の方々にとっても、やはり教職員の先生方が増えていくことは、皆さん、望まれていることだと思うのですけれども、こうした取組はすばらしいと思いますので、実際の現場の先生方のこうしたＳＮＳの取組の受け止め方ですとか、まだ始まったばかりですのでこれからだと思うのですけれども。","respondent":"舩木庶務課長","answer":"先ほど１点目でご答弁させていただいた今後の教育委員会ＳＮＳの検証の在り方のうちの１つとして、今、委員ご指摘のような、教育現場の教職員の先生方の生の声、よりこういう発信にしていったほうが効果的だろうといったことを含めて、そういった意見をもちろん集約。","id":"exchange-009"},{"speaker":"横山委員","kind":"質問・要望","question":"今まで、品川区の教育、すばらしい取組をしていただいておりまして、魅力もたくさんありますし、また、様々リアルタイムで発信できるのが、インスタグラムですとか、フェイスブックのいいところといいますか、ホームページとはまた違った媒体というところがありますので、そういった特色を生かしていただいて、また、使い方、その目的に即したコンテンツにしていくために。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-02","title":"令和６年度保護者アンケートおよび児童・生徒アンケートの結果","agenda":"令和６年度保護者アンケートおよび児童・生徒アンケートの結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"９年生で少し上がっていますけれども、ほかにも関連して、外国のことについてもっと知りたいと思うというのも、同様に２年生が一番多くて、８年生に向けてだんだん減っていく中で、９年生で上がる傾向になっておりますけれども、これはなかなか、英語の授業が恐らくだんだん難しくなっていく中で嫌いになっていってしまう子どもたちがいるのだと思う中で、９年生で少し上がってくるのは、受験勉強とか。","respondent":"酒川指導課長","answer":"理解できる授業については、やはり大変重要であると考えていますし、７ページにあります英語の授業で何が楽しいか、どのような活動が好きかといった質問に対する児童の回答等も踏まえまして、教育界とも連携しながら授業改善を進めていく必要があると考えております。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問・要望","question":"理解が９年通して進んできたということで、確かにそういうこともあると思いますし、やはり理解が進むことで好きになるので、子どもたちが、きちんと理解できる授業を進めていただきたい、取組を進めていただきたい、これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"まつざわ委員","kind":"質問","question":"学校が楽しい、これも８５％から７５％ぐらいです。やはり中学生に入ってくると、微妙にこうやって数字がずれていく、落ちていく、それが俗に言う、中一ギャップですか。だから、こういったデータがあったときに、教育委員会として、この下がっていくことに対して、この数字、こういうものをどう分析して、こういうギャップをどう埋めていくのか、どのように対応しているのかということを教えてください。","respondent":"酒川指導課長","answer":"一貫教育などについては、２年生で、他学年の人たちと勉強したり、遊んだりするのは楽しいと思っている一方で、だんだん年齢が上がるにつれて、楽しいと感じている割合が下がっていくこともありますが、これなどは。","id":"exchange-013"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"小学生から中学生になって、中学生・高校生の子どもが多感な時期で、なかなか本当に大変だと実感しているので、それを教えていく先生たちは、いろいろな方がいらっしゃるのでもっと大変なのですけれども、やはりここの子どもたちにしっかりと合わせて、そういったギャップをなるべく埋めていくことが教育だと思いますので、そこら辺は引き続き頑張っていただきたいのと、のだて委員が言いましたけれども。","respondent":"酒川指導課長","answer":"２年生で非常に人の役に立ちたいと思っている一方で、３年生から、質問の仕方がボランティア活動に参加しているという実行段階に移されますので、ここにギャップがあるのは認識しておりまして、やはりこの結果を見ますと、ボランティアが、どのようなものがあるのか。","id":"exchange-014"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ボランティアは、まさにやらされるのではなくて、自分がやりたくなるというのがボランティアの根幹だと思っていますので、ＪＣＡも含めて、地域が一番いいと思っていますので、そういった取組をまたどんどん進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"横山委員","kind":"質問","question":"今、少しボランティアの話がありましたので、ボランティアの部分なのですけれども、令和３年度から見ていきますと、全体の数字が１９.８％、１８.５％、１６.８％と下がって、すごく下がってしまっているのが残念だと思っているのですけれども、こちらの下がった要因について、教育委員会としてどのように分析されているでしょうか。何か分かりましたら、教えてください。","respondent":"酒川指導課長","answer":"下がった要因、正確に理由の把握をしていませんけれども、引き続き、どういった理由があるのかというのは探っていく必要がと考えています。","id":"exchange-016"},{"speaker":"横山委員","kind":"質問・要望","question":"子どもの権利条約の第３１条では、休みですとか遊ぶ権利が入っているのですけれども、以前、区民の方から、毎日習い事があるお子さんたちが、十分に体や心が休めているのか心配だというお声をいただいたことがありまして、そうした部分、区教委として、どのようにこの結果を受け止めているのかお考えを教えてください。","respondent":"酒川指導課長","answer":"これについては、我々も、各ご家庭の方針といったものがあるので、なかなか言及はしづらいところではあるのですけれども、やはり子どもたちがストレスなく生活できる、学業だけでなく、心身ともに健康に生活できるといった生活を整えていけるように、こういう現状については。","id":"exchange-017"},{"speaker":"横山委員","kind":"質問","question":"それぞれのご家庭の事情ですとか、お子さんの体力ですとか、ご本人のやる気ですとか、今こういったことがどうしてもしたい、そういった希望もあるかと思うのですけれども、お休みであったりとか遊びであったりもお子さんにとっては大変重要でありますので、様々な機会を捉えて、保護者の方に働きかけるですとか、または、７日間、そういった活動をしているお子さんに対しては、担任の先生であったりとか。","respondent":"酒川指導課長","answer":"私、昨年まで校長をしておりまして、習い事でストレスを抱えて学校に来て問題行動を起こすですとか、それから、どうしても受験をしなければいけない関係で、毎日のように塾に通っていて、それがストレスになって心身を壊して。","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問","question":"３つありまして、１つ目は、先ほどもほかの委員からありましたけれども、市民科の授業を肯定的に捉えていただいているという保護者の方のお声があったのですが、これは、市民科授業とは何みたいな感じで、保護者のいろいろ声が多かったのですけれども、そこを市民科公開授業でしょうか、それを各学校ともしっかりやられていて、それでこういう授業をやっているというところから、保護者の方。","respondent":"酒川指導課長","answer":"７年生、８年生、９年生、部活動で交流しているのに数値が下がっていくですけれども、部活動が何か弊害になっているとは認識しておりませんけれども、全体として、やはり他学年と関わることに対して、意欲的、積極的な傾向が下がっていく、これは課題だと認識しております。","id":"exchange-019"},{"speaker":"高橋（し）委員","kind":"意見","question":"公開授業は非常にいい取組ですので、ぜひ継続していっていただければいいと思います。市民科の授業を行う先生方は大変苦労されると思う。最後、７年生、８年生、９年生の他学年との交流は、やはり学校は同級生だけではなくて、上、下の子たちと交流するのは非常に大事なので、今、課長がおっしゃったような形で交流が進めていけるといいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"}]},{"id":"topic-03","title":"区立学校におけるいじめの重大事態の発生状況および調査結果","agenda":"区立学校におけるいじめの重大事態の発生状況および調査結果","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"もちろん被害者、保護者の意向を十分尊重していただきたいと思うのですが、可能なところで、やはり報告書を公表していただきたい。そうしないと、どうやってこの結果を生かしていくのか議論できないので、ここを改めて伺いたいのと、あと、保護者が公表を希望しないという理由を区はつかんでいるのかどうか。つかんでいたら、どういった理由なのか話せる範囲で伺えればと思います。","respondent":"丸谷教育総合支援センター長","answer":"１件１件の重大事態は、各個別のそれぞれにはなっていますけれども、いじめの重大化を防ぐためには、どういう学校環境、教室環境を整えればいいのかということの研修を繰り返し行っておりますので、１件１件の細かな共有は現時点では難しいのですけれども。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと併せて、議会にも、できるところで公表していただきたいと、これは求めておきたいと思います。こうした学校の中では研修の充実に取り組んでいるということで、ほかに生かされている部分はあるのかどうか。研修で十分なのかどうかも含めて伺います。","respondent":"丸谷教育総合支援センター長","answer":"まだ導入してから２年目ですので、引き続き、継続しながら、品川区のいじめ予防対策を進めていきたいと考えております。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろ教員のほうも子どものほうも進めているということで、引き続き、取り組んでいただいて、子どもたちが健やかに、いじめがないように、そして、いじめがあったとしても、しっかり解決できるような学校にしていくように取り組んでいただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"まつざわ委員","kind":"質問","question":"これを見ると、令和７年８月に３件あるということは、８月だけで、短期間での集中発生なのですか。例えば、この短期間、８月に発生した、３つもあった要因、何かそういった分析はあるのか、まずそれをお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"ずっと対応してきて、この時点で重大事態と認定したものもあれば、割と短期間に進んだものもございまして、そういったものも含めて調査の中で明らかにしていくです。あくまで法律に当てはめて判断したときに、この時期に重なったです。","id":"exchange-024"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"そこで、例えば、今、いじめとかは、前はよく定期的に無記名で子どもたちにアンケートとか、やっていたと思うのですけれども、今はどのような状況なのですか。","respondent":"丸谷教育総合支援センター長","answer":"昨年度、令和６年度からは、おおよそ月に１回のペースで、これはタブレット端末を用いて行っておりますので、名前は分かる状態で、自分の被害状況であったり、目撃情報であったり、どのようないじめを見たか、あったか、そういったアンケートをタブレット端末でとって。","id":"exchange-025"},{"speaker":"まつざわ委員","kind":"質問","question":"月１回ということは、すばらしいと思うのですけれども、やはり名前が分かると、なかなかあれですよね。それとあと、やはり初期段階からというのがすごく重要な中で、弁護士だったりとか、外部のスクールカウンセラーだったりもそうですけれども、そういう方は、こういうケースに関しても、すぐにこうやって対応していただいたのか、そこの経緯だけ伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"中にはＨＥＡＲＴＳが関わるですとか、学校の都費のスクールカウンセラー等とも連携して進めている事例もあります。","id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"意見","question":"それが１つ。それから、事案番号５は、これはもう金品云々とかあるので、例えば保護者の方が、法的にとか、さらに一歩進んだところまで、保護者の方からすれば、かなりの被害なわけなので、そういった動き、そういった主張、そういったことをされているかどうか。それぞれお答えできる範囲で結構です。よろしくお願いします。","respondent":"丸谷教育総合支援センター長","answer":"事案番号５ですけれども、文科省が出しているいじめの対応の分類が、次のページの上の枠囲みに、1)番から8)番まであるのですが、この中で当てはめると、6)番でいう金品を隠されたり云々というものに当てはまるので、必ずしも金品と限ったわけではなくて、物によっても。","id":"exchange-027"},{"speaker":"横山委員","kind":"確認","question":"重大事態の調査を実施する目的の中に、再発防止策を講じることであったりですとか、あとは被害児童・生徒の心のケアや学びの継続に向けた支援があったりするかと思うのですけれども、その辺り、どのように行われているのか、細かい内容は結構ですので、品川区の教育委員会として、報告書の中に提言等も入っていると思うのですけれども、どのようにやっていらっしゃるのかを確認させてください。","respondent":"丸谷教育総合支援センター長","answer":"学びの継続では、なかなか学校に通えないお子さんに対しては、学校から課題を家庭に届けたりですとか、タブレット上で課題を示したりですとか、その辺りも丁寧に進めているところです。","id":"exchange-028"},{"speaker":"横山委員","kind":"質問・要望","question":"やはり公表する、しないのところで、具体的な事例がもし公表された場合には、共有するのが一番ダイレクトに伝わっていく部分と思うのですけれども、今回のように、公表をご希望されない場合もありますので、そうした場合にも、ほかの事例集だけではなく、例えば、先ほどおっしゃっていた教員研修の充実のところで、個別の事例に触れることなく、ケースの対策であったり、提言の内容であったりとか。","respondent":"丸谷教育総合支援センター長","answer":"その中では、事例検討が主になっていきますので、品川区内で起こったいじめの重大事態だけではなくて、他自治体や、先行事例を織り交ぜた形で行っている現状があります。今後、品川区でも事案が大分重なってきましたので、そういった研修にも生かしていきたいと考えております。","id":"exchange-029"}]},{"id":"topic-04","title":"令和６年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"令和６年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"図書館ですけれども、まず、単純に確認したいところを伺いますが、Ａ、Ｃグループのところで、ブックリストとかパスファインダーということ、あとコンシェルジュ３点セットという言葉が出てくるのですけれども、これはどういったものなのか伺いたいのと、あと、Ｃグループで、ＢＤＳゲートが故障したということで、人数のカウントができなかったとありますけれども。","respondent":"三ツ橋品川図書館長","answer":"ＢＤＳゲートですが、期間について、１か月程度はかからなかったと考えています。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問","question":"分かりました。それと、Ａグループで、昨年度の課題ということになっておりますが、研修の受講頻度が比較的少ないということだったのですけれども、これはどのくらいの回数なのか、どういう頻度なのか伺います。Ｂグループのところで、大井図書館が５年連続で満足度が９０％を超えているのですけれども、この理由はどのように分析されているのか伺いたいと思います。","respondent":"三ツ橋品川図書館長","answer":"令和３年度からの微減に関しては、なかなか難しいところなので、貸出しの件数の状況に関しては注視していこうと考えています。そして、研修なのですけれども、細かい数値は持ち合わせてはいないのですが、こちらに関しては、様々な研修を令和６年度については実施しています。","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"子ども家庭支援センターでは、処遇改善補助金・雇用調整助成金が、２年間ゼロになっていますけれども、その理由を伺いたいのと、あと、今回の課題事項として人材育成の促進、事故防止の取組強化が書かれているのですけれども、ここに当たって、実際にどういった事例があったのかを伺いたいと思います。","respondent":"吉野子ども家庭支援センター長","answer":"処遇改善の部分なのですけれども、こちらは、コロナのときに始まった補助金になっております。この中で職員の賃上げを目的に実施されたものになりまして、次年度以降は廃止になっております。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"人材育成のほうは、ヒヤリ・ハットなどがあったということですか。そうしたことがないように、引き続き強化していただきたいと思います。お願いします。それとあと、これは全ての事業者についてなのですけれども、事業者の従業員、職員の方の環境も、利用者の方にとっては重要なことになってくると思いますので、離職率ですとか、職員の賃金が、十分確保されているのかということを伺いたいと思います。","respondent":"三ツ橋品川図書館長、吉野子ども家庭支援センター長、芝野保育入園調整課長","answer":"離職率に関しましては、調査をしていない状況です。申し訳ありません。こちらの家庭あんしんセンターですけれども、離職は、ご報告いただいておりません。ぷりすくーるのほうも、離職率という形では、ご報告はいただいていない状況になります。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"離職率は分からないということですけれども、あと、賃金が十分なのかということも含めて伺ったので、お聞きしたいと思うのですが、この間、人件費はそれぞれ上がっていますけれども、やはり最低賃金も上がっている、資材高騰もあるので、そうしたことがしっかり担保できるように、委託費も考慮していただいてやっていただきたいと思います。賃金のところを、それぞれ伺いたいと思います。","respondent":"三ツ橋品川図書館長、吉野子ども家庭支援センター長、芝野保育入園調整課長","answer":"こちらの収支報告書にも出ているように、前年度よりも上がっている状況では、人件費の増となっております。子どもの特性が増えてきているというものと、あと、家庭で養育が困難であるというような状況もありまして。職員の処遇ですが、定期昇給分等々、こちらにつきましては、適切に管理運営委託費に積み増して対応させていただいているところです。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"職員の処遇も、利用する方にとっては、提供する側の環境が利用者にも影響してくると思いますので、ぜひ賃金や処遇改善、環境をよくしていくこともぜひ視点として見ていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"まつざわ委員","kind":"意見","question":"家庭あんしんセンターですけれども、トワイライトステイ事業が、年々こうやって利用率が上がっていく一方で、ショートステイがだんだん減っていっていると思うのです。それで、小学校６年生から中学校３年生まで拡充して、こういった掘り起こしを一生懸命やっていただいたのですけれども、この減少した数字の分析はどのようなものなのかお聞かせください。","respondent":"吉野子ども家庭支援センター長","answer":"大体の方が、理由として、育児疲れで利用されるのですけれども、この方たちが２泊とか３泊ではなくて、１泊で利用される方が増えてきています。その分、働き方ということでいきますと、トワイライトステイのほうが、やはり残業などでだんだんと増えてきています。","id":"exchange-036"},{"speaker":"まつざわ委員","kind":"意見","question":"それと、先ほどお話の中でも、支出、１,４００万円が２,３００万円まで大分上がってきている人件費の課題があるというお話を聞きました。人件費の課題も補助金でこうやって対応しているという、何かそういうお話もありましたけれども、指定管理者と、こういった課題は、どう区と話し合って、改善の効率化は、どういう方向性でこうやっていきましょうという、そういったお話は、どのようにされているのか。","respondent":"吉野子ども家庭支援センター長","answer":"こちらの家庭あんしんセンターですけれども、毎月、お話しできる機会があります。そのときに、こういった収支の状況ですとか、あと、事業の報告会がありますので、そこで課題を拾っていきたいと考えています。","id":"exchange-037"},{"speaker":"まつざわ委員","kind":"質問","question":"例えば子育てが終わった世代、何世代と言いますか、子育てが終わった世代をターゲットにしたりとか、保育を学ぶ学生をターゲットにしたりとか、そういったターゲットを絞った説明会に特化してやっていくと、今までの３割よりも、このファミリー・サポート・センターのターゲットを絞った説明会、こういった考え方はありだと、私自身、これを読んでいて思ったのですけれども、そこら辺はいかがですか。","respondent":"吉野子ども家庭支援センター長","answer":"今回、令和７年度から、在勤と在学でも提供会員が要件になりましたので、こちらに関しましても、大学や専門学校にも働きかけていきたいと考えております。","id":"exchange-038"},{"speaker":"横山委員","kind":"質問・要望","question":"図書館のほうをお伺いいたします。レファレンスの数が伸びているのですけれども、内容、サービスの質に何か変化があるのでしょうか。レファレンスサービスの研修についてなのですけれども、例えば国会図書館が主催でオンラインの研修などが行われていると思うのですけれども、現在、どのような学習が行われているのかということも確認させてください。","respondent":"三ツ橋品川図書館長","answer":"レファレンスサービスに関しましては、やはり図書館ならではの知の知、知識の提供は大事だと考えています。その中で、区と指定管理業者との月１回の館長会とか、様々なところがありますので、そちらに関しても、向上は実施していただけるように働きかけをしています。","id":"exchange-039"},{"speaker":"横山委員","kind":"質問・要望","question":"ひまわり荘のご利用の区民の方から、職員に大変よくしていただいているとのお声をいただいています。そうしたケースに対して、今後どのような仕組みの構築が必要だと区は考えていますでしょうか。現在そうした課題の多いケースが増えていることに対する、何か研修等に参加しているようなものがあれば、どういったものがあるのか、そして、今後、どういうものが必要になってくるのかもお知らせください。","respondent":"吉野子ども家庭支援センター長","answer":"専門的な部分の研修としましては、子どもに起こりやすいけがや予防とかを学ぶ機会であったりとか、子どもへの望ましい声かけであったりなど、いわゆる子育てのノウハウの研修をして、それをお母様たちに伝える対応をしております。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"現在、研修については、子育てに関する研修ということですけれども、様々な多様な課題について対応できるように、そして、ほかの課が行っているような、例えばそういった研修のご案内ですとか、そういった参加ができるような何か仕組みをつくっていただいたりですとか、または、個別のケースで本課に情報がいって、現在は、障害の部門であったりとか。","respondent":"吉野子ども家庭支援センター長","answer":"こちらの家庭あんしんセンターなのですけれども、月に１回、私どもの課と連携、そういった話合いの場は設けております。そのときに、１件１件課題を出していただいて、それで解決策を見いだしております。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問","question":"最後に、ぷりすくーるの部分ですけれども、こちらの収支が安定しているお話があったのですけれども、１名、採用があったことで、予算よりも少しオーバーしているという記載があったのですけれども、こちらは予定していなかった採用が発生してしまった背景があるのでしょうか。その辺りを少しご説明いただけたらと思います。","respondent":"芝野保育入園調整課長","answer":"職員の採用の件についてですが、年度途中に、よりよい乳幼児教育活動をするためということで、法人で１名採用したと聞いております。それが金額的にはね返っておりまして、令和７年度については、しっかりそれを委託費の中に入れて対応させていただいてあります。","id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"質問","question":"それからもう１つは、さっき、本の貸出数の話が出ていましたけれども、別の指標が最近あって、図書館にどれぐらいいるか、いろいろ賛否両論あるのですけれども、滞在時間の計測、それについて、もし、どのような形かで調べていたら、その点と、滞在時間でたくさん利用していただけるということは大変いいことなので、それに関してのお考えを伺います。","respondent":"三ツ橋品川図書館長","answer":"貸出の件ですけれど、こちらは滞在時間に関してもなかなか難しいところでございまして、長く一生懸命本を読んでいらっしゃる方や、新聞を読まれている方、様々な方がいらっしゃいますので、そちらに関しては今後の研究課題と考えています。","id":"exchange-043"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"まちづくりに、地域に協力するというよりも、図書館が中心となって、ぜひまちづくりを進めていっていただきたいと思います。滞在時間については、いろいろな指標があるので、１つ参考になると思うので、測定方法を少し検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"筒井副委員長","kind":"質問","question":"何点か伺いたいと思いますけれども、図書館について、人件費が、Ａグループ、Ｂグループ、Ｃグループ、上昇しておりますけれど、それについて予算執行の視点で触れられていないのですけれども、その原因について詳しくお知らせください。指定管理者からの賃上げの要求とか、そうしたことをお知らせください。","respondent":"三ツ橋品川図書館長","answer":"人件費の増に関しましては、やはり最低賃金の増に伴って上昇しています。","id":"exchange-045"}]},{"id":"topic-05","title":"令和８年度末における小規模保育事業の閉園","agenda":"令和８年度末における小規模保育事業の閉園","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、建物の老朽化で立ち退きになってしまったということですけれども、ほかの何か経営的な問題とか、そうした理由は特にないのかどうかと、今までにこうした保育園が閉園になるということはあったのか伺いたいと思います。","respondent":"佐藤保育事業担当課長","answer":"ほかの園で廃園等があったのかというご質問ですが、今年度の末に１園、小規模保育事業所で閉園の予定がございまして、こちらは、同様に認可保育園を運営している事業者でありまして、そうした事業に経営資源を集中していきたいとお話を伺っておりまして。","id":"exchange-046"},{"speaker":"横山委員","kind":"確認","question":"確認なのですけれども、この後、令和８年度４月の０歳児クラスですとか、あとは、年度途中で転園してきたお子さんに対しても、転園時の加点を実施するという対応になるのでしょうか、その辺りを確認させてください。","respondent":"佐藤保育事業担当課長","answer":"今後の入園についてですけれども、今後、同一園において卒園ができない児童の年齢に関しましては入園を停止したいという要望を事業者より承っておりますので、そのように対応する予定です。","id":"exchange-047"},{"speaker":"若林委員","kind":"確認","question":"この周辺の０歳児園、１歳児枠は、現状、加点で入れればというお話の趣旨だとは思うのですけれども、確認で状況を、確実に転園がきちんとできますということも確認したい。","respondent":"佐藤保育事業担当課長","answer":"しかし、現在の１歳児、２歳児の方は、来年の４月に閉園になりますので、卒園して継続の連携園への入園が可能となる状況です。","id":"exchange-048"},{"speaker":"高橋（し）委員","kind":"質問","question":"すみません、私が勉強不足で分からないのですけれども、令和８年度末で閉園すると、３月３１日に廃止のような気がするのですけれども、今お話にあった転園の関係で、４月１日にもいることにして転園するのですか。０歳の子たち。この廃止日が令和９年度の４月１日ですよね、そこが少し分からないのですけれども。","respondent":"佐藤保育事業担当課長","answer":"こちら、閉園の記載なのですけれども、４月１日に閉園という記載の方法になっていますので、３月３１日に閉園ではなく、４月１日をもって閉園するという記載となっているものです。","id":"exchange-049"}]},{"id":"topic-06","title":"令和６年度品川区児童相談所運営実績","agenda":"令和６年度品川区児童相談所運営実績","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"一時保護の状況で、課題に書かれておりますけれども、４階バルコニーに児童が出てしまう事故があったということで、もともとここは出られるようになっているのか、出られるようになっていないのか伺います。どういう状況かということです。それと、その下に、特性のある児童が増えているので、職員の育成が急務だということですが、どういった部分が足りないのか伺いたいと思います。","respondent":"長谷川児童相談課長","answer":"開設前には、実際に多くの派遣研修に行かせていただきましたし、今回、経験者採用ですとか、任期付採用等を用いまして、多くの経験者の方にも来ていただいていますので、そういった経験則であるとか、あるいは、品川区の特性等を加味しまして、日々。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問・要望","question":"改めて何かあれば伺いたいと思います。職員については、いろいろ研鑽を積んでいらっしゃるということでしたけれども、今回、職員の育成が急務だというのは、この事故を受けて対応が必要だということで書かれているのか、どういった専門性が必要なのかを伺いたかったのですけれども、いかがでしょうか。","respondent":"長谷川児童相談課長","answer":"ただ、こういった事故が発生しましたので、事故の振り返りですとか、事例の共有、こういう事故が発生したときに、どう初動で対応すればいいかとか、そこら辺の起こってみて初めて分かる対応策もありますので、職員間で共有しながら、起こらないようにしつつも。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問・要望","question":"３番の施設入所措置等状況で、令和６年９月時点では９２件ですか。この受入先は、区内にあるのかということと、あと、今回、都児相から区児相になって、令和６年度では２件増えたということで、こうした入所措置が増えるのは、区内でどういったことが起きている、どういったことをあらわしていることになるのか、そこを伺いたいと思います。","respondent":"長谷川児童相談課長","answer":"とはいえ、家庭復帰が難しい場合には、里親ですとか、あるいは、小規模のグループホーム、または児童養護というように整理をしていまして、一時保護の件数が多くなっていること、また、児童虐待通告、対応件数が増えているという全体的な分母が増えている中で。","id":"exchange-052"},{"speaker":"のだて委員","kind":"質問","question":"それと、入所の一時保護、２か月を超えているのが２３％いらっしゃるということで、この理由はどういったことなのか、様々理由があると思うのですけれども、あまり長期になると、先ほどの国が言っている家庭養育が重要だというところから見ても、あまりよくないと思うのですが、理由を伺いたいと思います。","respondent":"長谷川児童相談課長","answer":"長期化している理由なのですけれども、本当に様々あります。かなり個人的な理由になってくるところもありますので、全てこの場ではお伝えできないのですけれども、１つ申し上げられるのは、当然、児童相談所の職員全員が家庭で生活できるならしたほうがいいと思っています。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"そのほうが子どもたちにとっても、環境としていいと思いますので、よろしくお願いします。こうしたいろいろ重大なケースなどもあると思いますので、職員の方にも様々負担がかかっていると思いますが、この間、児童相談所で、退職者などはいらっしゃるのかどうかと、あとは、やはりそうしたことがないようにケアをしっかりしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"長谷川児童相談課長","answer":"人事課にもご協力をいただいて、産業医面談等も行っていることと、あと、衛生委員会を立ち上げていますので、衛生委員会の中で超過勤務のことを取り扱うですとか、職員の全体で超勤を当たり前にしない風土ですとか、積極的に年休をとれる風土ですとか。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"様々大変な状況があると思いますので、ぜひ職員の方へのケア、充実させていっていただきたいと思います。最後に、超勤を当たり前にしないというお話がありましたけれども、今の状況、どのくらいの方が、どのぐらいの超勤になっているのか分かれば伺いたいと思います。","respondent":"長谷川児童相談課長","answer":"要因としましては、様々ありますけれども、児童相談所の支援が、保護者に対しては求められていない支援をするというところですごく難しさがありまして、例えば、面談の日時の設定をする場面においても、やはり夜でなければ対応しないとか、そういうことを言われたときに。","id":"exchange-055"},{"speaker":"横山委員","kind":"確認","question":"確定値を見させていただきました。日々の職員の皆さんのご努力、本当にありがとうあります。質問ですけれども、まず、児童相談所の運営状況等ということで、社会福祉審議会でも速報値が公表されていると思うのですけれども、こちらに子どもの権利擁護の取組状況も入っておりまして、こちらは特に変更がないということでよろしいのかどうか確認をさせてください。","respondent":"長谷川児童相談課長","answer":"そうした中で、相談件数が年々増加していることや、保護件数が増えているということで、一定課題感もありますけれども、とにかく目の前にある１件１件に真摯に向き合って、丁寧に対応していくことに尽きると思っています。","id":"exchange-056"},{"speaker":"横山委員","kind":"質問・要望","question":"こちらの２番の課題で、先ほども４階のバルコニーに出てしまう等の事故のお話があったのですけれども、こちらは、お子さんが外にすごく出たいというようなことが、たまにお子さんの状態とかであると思うのですけれども、普段から外の空気を吸うような場面だったり、あと外出だったり、そういう機会なども設けられていると思うのですけれど、こちらのケースに関しては、少し精神的に不安定だということで。","respondent":"長谷川児童相談課長","answer":"ただ、今回のこの事故、事例に関しましては、少し個別性が高いので、詳細はなかなか申し上げられないですけれども、精神的に不安定になるお子さんもいらっしゃいますので、そういった子の不調が高まらないように、なるべく早いうちから、心理とか。","id":"exchange-057"},{"speaker":"高橋（し）委員","kind":"意見","question":"１つだけ、ここの中に、どこに入るか分からないのですけれども、子ども家庭支援センターとの連携も捉えていると思うのですけれども、その辺りの、この表の中の数字でなくてもいいので、これまでの連携の実績、協力体制をお話いただければと思います。","respondent":"長谷川児童相談課長","answer":"この一元化のポイントは、虐待をどちらが受けたとしても、その後、合同会議を開いて、お互い納得のもと、支援機関を決めようというところで、子ども家庭支援センターと、およそ１年間、膝つきの検討をして決めた仕組みになります。","id":"exchange-058"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今お話を伺って、合同会議と、あと、そういった連携の相談をしながら、児相が２０％受けたとかありますけれども、協力体制が進んでいっているのだと思うので、ぜひ一体となって対応していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"}]},{"id":"topic-07","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"登録者数は、そんなに変わらないのかと思うのですけれども、利用者数が大きく違うということで、源氏前小学校だと、１日当たり１０.９人、豊葉の杜学園は０.４人で、大きく差が出ていると思うのですけれども、こうした理由、区では、どのように考えていらっしゃるのか伺いたいと思います。２か月弱ですけれども、どういうときに利用が多いとか、そういったことはあるのかどうか伺います。","respondent":"上野子ども育成課長","answer":"ご質問２点にお答えいたします。豊葉の杜学園の利用が少ないというところですけれども、背景としましては、豊葉の杜学園は、午前７時半から校門を開けておりまして、昇降口の手前まで児童を入れているという状況がございました。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、特に、こういうときが多いとか、そういうことはないのですね。それだけニーズはあるとも思いますので、引き続き進めていっていただければと思いますが、今後、全校展開に向けて、民間事業者への委託も検討していくということで、これはどういったところに委託をしようと検討されているのか伺います。","respondent":"上野子ども育成課長","answer":"今後、民間委託の委託先ですけれども、人材派遣会社ですとか、警備会社を想定しています。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問・要望","question":"人材派遣会社と警備会社を検討しているということで、そういったところできちんと見守りができるのかというのが、今、第一印象なのですけれども、区の考えを伺いたいのと、あと、朝食です。これ、１点、朝食支援を利用したい理由と、朝食支援を利用しない理由、この円グラフが全く同じ割合なのですけれども、これは何か間違いかどうかをまず確認させていただきたい。","respondent":"上野子ども育成課長","answer":"１点目のご質問ですけれども、人材派遣会社、それから警備会社の方、見守りができるのかというご質問ですけれども、見守り員の方につきましては、今現在、シルバー人材センターの方に対してもそうなのですけれども、こちらの課から事前に説明会を実施しておりまして。","id":"exchange-062"},{"speaker":"のだて委員","kind":"質問","question":"朝食支援ですけれども、この回答項目で、利用したい理由で、特殊な状況への対応とか、その他もどういったことがあるのかを伺いたいのと、利用しない理由についても、子どもの生活リズムへの配慮というのはどういうことなのか、あと、その他でも、どちらも２５％ということで、結構その他が多いので、どういったことがあるのかということを伺いたいと思います。","respondent":"上野子ども育成課長","answer":"いただいたご質問に対してお答えいたします。朝食支援を利用したい理由の中で、特殊な状況への対応についてですけれども、具体的にいただいていますご意見としましては、親の体調不良時のサポートですとか、出張による早朝勤務時の対応というものをいただいています。","id":"exchange-063"},{"speaker":"まつざわ委員","kind":"意見","question":"これ、多分、これから１期、２期とやっていく上で、次、１期をもう１回見てからだと思っているのですけれども、例えば、そういう１期でやったときに、ニーズをこうやって調査したうちに、結局、費用対効果、どれだけ子どもが利用していて、例えばシルバー人材センターの人をお願いするのに予算もかかるわけで、その費用対効果の基準は、何なのか、ばらつきがあっても利用したいという学校が多くあれば。","respondent":"上野子ども育成課長","answer":"ご質問いただきました、どれだけお子さんが利用しているか、優先順位の基準ですけれども、まだこれから１期を始めるところですので、まずは明確に優先順位を決めているというところではございませんけれども、他自治体の事例なども参考にしながら。","id":"exchange-064"},{"speaker":"まつざわ委員","kind":"質問","question":"もう１つ、課題の１つで、見守り隊の確保と、今、シルバー人材センターとかに委託、警備会社とかに頼みたいというお話があった。シルバー人材センターの人は、多分そんなにお金はもらえないと思って、そうすると、賃金のバランスだとか、質のバランスに差が出てしまうと私は思うのですけれども、そういった差も、これからどうやって埋めていくのか、そこを教えてください。","respondent":"上野子ども育成課長","answer":"ただ、今後、シルバー人材センターでの募集を進めていく中で、段階的に委託の範囲を狭めていくなどして、なるべく同一の事業者で対応できるように進めてまいりたいと考えております。","id":"exchange-065"},{"speaker":"まつざわ委員","kind":"質問","question":"ぜひ子どもにも聞いてほしいのです。この結果を踏まえて、これもそうなのですけれども、１１月から３校で試行実施すると言いますけれども、例えば、どれくらいの数だったら、その効果があるのですか、朝食の利用について、これぐらいの数だったら効果があるとか、そういった指標、そういうものは現状であるのかお聞かせください。","respondent":"上野子ども育成課長","answer":"朝食のご利用の割合、どれだけやれば効果があるかというご質問だったかと思いますけれども、まずは、まだ試行を始める前の段階ではありますので、どれだけの方が利用されるかというところで、そうは言っても、全く利用がないという場合ですと、ニーズがないと思いますけれども。","id":"exchange-066"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ご利用する方がいたらニーズがあるので、続けていくということは分かるのですけれども、その中でも、アンケートの中では、これだけ家でやりますと、でも一方で、課長がおっしゃったように、７％は食事をとらないのであれば、朝食の朝の居場所も含めると、いろいろばらつきが出て、例えば、これから先のことなので私が何と言うこともないのですけれども、希望者全員よりも、いずれは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"高橋（し）委員","kind":"質問","question":"そういうことで、何かあったか、何かそういった対応をしなければいけないことがあったのでしょうかというのが１つ。３つ目は、シルバー人材センターの見守り隊の募集のチラシなどが折り込みとかポストに入っていたりするのですけれども、現状で応募の状況はどうなのか、この１０月で１０校でしょうか、開始していけるような見込み、その辺りはいかがでしょうか。","respondent":"上野子ども育成課長","answer":"もし何か現地でトラブルがあった場合には、本課で専門の職員が待機しておりますので、何かあった場合は、まずは本課にご連絡をいただきまして対応するということで進めてまいりたいと考えています。","id":"exchange-068"},{"speaker":"高橋（し）委員","kind":"質問","question":"何もなかった３校の試行でよかったと思います。それから、１０月の開始について、人材の確保がめどがついているのもよろしいと思います。そことの関係は、どう調整しているか、万が一のとき、見て何もしないわけにはいかないから協力を仰ぐとか、そういうところが出てくることになると思うのですが、その辺の連携は、どのようになっているのでしょうか。","respondent":"上野子ども育成課長","answer":"もしどうしても、場合によっては教職員の方のご協力をいただく場面が出てくるとは思いますけれども、そこについては、まずは見守り員の方と今回は対応してまいりたいと考えています。","id":"exchange-069"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今お話があったように、一義的には子ども未来部の事業なのですけれども、今お話があったように、現場に仮に先生方がいらっしゃったら、そこはしっかりと協力しながら、子どもの事故とか、いろいろなものに対応をするということを学校を回ってお話しされているということですので、事故がないのが一番ですけれども、そういったときの対応はしっかりと協力して行っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"横山委員","kind":"確認","question":"見守りの状況についてお聞きしたいのですけれども、２名の見守り員の方がいらっしゃって、１日平均、多くて源氏前小学校で１０.９人ということなので、五、六人をお一人でになると思うのですけれども、見守りの状況ですとか、人員の数に関しては、どのように試行期間で、様子ですとか、十分、不十分なのかどうか、もし何かありましたら、教えてください。","respondent":"上野子ども育成課長","answer":"それから２点目のご質問、トラブル対応につきましてですけれども、私どもで危機管理マニュアルをつくっておりまして、例えば、事故、けがが発生した場合ですとか、火災が発生した場合、それから地震が発生した場合、不審者を発見した場合、朝食支援が始まった場合ですけれども。","id":"exchange-071"},{"speaker":"横山委員","kind":"確認","question":"見守りの方、合計３名で、お部屋の中で見守る見守り員の方が２名と、校門の前で見守っていただく方が１名で、これからは進めていくということを確認いたしました。","respondent":"上野子ども育成課長","answer":"ご質問がございました水害の発生時の場合の対応ですけれども、そちらにつきましては、朝の居場所の実施マニュアルに記載させていただいておりまして、どちらかというと、中止時の対応についてに記載を含めております。","id":"exchange-072"},{"speaker":"横山委員","kind":"質問・要望","question":"先日の大雨は短時間で急に雨が降ってきたので、もし中止の対応が間に合わなかったということがあった際にも、きちんと対応していただけるように、危機管理マニュアル等にも教育委員会の指針ですとか様々な地震マニュアルを含めて研修等でしっかり伝えていただく必要があるかと思いますので、ぜひ今後に生かしていただきたいと思うのですが、その辺りをもう１回お願いします。","respondent":"上野子ども育成課長","answer":"ご指摘のございました大雨等の場合、中止のご連絡がどうしても難しい場合ということもいただきましたので、今後、研修等で、その辺りをお伝えしつつ、管理マニュアルにも反映させてまいりたいと考えております。","id":"exchange-073"},{"speaker":"若林委員","kind":"意見","question":"少しご説明がよく理解できなかったので、豊葉の杜学園について、利用者数、累計、１日平均のご説明があったのですが、もう１回、校門のところで云々と、私が説明を聞き逃したのだと思いますので、もう１回ご説明いただいて、その上で、ほかの２校も含めて、いわゆるこの朝の居場所の本来の目的である校門の外で学校が開くまで待っている、学校に入れない状況が、豊葉の杜学園も含めて。","respondent":"上野子ども育成課長","answer":"ご質問をいただきました豊葉の杜学園が、どういう状況で、今、１日平均０.４人という利用者数になっているかですけれども、午前７時半から校門を開けられていまして、昇降口の手前までは児童が入れるような状況にあるそうです。","id":"exchange-074"},{"speaker":"若林委員","kind":"提案","question":"朝食はどちらかというと付随的に、議会の提案に対して区が積極的に朝食にも光を当てていただいてセットで、なので、朝食については、これは全国調査で７％、品川区がどういう数字か分かりませんけれども、こういった方々が、今までこの事業によって、１％でも、２％でも朝食を食べられる子どもが多くなればいいと、それは願ってやみません。豊葉の杜学園は分かりました。","respondent":"上野子ども育成課長","answer":"すみません、説明が足りずに失礼いたしました。","id":"exchange-075"},{"speaker":"若林委員","kind":"質問","question":"その子たちは、いわゆる登録している方たちですか。","respondent":"上野子ども育成課長","answer":"登録している方です。","id":"exchange-076"},{"speaker":"若林委員","kind":"質問","question":"要するに、校門の中であろうと外であろうと、７時半の時間帯を目指して来ている子どもたちは、教室の中に入ろうと、中に入らないで滞留している、関係なく、７時半にいらっしゃる子どもは、全部登録している方ですか。登録していなくても、別に７時半に行ってもいいわけですよね。","respondent":"上野子ども育成課長","answer":"そうです。７時半に門が開きますので、開いた時点で入れるので、必ずしも居場所に登録されているかどうかは分からない状況です。ただ、部屋にいらっしゃったときに、事前登録制になっておりますので、登録していただいた方が居場所の利用ができるという形の事業になっております。","id":"exchange-077"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/178682?Template=document&Id=7167#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":75952,"voices":240}},{"id":"r07-20250924-5","meetingId":"r07-cm09","date":"2025年9月24日","dateIso":"2025-09-24","committee":"総務委員会","time":"午前１０時００分～午後 １時０５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件抜き出しています。","topics":[{"id":"topic-01","title":"説明に入る前に、各所管委員会における審査の結果","agenda":"説明に入る前に、各所管委員会における審査の結果","exchanges":[{"speaker":"西本委員","kind":"質問","question":"マイナス調整もしているのですが、なぜ今なのかということ。どこかからどこかへ持ってくるという話なのですが、それは何か決まりがあるのですか。財政調整基金から持ってくるというほかに、いろいろなところから流用してというようなのが、結構頻繁に最近出てきていると感じるのですが、それの何か基準というのは何か決め事があるのでしょうか、教えてください。","respondent":"加島財政課長","answer":"大きく３点ご質問をいただいたかと思います。八潮南特別養護老人ホームの延伸ですけれども、地中障害物が発見されまして撤去を行いますが、その分、令和７年度に本来行うべきであった工事ができておりませんので、７年度に当初予定していた工期出来高が発生しない見込みです。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"大体分かりました。金額はいろいろあるでしょうから、その考え方として、予算で決められた額、承認をもらったものについてと言うのですが、ここが、例えば何％とかという形での審議だったのだろうか、少し定かではないので、何か決まりとか、これぐらいのところで予算を取っているから、その中の範囲だったら流用可能なのですよというようなものがあるのであれば、それを教えてください。","respondent":"加島財政課長","answer":"１点目の八潮南特別養護老人ホームの工期延伸の件ですけれども、地中障害物の撤去が発覚した段階で事業者とも話合いをいたしまして、今回、その分ではみ出てしまう工期延伸分につきましては債務負担行為を組んでおりますし、またインフレスライドにも対応しておりますので。","id":"exchange-002"}]},{"id":"topic-02","title":"勝島歩道橋補修工事請負契約","agenda":"勝島歩道橋補修工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"この歩道橋補修工事ですが、前回はいつ頃やられたのですか。教えてください。","respondent":"佐藤経理課長","answer":"前回の大きい補修工事については特段所管から聞いておりませんで、この歩道橋は１９８５年ですので、約４０年前にできたもので、細かい補修については日々の中でやっているということだと思います。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"この写真等を見る限りでは、さび等云々があると思うのですが、通常４０年間放っておくというのはいかがなものかなという感じがしたもので、通常、公共施設なども、やはり１０数年から２０年ぐらいのサイクルで補修していると思うのですが、何でこんなふうに４０年間も放っておいたのかなというのは少し疑問に感じたもので、それだけ教えてください。","respondent":"佐藤経理課長","answer":"定期的な点検と小規模な補修については都度やっているというところですけれども、今回のような大規模な工事については、設計をした上で、状況に応じて計画して進めていると聞いております。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"これは補助金があるのですか、国とか東京都から。これは、品川区独自の財源からでしょうか。","respondent":"佐藤経理課長","answer":"補助金に関しては、所管から確認をしておりません。〔「そうですね。","id":"exchange-005"}]},{"id":"topic-03","title":"子供の森公園管理事務所改築工事請負契約","agenda":"子供の森公園管理事務所改築工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"ここでまた加地建設という名前が出てきているわけですが、加地さんは新庁舎整備のほうにも関わっていると思うのですが、資本金の規模からいって、何もかもできるというのは非常に違和感があるのですが、経理課として、昨日も少し質問させていただきましたが、大丈夫なのですか。そんなに従業員がいるようには私も見ていないのですが、その辺は大丈夫なのですか。教えてください。","respondent":"佐藤経理課長","answer":"委員ご懸念のほかの事業もあるけれどもというところですけれども、こちらに関しては、区で一つ一つ確認するわけではありませんけれども、これまでも同様の形で複数の事業を同時に受けているということもありますけれども。","id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"私は発注する側の責務もあると思うのですよね。今、民間企業でも、例えば協力会社に仕事をお願いするときに、能力的にどうだとかこうだとかということをやはり判断しながら発注をしている。","respondent":"佐藤経理課長","answer":"繰り返しの答弁になりますけれども、入札時に課している条件をクリアしていただいていれば、それ以上、区が事業者の事業実態について踏み込んで確認するということはできませんので、また、途中でできなかったということであれば、以降の入札に関して資格を停止するですとか。","id":"exchange-007"},{"speaker":"須貝委員","kind":"意見","question":"相手の能力とか人員がどれぐらいいるのだとか、そういうことを見ているのに、片やこっちはそのまま、そういうのを関係なしに、いや、今まで中止しなかったからとか、途中で仕事を投げたとかそういうことがないから、相手が仕事を受けるから、入札に参加させたというのは、私はやはり考えていかなければいけないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"}]},{"id":"topic-04","title":"庁有自動車のカーナビに係るＮＨＫ放送受信料の支払い","agenda":"庁有自動車のカーナビに係るＮＨＫ放送受信料の支払い","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"これ、今まで、毎年、ＮＨＫから請求というのはきちんとコンスタントに来ていたのですか。教えてください。","respondent":"佐藤経理課長","answer":"区のＮＨＫへの受信料の支払いの方法というところだと思います。毎年ＮＨＫから１０月に、テレビも含めて受信機器の設置状況の調査というものが来ておりまして、それに基づいて全庁各部に対して調査を行いまして、経理課で取りまとめて回答しております。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"これからの分は、払うというのは妥当な請求だと思うのですが、過去に遡って、例えば品川区に支払いをお願いしますという督促状とかが来ているなら分かるのですが、そうでなかったら、何か過去の分は払う必要はないのではないかという気がするのですが、その辺のご見解をお聞かせください。","respondent":"佐藤経理課長","answer":"もう１点、過去に遡って支払う必要があるかどうかというところですけれども、ＮＨＫの受信料に関しては放送法という法律で定めがありまして、テレビをはじめとした受信機器を設置した場合は受信契約を結ばなければならないという規定になっております。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"それを、いや、急に裁判で勝ったから請求するというのは、これはおかしな話ではないですか。やはり向こうが調査して、こうやって「どうなのですか、品川区さん」とか、「ではこういう請求書を出します」、「支払ってくれなければ督促状を出します」という形なら分かるけれども、ほかの自治体が払っているからうちもやらなければいけないというのは、何か違和感がある今回の事件です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"そういうことであれば納得いくのですが、それもなく、忘れている状況を、なぜ私らの税金を使って支払わなければいけないのと、そういう感覚が当たり前だと私も思うので、ここはどういう折半の仕方をしたのかということをお聞かせください。折半ではないですね。それから、カーナビ５台を撤去しているということですが、カーナビ５台は必要ないという結果に基づいて撤去ということになったのでしょうか。","respondent":"佐藤経理課長","answer":"先ほど説明の中でもありましたけれども、ワンセグの携帯ですとかテレビが映るモニターに関しては、実態をＮＨＫと調整して、受信契約が必要というものだとは思いますけれども、解釈の範囲の中で、それらについては契約の必要がないというところになりましたので。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"だけれども、それでもやはり責任の所在というのはＮＨＫ側も私はあると思っているので、そこは協議の中で何かしらの話合いはあったのだろうと思いながら、いずれにしても法にのっとってやっていかければいけないのは分からないではないですが、だけど、もう少し慎重にというか、していただきたいと、今後こういうことのないように、いろいろと注視していただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"塚本副委員長","kind":"確認","question":"カーナビ３９台が対象になったということで、これは少し教えてほしいというか、あるのか、ないのかの確認だけですが、契約としては１台幾らということでの単純な積算なのか、もしかしたら区役所として、車全体の包括契約みたいなことで多少安くなる、そんな契約が、向こう側の契約の在り方としてあるのかどうかというのをお聞かせください。","respondent":"佐藤経理課長","answer":"契約の本数といいますか、対応のことですけれども、結論的には車１台について１契約という形になっております。","id":"exchange-014"},{"speaker":"塚本副委員長","kind":"質問","question":"そうすると、カーナビですが、本来は道案内が、もともとは役割だったと思うのですが、今の車は多分、基本的にテレビが見られるようになっていると思うので、車を買うと、もう必然的に契約みたいな、ＮＨＫの契約はしませんみたいなことは恐らくできないと思うのですが、できる余地はあるのですか。","respondent":"佐藤経理課長","answer":"ただ、事業者としましては、今回の事例もそうですけれども、各車ごとに考えるという形になっておりますので、この判決が出たのが大分前ですので、それに沿って車も選べるものもあるとＮＨＫの担当も言っておりましたけれども、オプション等でつける。","id":"exchange-015"},{"speaker":"塚本副委員長","kind":"確認","question":"最後に一つ確認で、では、仮にカーナビは内蔵していない車がオプションとしてあって、カーナビはつけません。職員とか庁舎が持っているスマホとかでカーナビの代用をしますというような場合は、それは契約の対象にならないということでよろしいですか。","respondent":"佐藤経理課長","answer":"あくまでもテレビの受信装置というところで、今回、受信料を払いますので、単純にカーナビであれば、スマホであっても同様だと思いますけれども、受信料は必要ないということになると思います。","id":"exchange-016"},{"speaker":"山本委員","kind":"質問・要望","question":"説明ありがとうございました。複数の自治体で同様なことが起こっていて、まさに見ていないで払っていると、自治体としては無駄な費用になってしまうということで、各自治体に共通した問題だと思うのですけれども、何か横の連携とかで国にこの法改正を求めるとか、そういった考えとか動きとかがあれば、お考えやその動向があれば、教えてください。","respondent":"佐藤経理課長","answer":"今年の全国市長会でも、同様に話題になったり議論されたりしているという報道もありますので、今後とも状況を注視していきたいと考えております。","id":"exchange-017"},{"speaker":"山本委員","kind":"質問","question":"状況は理解いたしました。東京都は本件に関してどれぐらい支払っているかというのをもし把握されていたら、教えてください。","respondent":"佐藤経理課長","answer":"東京都は、報道の内容ですけれども、５１８台対象になって約５,１００万円を支払うと聞いております。","id":"exchange-018"},{"speaker":"山本委員","kind":"質問・要望","question":"ご説明ありがとうございました。東京都も５,０００万円と割と大きな金額を払っていると思いますし、基礎自治体として共通する、何でしょう、使っていないとすれば無駄な支払いになってくるので、都区部として、改正がなされるような取組は情報を注視しながら、そういった機会があるときは、ぜひ積極的に連携していただきたいと思います。要望であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-05","title":"「品川区ジェンダー平等と性の多様性を尊重し合う社会を実現するための計画（素案）」に係るパブリックコメントの実施","agenda":"「品川区ジェンダー平等と性の多様性を尊重し合う社会を実現するための計画（素案）」に係るパブリックコメントの実施","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この計画の策定に向けて、私も可能な限り推進会議を傍聴しているのですけれども、毎回、積極的な、大変活発な議論がされていて、本当に品川区のジェンダーが前に進むなという感じが、会議を見ていても感じるのですけれども、それで、今回パブリックコメントということで、計画を策定していくためのパブリックコメントなので、多くの方からの意見がやはり必要になってくるだろうと思いますので、そして。","respondent":"木村人権・ジェンダー平等推進課長","answer":"推進計画について、パブリックコメントには多く皆さんにご意見をいただきたいと思っているところなのですけれども、特にご説明会というよりは、初日からＳＮＳ配信等で、パブリックコメントを実施していますというところを広く周知してまいりたいと思います。","id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ジェンダー講座に関しても、やはり興味関心がある人しか来ない、参加しない。やはりそこを乗り越えてこの条例をつくって、さらにそれを具体化していく計画なわけですから、今回もそういった様々な攻撃する意見や反対意見等も出てくる可能性もあると思うのです。それを具体化させる計画ということなのですけれども、そういう中でも少し困難があるとか、そういう部分があれば伺いたいと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"委員から言われたのは、これから進めていく上で困難な例がどのぐらいあるのかという話だと思いますけれども、今、世界的にこういったジェンダーに反するようなことですとか、先ほど説明の中にあったＤＥ＆Ｉなどに関することについては、世界的にバックラッシュというか。","id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"とはいえ、多くの方がこれを理解して進めていこうという立場に立っていくことが、そうしたバックラッシュをはねのける大きな力になると思いますので、ぜひ積極的に進めていただきたいですし、そのためのパブリックコメントだと思っていますので、改めて説明会等も少し要望しながら、進めていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問・要望","question":"理解もしています。だから品川区は、女性起業を取り立てて、いろいろなサポートをしてきたという経緯があるのですが、今はどうなのかな。子育て支援とは何だろうかといったときに、やはり親が子どもをしっかり見てほしいというのがあるのですよ。そこら辺は、今、入れろというわけにいかないと思うので、これから進める上で、その２点についてどう考えられるのかなと思いますが、いかがでしょうか。","respondent":"木村人権・ジェンダー平等推進課長","answer":"２つ目の子育て支援につきましては、今回、子育て支援の中に、幾つか父親向けの教室ですとか、そういうものも入っておりますけれども、今後は、両親ともに子育てしていける状態をつくるというところが必要になってくるかと思いますので、今回の計画は、条例もそうですけれども。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"それは家庭の中でいろいろやりくりしてもらえばいい話なのです。なので、そこは今後、考え方に入れていただきたいと思っていますので、これはいろいろな考えがあるかと思うので意見だけにしておきますけれども、ぜひ子どもを真ん中にというのはどういうことなのか、子育て支援というのはどういうことなのかということも含めて進めていただきたいと、要望をしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですが、区としてできる限りこういうことをどんどん進めていってほしいのと、あとは、今度、基本的な生活に困る人たちを何とか救済できるような、社会が安定するような施策を自治体として、国が本当は頑張らなければいけないのですが、駄目ならば区としてできる限りのことを私は推進して、こういうジェンダー平等というのを推進して、また取り組んでいっていただきたいと思います。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"山本委員","kind":"確認","question":"今回、５年の計画で、各項目で目標設定して、各年度で進捗確認をすることで理解いたしました。それぞれの項目の目標設定を細かく把握できているわけではないのですけれども、こういった姿勢というのはすごく評価しておりまして、目標値、この計画では５年後が示されているのですけれども、単年度の目標は、これには表記されていないものも、区としては設定していかれるのでしょうかというところです。","respondent":"木村人権・ジェンダー平等推進課長","answer":"ただ、今回から、指標につきましては、前の計画よりもかなり多く指標自体を設定しておりまして、これにつきましては、毎年の目標というよりは、毎年の結果をもって毎年評価をしていこうというところで、考えているところです。","id":"exchange-026"},{"speaker":"山本委員","kind":"質問","question":"ホームページで全部こういうものを、項目ごとに発表していくのでしょうか。","respondent":"木村人権・ジェンダー平等推進課長","answer":"ホームページにこちらの資料を掲載いたしますので、こちらを見ていただいて、パブリックコメントをいただくような形で考えております。","id":"exchange-027"},{"speaker":"山本委員","kind":"質問・要望","question":"追加での質問になりますけれども、サイドブックス２１ページ、素案の計画の１３ページですけれども、取組の方向性というところの中で、Ｉ－（１）－７とＩ－（１）－８で、それぞれ条例の認知度や人権尊重都市品川宣言の認知度というのを高めるということで、現況のパーセンテージから目標のパーセンテージまでを設定されていて。","respondent":"木村人権・ジェンダー平等推進課長","answer":"２つ目のところで、条例と宣言のものにつきましては、こちらは人権・ジェンダー平等に係る意識調査、今回、令和６年に実施しておりまして、５年ごとに実施をすることになっておりますので、この５年間の数値については、正確なものについては分からないというところになります。","id":"exchange-028"},{"speaker":"山本委員","kind":"質問・要望","question":"ご説明ありがとうございました。それに関してのご意見を伺いたいというのが１つと、あと、多くの方々にこの計画について知っていただくことがいいと思うのですけれども、区民の皆様にこの計画を、概要版とか、そういうふうに周知していくときに、何か分かりやすく説明していく手法とかお考え、概要版とかを作って説明していくご予定とかがあれば、教えていただければと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"２つ目の、計画を知ってもらうことが必要ですということになっているのですけれども、もちろんやる内容について広く区民の方々にご協力をいただかないと、この計画自体は進められませんので、こちらについては、ＳＮＳも含めて広く周知に努めていきたいと考えています。","id":"exchange-029"},{"speaker":"山本委員","kind":"質問・要望","question":"ご答弁ありがとうございました。ぜひお願いします。２つ目の点、ＳＮＳ等を通じて周知を進めていただきたいのですが、計画自体が１５０ページぐらいで結構量が多いものですから、区民の方に少しエッセンスを分かりやすく凝縮してお伝えいただくようなこともご検討いただければ、概要版とか、簡単に分かりやすく説明するということについても、ご検討いただければと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-06","title":"令和６年度マイセルフ品川プラン～誰もが自分らしく～推進状況評価の報告","agenda":"令和６年度マイセルフ品川プラン～誰もが自分らしく～推進状況評価の報告","exchanges":[{"speaker":"石田（ち）委員","kind":"意見","question":"今、マイセルフ品川プランの推進状況評価報告書ということで、この推進状況評価報告書ですが、今後、さっき説明いただいたジェンダー平等と性の多様性を尊重し合う社会を実現するための計画が策定された後というのは、このマイセルフ品川プランというのが一緒に……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうです、移行されるのかと、整合性、どういうふうになっていくのか、お聞きしたいと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"委員お尋ねのところは、今後、この新しい計画が策定された後、年来年４月以降に、同じような状況評価報告書が上がるのかというところだと思いますけれども、こちらについては毎年実施をしてまいります。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。そういう推進状況評価報告書、先ほど毎年出すとおっしゃっていたので、これも今回そういう感じで出ているのかなと思うのですが、マイセルフ品川プランという名前の計画、プランというのはなくなっていくということでいいのですか。","respondent":"木村人権・ジェンダー平等推進課長","answer":"令和７年度についてということなのですが、新しい計画は令和８年から実施ということになりますので、ただ、評価方法ですとか内容については今後検討していくところにはなりますけれども、今のところは、令和８年の評価報告書から。","id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"言うべきか言わぬべきか少し迷ったのですが、すごく、こういうふうに誰もが自分らしく、「区民一人ひとりが互いに人権を尊重しつつ責任を分かち合い」とありますが、これ、課長の説明で、まとめられたことには敬意を表しますが、区の企画経営部長、こういうのをどう思うのですか。実現できるのですか。それで、今日、女性の理事者の方もいらっしゃいますが、女性がそれをできるのかな。どうなのですか。","respondent":"柏原区長室長","answer":"最初からもうこれは無理だということではなくて、こういう世の中を品川区はつくっていくのだというのをお示ししたところでありますので、決して最初からできないものをつくっているというよりは。","id":"exchange-034"},{"speaker":"須貝委員","kind":"質問・要望","question":"課長からこういう報告書が出るではないですか、区でまとめて。こんなにできるなら、行政として掲げるのはいいのかもしれないですが、それだったら１人でも２人でも、区民を何か助けられる、支援できるような、私はそういう方向にやはりもっと力を……。でも、ここで今、これはこれで悪いことではないのですが、一応私としての考え方は、ここでしっかり述べさせていただきたいと思います。議論はしません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"なので、そういう感覚だったのですが、それは違いますか。だから、マイセルフが発展的にというのであればいいのですが、分からないではないのですが、急激にジェンダーのほうが始まるとなって、それを、結局は統合になることをやるということは、何か取っかかりが逆なのではないのと思っているのですが、どうなのですか。そうではないのですか。二重でやっていたことになりませんか、これ。どうなのですか。","respondent":"木村人権・ジェンダー平等推進課長","answer":"委員のおっしゃっているところの二重になるのではというところに関してですけれどマイセルフ品川プランから、次の品川区ジェンダー平等と性の多様性を尊重し合う社会を実現するための計画になるという形になりますので、二重になるというところは。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"それでやっていくということで、それで、本来は、このジェンダー平等の計画とかを出すときに、こっちになっていくよという説明をきちんとしていただければ、品川区のいろいろな事業の中に、全ての基礎となる１本こういう柱があってというのは分からないではないのですか。それは(4)のほうに関わってくるのですが、それは全然、そっちは両方同時にスタートしているのだと思う。分かりますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"どこを起点とするのか。ということは、では、どこが起点になるのかというのをまず確認したいのが１つです。会派が大きい、少ないにかかわらず議員は同じ立場であるのだから、あそこの会派に言って個人的には言わないとか、小会派には言わないとか、そういう差別的なことはやめていただきたいという、これは要望も含めて、そのお考えを確認させていただきたいということで、この２つをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"石田（秀）委員長","kind":"質問・要望","question":"私から一言だけ。その答弁のことは、私は、目的が違うのでと言ったのかどうか、その細かいことまでは覚えていないけれども、今そうおっしゃったからそうだったのかもしれないけれども、そこは必ず大切なことだと思っていたので、それは理事者の方にもご答弁はいただきたい。オープンの時間の話というのは、これは所管質問だから……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"一般質問に対する答弁は、私も確認を取っているので理解はしております。その上で、先ほどの答弁がよく分からないのですが、確認ですけれども、なぜか、議会側の、議員側の采配に任せるというようなことをおっしゃいましたよね、今。それはどういう意味なのでしょうか。そこを教えてください。それを間違えないようにしていただきたい。先ほどの答弁をもう少し説明していただけますか。","respondent":"與那嶺戦略広報課長","answer":"現在の取扱いといいますか、今年の補正予算でも様々なご説明をさせていただいているかと思うのですけれども、そこの部分の情報に関しては、プレス発表の前にご説明させていただいているというところで、そこからプレス発表までのところを。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"すみません。私も意味がよく分からないのですが、ということは何ですか、もう自由に議員たちは、私たちも含め、理事者もそうかと思うのですが、公開していいよという話ですか。では、区長が発表する前にそういう情報が得られたら、公開してよいということでの理解でいいですか。そうしたら、やりますよ、私ら。そういうことを意味しているのですか。もう一度答弁いただけますか。","respondent":"與那嶺戦略広報課長","answer":"いわゆる、自由に話してよいかどうかというところに関しては、こちらとしても、ある意味お願いと申しますか、どういった形で取り扱っていただくかというところは、そこはご判断に委ねるしかないのかなと考えています。","id":"exchange-041"},{"speaker":"西本委員","kind":"確認","question":"意見で言います。だから、区長のプレス発表は要らないではないですか、そういうことになったら。プレス発表は要らないのではないですか。それも、マスコミ側にも、これは朝日新聞だけですから、やっているのは。ほかのところはやっていないですよ、今回、この第２回定例会の報道はしかもデジタル配信ですから、もうばーんと出てしまうわけですよね。そこだけもう一度確認して、これは終わりたいと思います。","respondent":"與那嶺戦略広報課長","answer":"やってよいかどうかというご質問に対して、なかなか答えは難しいところではあるのですけれども、あくまでもこちらといたしましては、記者会見でプレスリリース、それが区として最も大きく世間に発表できるやり方、タイミングだとは思っております。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"質問をざっと言ってしまいます。それを教えてください。２つ目、相談内容などが区長、副区長、教育長に知られるような運用にしておりますか。実態はどうでしょうか。ハラスメントがなくなった、パワハラをやっていた人が、パワハラが少なくなった、改心した、職場の環境がよくなったというような、そういうのをどのように測っていくのかということを教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問・要望","question":"これは答弁がなかったのですが、双方の情報収集をして、いろいろ改善していくという方向なのですが、相手側、加害者の方にハラスメント認識がないという場合はどういう対応をされているかということで、応じないという方に対してどういう説得をして改善を求めていくのか、どういうことをされているのか、お聞きしたいと思っています。それから、研修は分かりました。これは要望したいと思います。","respondent":"宮尾人事課長","answer":"相談をされる中で、加害者というか、行為者とされる方の場合ですけれども、こちらは相談者の方が、ある程度行為者のほうにも何らかの働きかけ、アプローチをしてほしいという場合につきましては、基本的にはまず所属長に相談をさせていただいて、その方で、例えば。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問・要望","question":"やはりハラスメントのある職場だと、意識が低下してきます。仕事に対する意欲も低下するのは当たり前だと思うのですよね。これは社会でも一緒です。昔はきつく言って、俺の言うことに従えみたいな形で、それで通用したかもしれないけれども、もうそういう時代ではないので、やはり丁寧な、一人一人仕事が十分にできるような環境をぜひやっていただきたいと要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"須貝委員","kind":"質問","question":"こういうことになっているので、こういう行動は慎んでくれと言う段階で、そこで庁内で、やはり管理職である程度その人を特定できてしまうのではないのでしょうかね。何か民間だと、ほとんど民間の企業は関わらないで、もう弁護士がじかにその加害者の方に対して注意喚起をして、一切社内では何だかんだ、誰がどうだこうだというのを言わなくて動くような話も聞いています。","respondent":"宮尾人事課長","answer":"ですので、そういった意味で、例えば、その行為者の方だけピンポイントに言うのではなくて、その行為者の方がおられる所属全体に対して、所属長から何か注意喚起をしていただくとか、そういった本当に相談者が特定されないようなやり方で、日々模索、あるいは工夫をしながら。","id":"exchange-046"},{"speaker":"須貝委員","kind":"意見","question":"そういうときには、もし、必ずどなたか、人事課長が、今言ったとおり、区がどこかで介入してしまうと、知れてしまうと、もう注意は全くできないと思うので、それこそ直接弁護士からじかに、これはないと思いますが、区長とか副区長にじかにお話をできる、注意喚起をするという手法が取れるような仕組みというのをつくっておかないと、ある中間で止まってしまうのではないかという可能性。","respondent":"宮尾人事課長","answer":"ですので、どんな職層の職員でも、やはりそういったお悩み事があったら、私たちで真摯に受け止め、真摯に対応をして、しかるべき対策を取るべく、そして再発防止に努めていく、この考え方というのは一貫して常に持っているつもりです。","id":"exchange-047"}]},{"id":"topic-08","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"石田（秀）委員長","kind":"質問・要望","question":"予定表４の行政視察を行います。進め方につきましては、まず、私から視察先についての概要をお話しし、その後に視察先の質問や確認したい事項など、ご発言を願います。分配金は競馬事業の収益に応じて分配され、昨年度は１区当たり６億円となっております。視察先で特に質問や確認したい事項、ご要望等がございましたら、現地にてご発言をいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"山本委員","kind":"質問・要望","question":"沼田町自体は、今、ご説明いただいたような形で、品川区としてのおまつり等でのご接点とかもあるということなのですけれども、人口で見ると３,０００人弱というところで、決して多くはなく、品川区からも離れているというところで、私自身がいろいろな都市と交流を進めるべきだと思いながらも、今回、北海道のこの沼田町が視察先になるのが果たして妥当なのかというところでいうと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"山本委員","kind":"質問","question":"ご説明ありがとうございました。改めてになりますが、ご説明をお伺いできてよかったです。所管事務調査で競馬事業が選ばれていて、その中で、品川区として役に立つ視察先ということでばんえい競馬を選んだ。それで、そこから行ける先を選ばれたということで、理解いたしました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/121362?Template=document&Id=7187#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":51365,"voices":147}},{"id":"r07-20250925-21","meetingId":"r07-cm09","date":"2025年9月25日","dateIso":"2025-09-25","committee":"子ども若者支援・共生社会推進特別委員会","time":"午前１０時００分～午後 ２時４８分","status":"正式会議録","sourceType":"formal","overview":"子ども若者支援・共生社会推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"西村委員","kind":"質問・要望","question":"保育事業担当課長からもご質問がありました点で、５歳児健診の今後の進め方についてもご所見を伺えればと思うのですけれども、もちろん、保育園側からの視点ということでのご質問がありました中で園長先生でしたか、何が原因でほかの自治体ではトラブルになっているのですかというような率直なご質問もあって、すごくいいご質問を保育事業担当課長からいただいたなというふうに思っていますので。","respondent":"佐藤保育事業担当課長","answer":"次に５歳児健診の今後の進め方ですが、今年度、モデル実施を区のほうでも実施させていただいておりまして、１２の施設で今まさに実施しています。","id":"exchange-001"},{"speaker":"西村委員","kind":"質問・要望","question":"葛飾区の具体的な運用まで把握できていないのですが、もしご存じでしたら、今おっしゃった保育士さんの負担が自分たちがスクリーニング、判断に関わってしまっているというような心理的な負担をもしかしたら葛飾区が減らせるような運用をしているのかもしれないなというところで分かりかねますので、伺わせていただきたいなというふうに思うのと、あと。","respondent":"佐藤保育事業担当課長","answer":"葛飾区の方式の詳細については把握していないのですが、私の認識しているところで言いますと、心理士という、児童福祉心理司だと思うのですけれども、専門の方がそのようなスクリーニングに一定の関与をされているというのを記憶しています。","id":"exchange-002"},{"speaker":"西村委員","kind":"質問・要望","question":"私どもの会派の要望でもお伝えさせていただいているのですけれども、巡回相談のご報告も今あった中で品川区で無理のない５歳児健診の運用というのをぜひこれから進めていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところでのフォローの仕組みというのが私、すごく大事なのではないかなって、そのときにも申し上げたのですけれども、そのところについてなのですけれども、ご報告いただいた、区立保育園における特別支援保育の取組というところで、特別支援保育の知識・経験の豊富な保育士を中心に専門チームをつくって取組を進めているということで書かれているのですけれども。","respondent":"染谷保育施設運営課長","answer":"区立保育園における特別支援保育推進チームですけれども、こちらについては全ての園に設置をしております。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"やはりすごいこの発達障害についての保育園での取組だったりとか、保育士さんたちの研修だったりというのがここまで進んでいるのだなというので私は安心した思いがします。それから、嘱託医による巡回相談というのは、この実績のところで３５園で６８人ということなのですけれども、これは年１回の巡回相談ということになるのか、そこら辺の回数についても教えていただきたいと思います。","respondent":"佐藤保育事業担当課長、染谷保育施設運営課長","answer":"区で実施している研修にも私立保育園の職員も参加していただくことができますので、そのような研修を受けて特別な支援が必要なお子様に対応されていると考えております。こちらについて基本的には巡回をする中でお子さんの様子を心理士の方に見ていただいて、その後、カンファレンスをして担任の保育士等に助言等いただくというものになるのですけれども、１回について２名のお子さんを基本といたしまして。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうことで、研修というのは受けるという仕組みになっているのか、その点についてもお聞かせいただきたいと思います。","respondent":"染谷保育施設運営課長、佐藤保育事業担当課長","answer":"それに対する加配ですけれども、こちら、基本的には会計年度任用職員とそれから人材派遣の職員で構成されているものになりまして、会計年度任用職員についてもそれぞれ３時間、５時間。ただ、実人数と言いますと、午前中はこの先生、午後はこの先生というふうに変わる場合がありますので、なかなか把握することはできないのですけれども、基本的には１対１で保育についていただいているというような状況です。","id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そうすると、区立のほうも基本的に１対１でつくという、加配については１対１というふうなことで考え方でいいのか、その点を伺いたいと思います。そういう指摘がされた方のフォローと合わせてそういう受皿という問題が出てくると思うのですけれども、そこのところが求められていると思うのですけれども、その点に対してはどのようにされていくのかということについても伺います。","respondent":"染谷保育施設運営課長","answer":"当然ながら、例えば、環境刺激だとか、情報処理が難しく、集団の中に１人置いておくというのがなかなか難しいお子さんがいる場合につきましては、その加配の職員が対応するというところはあるかと思うのですけれども、基本的な品川区の公立の保育園の考え方としましては。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうことに対してしっかりと、診断はされたけれども、必要なサービスが受けられないということがないようにしっかりと受皿をつくるという点では取組を進めていただきたいということでお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"澤田委員","kind":"質問・要望","question":"私からはまず伺いたいことが、保護者の発達障害への理解についてですが、現在、保育園のほうではどのような取組を行っているとか、もしあれば教えていただきたいです。","respondent":"染谷保育施設運営課長","answer":"その中で様々ご相談をお受けするのですけれども、お子さんの育ちに関する部分ですとか、あと、お子さんの行動に関して困っているというようなご相談、この２つが全体の相談の大半を占めているというような状況ですので。","id":"exchange-009"},{"speaker":"澤田委員","kind":"質問","question":"私の質問の仕方が悪くて申し訳ないのですけれども、発達障害というものに対しての理解というか、啓発というか、まずそもそも育てにくいとか、いろいろなことがある中で相談して、「あ、もしかしてそうなのかも」というふうな形で気づかれる方も多いと思うのですけれども、そもそも発達障害がどんなものか、どんな種類があるのか。","respondent":"染谷保育施設運営課長","answer":"先ほどの育児相談会につきましても、相談を受ける相談員については臨床心理士ですので、そこの中でそういった発達の特性に関するご相談というのはお受けすることはあると思いますし、あと、各園におきましてもそういう中で先ほど申し上げたとおり。","id":"exchange-010"},{"speaker":"澤田委員","kind":"質問","question":"先ほどの視察の中で、保育園で巡回相談を各園で行っていて、これって小学校での特別支援教室の拠点校があって、それでやはりいろいろな学校を回っておられると思うのですけれども、それと保育園も同じような形でやっていて先生方を支援したりというところだと思うのですけれども、今後、児童発達支援施設を併設していくような園というもの、それはいわゆる拠点校に近い形になると思うのですけれども。","respondent":"染谷保育施設運営課長","answer":"先ほど少し説明の中で触れさせていただいた、実際に、特別支援児童として区のほうで認定させていただいているうちに療育施設の利用実績のあるお子さんがそれぞれ令和７年で４８人で、令和６年度４３人といらっしゃるというような現状におきましても、保育所と訪問支援ですとか。","id":"exchange-011"},{"speaker":"おぎの委員","kind":"質問・要望","question":"個人情報ですので、扱いが難しい部分もあるとは思いますが、子育てで悩んだお母さんがやはり心のよりどころであったりとか、一緒に子育てを考えてもらえる、そういった一体化したといいますか、子育てに関して保育園からスムーズに小学校と子育てできるように、先ほどのところでは卒業後もまた連携はなるべく取るようにしていきますとおっしゃっていただきましたけれども。","respondent":"染谷保育施設運営課長","answer":"現状、教育相談、中学相談に教育総合支援センター、教育委員会のほうで実施しているほうに行かれるお子さんに関しては保育施設運営課にお子さんの様子を確認するための実態把握表のようなものの提出の依頼がありまして、その中で実際にそのお子さんの現状。","id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問","question":"医療的ケアの必要性なのですけれども、医療的ケアのお子さんを保育園で受け入れるということになって、どんどんその中身というのも充実をしてきていると思うのですけれども、今、どの程度までの医療的ケアのお子さん、医療的ケア児の保育園入園に関するガイドラインというのを見せていただいたのですけれども、痰の吸引、経管栄養、それからインシュリン注射、それから導尿、在宅酸素療法、ネプライザー。","respondent":"染谷保育施設運営課長","answer":"医療的ケア児、ケアの必要なお子さんの受入れに関しましては、今、委員がおっしゃられたような形で対応する医療的なケアについてを令和５年から大きく拡充いたしまして、それまでは痰吸引と経管栄養というところだったものについて、今、委員がおっしゃられた酸素療法ですとか。","id":"exchange-013"},{"speaker":"鈴木委員","kind":"意見","question":"本当に令和５年からさらに拡充をしていただいて、ここまで保育園でも、学校でもそういう対応をしていただけるようになってきていると思うのですけれども、医療的ケアの子どもさんに対してはかなり通える条件というか、そういうのを整えていただいているなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"つる委員","kind":"確認","question":"今日、先ほどの西村委員の質疑で確認があって、品川区内では、午前中視察させていただいたようなことについても、児童発達支援施設が併設されているところは１施設ということであったのですけれども、傾向としてそうした対応が必要なことが今増えてきているという状況がある中で、その上で就学前人口のがピークの人口動向の就学前の人口のピークの話もこの委員会の中でもあったり、ただ。","respondent":"佐藤障害者施策推進課長","answer":"児童発達支援事業所の施設の基準のご質問というところで……。","id":"exchange-015"},{"speaker":"つる委員","kind":"質問","question":"すみません。分かりづらくて。当然、受け入れられる人数にもよると思いますし、今日のところも外部というか、人数の部分で成り立つ、成り立たないというところもあると思うのですけれども、そういう意味でどのぐらいの広さというか、スペースがあれば、できるのかな、そこが分かれば教えてください。","respondent":"佐藤障害者施策推進課長","answer":"児童発達支援は、お子様１人当たりで中心となる発達支援を行うお部屋において、１人当たり２.４７m2以上の床面積というような形で基準が示されておりますので、例えば、先ほどおっしゃっていた定員、例えば、１０名に対して掛けるというようなところになります。","id":"exchange-016"},{"speaker":"つる委員","kind":"意見","question":"何人、始めたのが何年ぐらい経っているかというのによると思うのですけれども、当然、改修できて分岐点を超えて、事業者としても利益が出るような形になっていれば、いいなとは思うのですけれども、ただ、一方で、そういう就学前の子どもたちのニーズに合わせた、また、保護者のニーズにも合わせた施設のあり方って。","respondent":"染谷保育施設運営課長","answer":"今日、午前中に視察いただいた保育園につきましても、もともとある定員を落とした中でああいった余剰スペースを生み出して併設の園にしているというような考え方となっておりますので、今後、区立の園で定員の見直しを図った場合において。","id":"exchange-017"},{"speaker":"つる委員","kind":"質問","question":"何ていうのでしょう、「いやいや、もうそういう感じで当然いいのだ」とか、「今の形でずっと別々でやっていくほうがいいのだ」とか、いろいろあると思うのですけれども、それは制度上とか、どうだってあると思うのですけれども、その辺り、今お答えいただいたとおりだと思うのですけれども、何かまたあれば、ぜひ教えてください。","respondent":"佐藤子ども未来部長","answer":"今日、ご見学していただいた、いわゆる複合施設のあり方ですが、一応法律上、縦割りになっていまして、今日は所管の課長にも来てもらっているというのが現状ですが、区としては計画している公共施設等整備総合計画というのにも明記してありますけれど、施設を改築であったり。","id":"exchange-018"},{"speaker":"ゆきた副委員長","kind":"質問","question":"特別支援保育審査会で面接の入園審査というところ、特別支援保育審査会では保育施設運営課長も構成員の中に入っているので、面接とか、入園希望者の審査のところで申込みするというのは大体把握されていると思うので、この辺と、あと、令和６年度のモデル園において受入れを実施するとしている私立保育園では現段階でどういうふうになっているのかというのも含めてお聞きできればと思います。","respondent":"染谷保育施設運営課長","answer":"医療的ケア児につきまして、先ほど申し上げたとおり、令和７年度の現時点において１２名のお子さんの受入れをしていますけれども、先ほど申し上げたとおり、実際に、品川区におきましては、０歳児園での受入れというのを基本にしておりますので。","id":"exchange-019"},{"speaker":"ゆきた副委員長","kind":"質問","question":"私立保育園での医療的ケア児の受入れのそこの現段階を教えてください。","respondent":"佐藤保育事業担当課長","answer":"しかし、区としては私立保育園を希望される方がいらっしゃったときのために各園に研修、医療的ケア児を受け入れる際の研修に対する補助というのを補助メニューとして持っているところでございまして、昨年度は１園、今年度も１園、研修の予定となっております。","id":"exchange-020"},{"speaker":"ゆきた副委員長","kind":"質問","question":"先ほどの中で受入れは三十数園、受入れの可能な状態というのはお聞きしましたけれども、申請自体はどのぐらいあるのかというようなところをもう一度お願いします。","respondent":"染谷保育施設運営課長","answer":"現状におきましてガイドラインで示している医療的ケアで対応が可能な項目に該当するお子さんについては原則、特別支援保育審査会の中で受入れをしているという状況にありますので、区的に申請数が、申し訳ありません。","id":"exchange-021"},{"speaker":"ゆきた副委員長","kind":"質問","question":"今後、受入れをさらに拡充していくとしても、私立・区立含めて看護師の加配とか、専門的な研修に要する費用の予算も関係してくると思うのですけれども、今後、必要性に合わせて方向性についてお聞きできればと思います。","respondent":"染谷保育施設運営課長、佐藤保育事業担当課長","answer":"令和５年度におきまして痰吸引、経管栄養以外にもインシュリン注射ですとか、先ほども申し上げた大幅に医療的ケアの項目のほうは拡充をさせていただいておりまして。さらに医療的ケアの児童の受入れの拡大のために、昨年度から先ほどお話しさせていただいたような医療的ケア児を受け入れるための研修。","id":"exchange-022"},{"speaker":"ゆきた副委員長","kind":"質問・要望","question":"医療的ケア児の保育園入園に関するガイドラインも私も見させていただきましたが、１名の医療的ケア児を受け入れるのに受入れの園の体制の準備とそれぞれの役割の相当な業務があると感じられます。様々な課題がある中ですが、より一層医療的ケア児の受入れを進めていただければと思いますので、こちらは要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"西村委員","kind":"提案","question":"その中で区と何度も相談をしながら、今の児童発達支援施設に至ったというふうに伺っておりまして、今回、保育園のあり方、どうしていくのかというのが議論の主だったと思いますので、今回は私立園が自ら認可園が独自の判断でこのような方法はどうかと区にご提案したものと思っているのですけれども。","respondent":"芝野保育入園調整課長","answer":"公私の役割分担、こちらも引き続き、今もしっかりやらせていただいておりますが、引き続き公私のバランスというか、役割分担につきましてもしっかり検討してまいりたいというふうに考えております。","id":"exchange-024"},{"speaker":"西村委員","kind":"質問・要望","question":"ありがとうございました。私立園に関してはお任せしている部分もありまして、また区立園とは違う課題もあるかと思うのですけれども、区が主導でぜひ引っ張っていっていただきたいという思いで質問させていただきましたので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"せお委員長","kind":"質問","question":"ないようでしたら、私から１点ご質問します。","respondent":"芝野保育入園調整課長","answer":"今後の複合施設の考え方ですね、こちらについては企画課のほうでしっかりと、こういう跡地、これからいろいろ出てきますので、そちらのほうが出た段階で企画課のほうでしっかりとあり方は検討させていただきたいですが、保育のほうについても、しっかりと声を届けまして。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/170663?Template=document&Id=7189#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=21&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":23895,"voices":66}},{"id":"r07-20250925-20","meetingId":"r07-cm09","date":"2025年9月25日","dateIso":"2025-09-25","committee":"ＳＤＧｓ推進・行財政改革特別委員会","time":"午前１０時００分～午後 １時５１分","status":"正式会議録","sourceType":"formal","overview":"ＳＤＧｓ推進・行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"あくつ委員","kind":"提案","question":"だから、それに関して、そこの子どもの発想を、そのまま純粋に聞いた感じというのは、そこがどう担保されているのかというところが少しあったので、例えば、この１０番目の子ども食堂に関するテーマ、私、これは時間がなくて拝聴していないのですけれども、ここについては、子ども食堂の代表的な関係者と、その提案者とかの方たちは、意見交換はされたのですか。そこについても含めて教えてください。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"あくまで、これは区長に対して、中高生それぞれの地域課題、社会課題に対する問題意識からの提言でございまして、この後、所管課と、そこでも少しリバースメンターには関与してもらうことを考えているのですけども、それが区として。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"提案","question":"繰り返しになりますけれども、フォローするわけではないですが、すばらしいプレゼンだったがゆえに、逆に、さっき言った、子どもの能力を私が甘く見ていたのかもしれませんけれども、すばらしい提案だったがゆえに、大人の意図が入り込んでいたら困るというところでの質問、先ほどの意図ですので、それではないということでの今のご答弁だと思いますので、承知いたしました。一旦切ります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"リバースメンターということなので、流れでお伺いしたいのですが、一昨年、私は文教委員だったのです。ぜひ継続・発展させていただきたいと思います。これは、それぞれのテーマに沿った、それぞれの専門家という意味なのかを伺いたいのと、あと、１０名の方が提言されたのですが、今の時代、男女というのもどうかと思いますが、１つの客観的な事実として、中高生とか男女の比率はどうだったのか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"当初は、それぞれのテーマの専門家に入っていただくことも検討したのですけれども、本当に、ご覧のとおりテーマが、十人十色のテーマでございましたので、今回関わっていただきました専門家につきましては、国の政策を立案するような、例えば財務省ですとか、内閣官房ですとか。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"目的自体が、やはり社会を変える実感を持つということによって、社会の担い手を広げていくということでありますので、すごく今、日本の社会にとって大事なことだと思って、それを、かなり惜しみもなく人材を、ありとあらゆるつてなども活かしつつ、丁寧にやっているというのはすごいと思いまして、お知らせも相当な規模で広くやっていると思ったのですが、１６名というのは若干少ないと思うのですが、ただ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"新妻委員","kind":"質問","question":"お伺いしたいのが、今回、皆さん、それぞれテーマが本当にすばらしいと思ったのですけれども、１６人の応募の中でプレゼンテーションをした上で、この１０人に絞られて、今回この１０名が発表しているテーマというのが、最初にプレゼンをされたときのテーマなのか、それとも、委嘱式が終わって、検討会が４回行われる中で、それぞれテーマを皆さんがつくり上げてきたのか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今回、区立学校の方からのリバースメンターの応募が少なかったというところなのですけれども、応募に当たっては、区立学校の方から１名ご応募があったのですが、残念ながら選ばれず、結果的に区立の中学校からリバースメンター。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"最終的には、今後のスケジュールとして、９月以降に事業化へ向けた検討実施とありますが、全てがこのままということでもないというお話もありましたが、今後これが事業化になったとき、１０テーマありますけれども、テーマを挙げてくださった方々への返しといいますか、何かそこでまたイベント的なことがあるのかとか、もう少し今後の流れを教えていただきたいと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"ですので、そこで、来年度予算だったり、それ以降だったり、事業化される提案も、それ以外の提案も含めて、区での検討がどのようになされて、できない事業であれば、なぜそれが困難なのかといったこともきちんとフィードバックをすることによって、先ほど。","id":"exchange-006"},{"speaker":"新妻委員","kind":"提案","question":"すごく大事な視点だと思います。できること、できないこともあると思いますし、そのことをしっかりと、今回提案をいただいた皆様にお伝えいただくということは非常に大事なことですし、また、できなかった、選ばれなかった方たちにとっても、今後はこういう視点でまた見返して、こういう方法でというようにもつながっていくとも考えられますので、引き続きよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"こしば委員","kind":"質問","question":"今後、本当に純粋な気持ちでテーマを立てて、自分たちで研究して、いろいろな声を拾い上げていって、そういう中で、今後事業化するに当たって、当然、その地域との兼ね合いもありますので、協議体のようなものとの意見交換、調整がどうしても必要になってくると思うのですけれども、その辺りのスケジュール、そこまではないかもしれないですが、考えについて教えていただければと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今後、各所管にて事業化の検討を進めてまいる中で、中高生リバースメンター、当日のプレゼンテーションは３分間だけでございましたので、本人が、委員から先ほどご紹介があったようなアンケートを使った調査の内容なども資料として提出、所管と確認しながら。","id":"exchange-008"},{"speaker":"こしば委員","kind":"質問・要望","question":"ぜひ、その辺、地域の未来に関わってくるわけですので、それが場合によっては、地域で活動する団体の声がまた大きくなってしまうと、それは本来の趣旨にもまた外れていってしまいかねないのですけれども、そこはぬかりなく、調整して進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"提案","question":"さっき新妻委員のやり取りの中で、今回、十数名の方が応募をされて、１０名の方が６００字の作文で選ばれたという話の中で、提言テーマの１番目のところで、かなり具体的な内容の記載があるのです。これは６００字の作文の中に、もう既にこういう提案が入っていたのかどうか。要するに、もう最初からこういうご提案だったということなのかどうか、確認させていただいてもいいですか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"リバースメンターからの提案のうち、１番目の選挙に関する、投票率９割超という提案に関するご質問です。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"提案","question":"子どもが言っていることだからやりました、事業提案しましたということになってしまうと、ごめんなさい、こんな意図はないと思うのですが、やはり子どものものを利用したということになりかねないので、それはないということなのでしょうけれども、そこのところだけはないということを確認させてください。","respondent":"久保田企画経営部長","answer":"子どもたちが一生懸命考えていく中で、いろいろなアドバイスを受けながら、また、自分で取材をしていく中で、考え、至ったものと我々は認識していますし、そういったことでありますから、事業化できるものは事業化はしていきたいと思っていますし、事業化できないものも。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"部長からは今、そういったことはありませんという明言をいただきました。それはそれとして受け止めたいと思います。ただ、先ほど申し上げたように、政治というのは、特にこの選挙という部分に関して、ほかもそうですけれども、かなりセンシティブなものを含んでいます。そういうところはきちんと配慮した上での予算の編成はしっかり行っていただきたいということは最後に申し上げておきます。","respondent":"久保田企画経営部長","answer":"我々もその辺については、委員のご指摘を踏まえまして、しっかりと肝に銘じで対応していきたいと考えております。どうぞよろしくお願いいたします。","id":"exchange-012"},{"speaker":"まつざわ委員","kind":"提案","question":"私も少し気になったのは、新妻委員の質疑で分かったのですけれども、やはりせっかくこういった、例えば、今お話しのこどもせんきょの運営方法というのは、出したその子どもが分かっていることであって、そういうのをやはり追っていかないと、本当に提案者はどういう意図があるのかというのが分からないと思っていたので、区長に、会う予定というのは、あと１回でしたか、これは今後の流れではなく。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"現在、区のホームページでも中高生リバースメンター事業について、検討会の経緯などについて写真とともに掲載をしておりますので、そういった点も今後、見ていただけるようなことを検討してまいりたいと考えております。","id":"exchange-013"},{"speaker":"山本委員","kind":"提案","question":"幾つかご質問をさせていただきたいのですけれども、これまでの質疑の中で、今回の募集の中で、区立学校の方が１名、あとは私立の方だということだったのですが、これ、ぜひ区立中学の人にもたくさん応募してもらいたい、参加してもらいたいという思いからなのですけれども、私立中高では、今回のこういった企画があるから、みんなで応募してみようみたいな、学校の中での働きかけとか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今後、事業に反映されたかどうかについて、委員の皆様、それから周知の点につきましては、きちんと公表できるように、今後、見せ方等の検討を進めてまいりたいと考えております。","id":"exchange-014"},{"speaker":"山本委員","kind":"提案","question":"今回、検討会の２回目のときに、群馬県の先輩リバースメンターによる体験談というのがあったと思うのですけれども、来年以降は、今回の参加した人による体験談ということをしていくことで、先輩、後輩のリバースメンターのつながりとかもできてくると思いますし、ぜひ継続していく中で、１回やって終わりではなくて、参加した方々にも引き続き関係を持ってもらって、この品川区政に政策提案。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"前回、委員からご紹介ございましたように、第１回の検討会ですが、群馬県高校生リバースメンター事業をやって、そこでリバースメンターとして経験した方が、今、大学生になって、そういう方に説明をしてもらう機会がございましたので。","id":"exchange-015"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ウェルビーイングもあって、ファンドの状況を見ました。それで、審査に関しては、８事業の中の６事業が一次審査、二次審査が、このまま６事業全部入ってしまったわけです。見るとＡＩ、ＧＸという部分がすごくあって、私はよく分からないのですが、ＡＩ、ＧＸというのは専門的なものがすごく多い中で、これを審査する専門員がいるのでしょうか。そこの確認をお願いします。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"そちらは全て６０点に満たなかったですが、今年度も審査基準にのっとって、各審査員につきましては、プレゼンテーション事業者に対して、かなり厳しい、例えば助成が終了した後の事業収益性などについても厳しく質問がなされたところですので、審査につきましては、昨年同様。","id":"exchange-016"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"何社かあったのですけれども、そうすると、公金納付の目的というものと、アプリの開発などは自己資金でやるものという、利益追求、この線引きを、果たしてどのように審査したのかというのが１点と、例えば、株式会社タンソーマンＧＸのこのＡＩ電気相談コーナー、いろいろ調べていると、民間でも、そういう電気の相談があると、そうすると、そういうほかの企業のＡＩ電気相談があるにもかかわらず。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"２年目の５番目、６番目、株式会社ラヴィプラスですとか一般社団法人めぐもりという事業者からの提案でございまして、昨年度と事業内容が類似しているのではないかですが、こちらは本事業のスキームとしまして、２年目までは同じ事業で継続して応募ができる。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"提案","question":"もう１つ大きなところで言えば、これも、前回も同じような質問をしましたけれども、監事の方の意見が前回出ていて、その３つの意見が付されていたと思うのですが、そこについては、今回どのようにそれを反映、この２回目の選定に当たっては反映をされたのかということで、１番目は簡単に言ってしまうと、既存の事業との類似性を確認した上でやってくださいとあったと思うのですが。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"こちらにつきましても、実施スケジュールを各選定事業の方には、３か月前をめどに、あるいは決まり次第、事務局にお知らせいただくようにと周知してお願いをしていまして、イベント等、規模や対象の方などにもよってはまいりますが、委員の方にも視察をしていただけるように。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問","question":"いろいろ深掘りしたいことはあるのですが、時間も時間なので、私が疑問に思ったことを今、漏れなくお答えいただきました。より、何というのですか、先ほど申し上げたとおり、今回の採択事業がかなり専門性も高い形で、ヒットが出そうな予感もありますし、そうすれば、また、相乗効果が出て、資金なども集まりやすくなると思います。この事業自体は成功してほしいと思っていますので、私からは以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回６つの団体ですけれども、資料の６の申請できる企業・団体等と分類があると思うのですが、それぞれ幾つぐらいずつなのか教えていただきたい。スタートアップ企業は幾つ、中小企業は幾つ、その他法人は幾つなのか伺いたいと思います。助成金の額の決め方について、事業費と助成金と書いていますが、こちらについてはどのように決まっているのか伺います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"大きく３点、ご質問をいただきました。資料の１枚目の右側です。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。それと、スタートアップが多かったということですけれども、今回６つのうち５つが株式会社で、なかなか次年度以降の継続は、収益化を目的にしないとなかなか厳しいだろうというのがありまして、実際上、企業以外の参入が困難な事業スケールになっているのではないかと思ってしまうのですが、その点はどのようにお考えでしょうかというのが２点目です。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"改めまして、３点、ご質問をいただきましたのでお答えしてまいります。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"今後もよろしくお願いします。だから株式会社ですとか、それ以外のＮＰＯですとか、社会福祉法人とか、そういうところとは切り分けて、３年目以降のスキームを考えてもいいと思いまして、目的を達成する意味では、そうしたこともあるのと私は感じましたということで、意見で終らせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"筒井委員","kind":"確認","question":"先ほども話題になったのですけれども、「投票率９割超、積極的な政治参画が当たり前の社会に」ということで、私もそのとおりだと考えておりますが、一方、公職選挙法上の問題とかが、先ほどあるという話だったのですけれども、そうした法令上の問題は様々な、今まで６月から８月にかけて、所管に質問や相談をしながらとかあったのですが、そうした法令上の問題は。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"中高生リバースメンター事業の提言の１つ目、こどもせんきょに関する提案についてのご質問です。もちろん、本人、それから所管から公職選挙法上の説明だとか、本人も調べて、例えば１８歳未満の選挙運動が禁止されているですとか、投票日当日の選挙活動は禁止されてあります。","id":"exchange-023"},{"speaker":"筒井委員","kind":"提案","question":"先ほど、あくつ委員からもお話が出たように、政治的というのはセンシティブなものであって、提案としてなかった品川区長選挙とかが盛り込まれるというのはなぜか、単純に疑問に思ってしまうところでもありますけれども、そうしたいろいろな問題を抱えている中、これ、そのまま事業化ありきではないという話なのですが、かなり課題が多いと思うのですけれども、一方、私としては。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"ただ、その過程においても、区でできることはここだからこういうように意見を曲げてほしいと、区がそのように誘導することは決してしないようにしたいと思いますので、中高生が本当にやりたいこと、目指したい世界はどういうところで。","id":"exchange-024"},{"speaker":"筒井委員","kind":"提案","question":"（４）番の先駆性、新しい視点、アイデアなどが含まれており、また、専門性や強みを活かした事業というのがあって、これが必須になるわけだと思うのですけれども、今回、新規の事業は、様々、別の委員からもご指摘がありましたが、比較的スタートアップで、ＡＩとかアプリとか、そうした比較的科学的なもの、また、データ測定とか客観的なものになって、結構いい事業と考えておりますけれども、１年目からの。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"本審議の中でも、審査の視点としまして、区内全域に発展性として考えられるのかといった視点での質問などもなされておりまして、実際、一般社団法人めぐもりにつきましては、昨年の実績を踏まえて複数のほかの地域の団体とのつながりができて。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問・要望","question":"審査基準の点を出さない、非公表ということなのですけれども、それは先ほど安藤委員からもご質問がありましたが、品川区、ほかの所管で、指定管理者を認めるか否かのところで、点数とかは、それはさすがに公表しているので、今、一般社団法人めぐもりと株式会社ラヴィプラスのイベント系の２団体については、審査基準の成果はどのように評価されているのかも気になりますので。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"審査結果、審査点数ですとか各項目の内訳等の審査、点数の公表についてですが、こちらもやはり委員の自由闊達な、民間の多様性を踏まえた意見、率直な意見の審議の内容などができるように、一定内容については公表しないとしておりますが、実行委員会でも。","id":"exchange-026"},{"speaker":"山本委員","kind":"質問","question":"私からも１点、ご質問します。今回、成果のところ、これまでもお話の中で、客観的に分かる、具体手的な定量的な成果が分かったほうがいいと、そういう目標設定があったほうがいいというお話もあって、適切なＫＰＩ、指標を設定してもらうということで話が進んでいたと思います。今回、それぞれの事業者では、どのような成果目標を設定されているのかお伺いしてもよろしいでしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"各事業を、例を挙げてご説明しますと、例えば１事業目の株式会社タンソーマンＧＸにつきましては、例えば６か月の実証の間で１００社以上の利用、そして累計５,０００ｔ－ＣＯ２の削減の提案。","id":"exchange-027"},{"speaker":"山本委員","kind":"質問・要望","question":"具体的な定量的な目標設定にできるだけなるように設定されているということで理解しました。今日お聞きしなかったところも、定量的に目標設定いただいているということで、それが妥当かどうかも、もう少し聞いて見ていかないと分からないですけれども、ぜひ、そういう見える形で、成果をまず、目標を決めていただいて進めていただくというのがよいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"こしば委員","kind":"質問・要望","question":"先ほど筒井委員からも話が出たのですけれども、そもそもＳＤＧｓのファンド事業の選定に当たっては、分野が多岐にわたっていまして、まず、確認ですが、この予算の出どころ、予算処理のときに、これは企画課から出るものなのか、それとも中に入ってくる、要は、内訳を見ると、子ども未来部だったりとか地域活動課に関わってきたりもするので、それがまた細分化されていくのか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"助成金額、予算書の記載の仕方ですが、まず、前提といたしまして、本事業につきましては、区の主体となっているのはウェルビーイング・ＳＤＧｓ推進事業実行委員会ですので、区の予算書の中には、令和６年度の当初予算として。","id":"exchange-029"},{"speaker":"こしば委員","kind":"質問・要望","question":"手が挙がるのは別に悪くはないと思うのですけれども、そもそもこの一般社団法人めぐもりの団体自体がそこまで、品川区全体にわたって活動を展開していく体力があるのかどうかは分からないですし、正直そこまでないと思うのですが、その辺はどのようにお考えなのか、また、今後どういう見通しをつけているのか教えていただきたいと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"なので、あらかじめ、これは地域産業振興課の事業だから提案できませんとか、そういった線引きは、今のところはこちらで線引きをするようなことは考えていないのですけれども、今後、もしそういうご指摘等ございましたら、その辺りも含めて検討してまいりたいと思います。","id":"exchange-030"},{"speaker":"こしば委員","kind":"質問・要望","question":"ぜひ、そこは共有といいますか、調整していただきたいと思います。ややもすると独り歩きしてしまって、それがひいては、地域の中での何か交流の分断にもつながってくると、それは本来の趣旨と全くかけ離れていってしまうので、そこは調整、共有をしていただきたいと思います。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"もう１つ、最終的に、この評価が決まっていくと思うのですが、これを決算特別委員会に間に合わせることはできないのでしょうか。なぜ今は空白になっているのでしょうかというのをお伺いしたいのと、その評価の基準なのですが、最終的にはＡからＤになると思うのですけれども、評価の基準、何をもってＡからＤを決めるのか伺います。","respondent":"吉岡政策推進担当課長","answer":"評価の基準ですが、やはりいろいろな福祉施策、まちづくり施策、防災施策、捉える基準が少し異なりますので、一律にではないのですけれども、将来的な行政需要が高い、重点的に実施すべきものがあれば、そういったＡに近い評価にもなりますし、逆に、法定受託事務。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、評価が現在はないというのは、間に合う、間に合わない話ではないという、よく理解できました。それと、何をもってＡからＤですが、様々、この評価シートの中に書いている内容について、項目についてご説明を冒頭にいただいたのですが、もう少し、どの辺を重要視して決めるとか、先ほど説明いただいた項目に基づいて何か評価基準ですか、もう一度説明いただきたいと思います。これは質問です。","respondent":"吉岡政策推進担当課長","answer":"一方で、なかなかこういった課題が解決できない、あるいは、役割に応じていないというところであれば、そこがＤ評価につながっていくと考えています。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"考え方は分かりました。政策委員ですけれども、１１名いらっしゃるのですが、区内在学者２名と区民の方３名ということで、この公募のやり方なのですけれども、どのようにやっているのか伺います。それと、区内関係団体の方が３人、選定されていると思うのですけれども、この選定の考え方も伺います。原則公開となっておりましたけれども、伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"開催の仕方についてですけれども、今、政策評価委員会、１回から５回までございまして、１回、２回が事前検討会で、こちらは事業をしっかりと知っていただく、基本的なものも質問していただく、闊達な議論をしていただくというところで。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。テーマによって、関係団体ですとか、あるいは公募区民を、毎年変えているということと理解したのですけれども、そういうことでいいのかという確認と、それと、この事務事業評価と政策評価ですが、この政策評価は１１月に昨年、提言を受けて、今年も同時期に提言になると思うのですけれども、区は、この評価委員会の評価、提言を、新年度予算にどのように反映する方針を持っているのか伺いたい。","respondent":"吉岡政策推進担当課長","answer":"政策評価委員のメンバーのことと、あと予算編成に関連するお話をいただきましたけれども、まず、メンバーですが、学識経験者の委員長、副委員長、１名ずつにつきましては、政策評価あるいは行政評価について明るい方で、こちらは固定でお願いしたところですけれども。","id":"exchange-035"},{"speaker":"新妻委員","kind":"質問","question":"行政評価につきまして、森澤区長が公約として掲げて始まった、この事業と思います。今年３年目でよろしいでしょうか。令和５年から始まって、令和５年は令和４年度の事業、そして令和６年、令和７年と３年目かと思います。この３年を迎えた、まず、区の評価と、やった上でのよかったこと、また、課題、職員の負担等も含めた評価をお聞きしたいと思います。","respondent":"吉岡政策推進担当課長","answer":"よかったことは、やはり今までも、この事務事業評価、行政評価を行っていなくても、いわゆる事業実施の中で、あるいは予算要求、予算編成の中で、事業はしっかり見直してきところですけれども、こういった１つのシートとして見える化をしたことによって、議会の皆さん。","id":"exchange-036"},{"speaker":"新妻委員","kind":"質問・要望","question":"新年度のときに、それぞれが新年度でスタートをするので、同時にその予算を使えないという歯がゆいところもあるのだろうと思うのですけれども、今後、国の予算や東京都の予算の、そこをより多く活用するためには、どういうことが必要なのかという区のお考えがあれば教えていただきたいと思います。","respondent":"吉岡政策推進担当課長","answer":"やはりこういった予算がついていないところに関しては、所管だけでなくて、こういった企画財政部門でもこういったものが使えないかというところをコミュニケーション、国ですとか都と取っていく必要があるとは認識をしています。","id":"exchange-037"},{"speaker":"新妻委員","kind":"質問・要望","question":"最後に、評価委員会の委員についてお聞きしたいのですが、今、ご説明がありましたとおりですけれども、この中で、大学生や公募区民の方が入っております。公募区民の方は公募だと思うのですけれども、大学生に関しては、どういう形で入っていただいているのかを教えていただきたいと思います。","respondent":"吉岡政策推進担当課長","answer":"教授に、学部の中で、こういったいわゆる行政評価あるいは行政に興味のある方に、ご推薦をいただくという形で、男性１名、女性１名の選出をいただいたです。","id":"exchange-038"},{"speaker":"新妻委員","kind":"質問","question":"そういう知見のある大学生が入っているということで、しっかり、これ、この方たちが、若い目線での発言をいただくことがすごく大事かと思うのです。名前だけ載せているということではなくて。区の予算の在り方について、若い方たちの意見を反映させるように発言をいただくことが大事だと思うのですが、実際にこの方たちは発言をしっかりいただいているのでしょうか。","respondent":"吉岡政策推進担当課長","answer":"この政策評価委員、委員長を入れて１１名ですが、委員おっしゃるとおり、そういったところの懸念を解消するために、ある程度人数を絞ってやっていまして、今年度も昨年度もそれまでも、大学生の皆さん、活発にご議論いただいているところです。","id":"exchange-039"},{"speaker":"まつざわ委員","kind":"質問","question":"それも、それをするにも、６５２事業全部ではなくて、例えば各所管の何％か、何割かを出して、これぐらいをまずやりましょうというのを、ゼロベース査定をしていくやり方をこれからすると、全部の事業を評価するのと、例えばそういうゼロベース方式で、ゼロ査定から１から落としていくやり方だと、どちらが、効率がいいか、大変ではないのか、そういうのは分かるものなのですか。","respondent":"吉岡政策推進担当課長","answer":"一方で、全事業を毎年見直して、本当に改善・見直すところが出てきているのかというのは正直ありますので、そういった段階においては、やはりかけた時間に対して、いわゆる改善・見直し事項が出てこないと、時間を使ってしまい過ぎていないかというところもありますので。","id":"exchange-040"},{"speaker":"まつざわ委員","kind":"意見","question":"そうしますと、例えばサンセット条項というのがあるのです。例えばＣ評価が２年続いてしまったら、もう予算は半分ですとか、それぐらいもう初めから組み込んでしまうとか、そういったやり方を今後こうやって踏まえていくのは、評価のやり方としていいものなのか、少し違うものなのか、そのお話を聞きたいと思います。","respondent":"吉岡政策推進担当課長","answer":"先ほどお話ししたように、行政の事業、施策は非常に多岐にわたるものでございまして、何を基準に、これは何％かと、執行率が低いから悪いのか、高ければ絶対いいとか、そういったものではございませんので。","id":"exchange-041"},{"speaker":"まつざわ委員","kind":"意見","question":"本当にとても大変なことだと思っていますので、やはり継続しながら、一番怖いのは、そのままでいいという、ただやみくもに惰性で継続してしまうのが、こういう事務事業の一番怖いところだと思っているので、何かいろいろなことをやりながらも、また、自分たちに過度な負担がかからない何かいい方法を一緒に見つけていけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"いよいよ３年目を迎えたということで、事務事業評価については、本当に見える化で改善につながったと、今もお話がありましたけれども、議員としても非常に助かっておりますし、自治体によっては事務事業評価がなくて、それをつくってほしいという、そうした市民の声とかが出ているような、そうした自治体がある中、品川区はこうしてやっていただいているということ、非常にいいことだと考えています。","respondent":"吉岡政策推進担当課長","answer":"昨年度の事務事業評価を実施した予算事務事業が６６９事業で、今回６５２事業ですので１７事業差分があります。","id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/416707?Template=document&Id=7213#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=20&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":53737,"voices":111}},{"id":"r07-20250926-22","meetingId":"r07-cm09","date":"2025年9月26日","dateIso":"2025-09-26","committee":"まちづくり・公共交通推進特別委員会","time":"午前１０時００分～午後 ０時０８分","status":"正式会議録","sourceType":"formal","overview":"まちづくり・公共交通推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"これを実現すべく、議会側もしっかり対応していきたいという思いであります。１の（２）の窓口および事務機能、ここが今後は中心になってくるテーマなのかなと考えています。これこそ新庁舎を建てるに当たって、求められる成果というか効果だと感じています。新たな価値とはどういうことを指されているのか、まずはお聞かせいただきたいと思います。","respondent":"三井新庁舎整備課長","answer":"今後、そういったコミュニケーションを活性化していくため、検討を進めているところです。オフィスレイアウトについては、実施設計概要にも書かせていただいているとおり、グループアドレスの導入と書いております。","id":"exchange-001"},{"speaker":"田中委員","kind":"質問・要望","question":"職員の方同士、また部署を越えた職員の方同士の交流ということから、新たな価値、何が求められるのかはあれですけれども、交流によってお互いに刺激し合って、活性化された職場をつくっていく。１箇所の窓口で言えば、そのことがほかの部署でも共有されて、活用できるようなことも含めて、新たな価値の創造なのかなと思っています。今の段階での想定されているものがあればお知らせをいただきたいと思います。","respondent":"三井新庁舎整備課長","answer":"そういったことも考えると、やはり基本情報を各課と連携するというのは、今、国が進めている窓口ＤＸＳａａＳという窓口支援システムがあるのですが、まず国の標準化の進捗具合も見定めながら、そういったシステムの導入も見据えて、今後。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"最後にお聞きします。あわせて、新たに新庁舎のヘッドクオーターが新しくなるということに伴って、今１３地域センターありますが、それぞれの地域センターと本庁舎との連携について、お聞きします。それはその次のさらなる段階なのかもしれませんが、その辺のご認識を地域センターとの連携という視点での今回の新庁舎の在り方というのをどのように考えていらっしゃるのかお聞かせいただきたいと思います。","respondent":"三井新庁舎整備課長","answer":"ただ、新庁舎整備課だけでできる話ではございません。地域センターで実施する内容も多岐にわたりますので、関係の窓口部署と引き続き連携を図りながら検討していきたいと考えています。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"最後、意見で。ぜひ地域振興部とも連携していただきたい。窓口のワンストップというのは、本庁舎でのワンストップももちろんありますが、場合によっては地域センターでワンストップで全てが可能な対応をしていただけるというのが本来のワンストップの意味でもあると思いますので、新庁舎に限定せず、オール都庁というかオール区役所として、窓口も含めた対応を取っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"塚本委員","kind":"質問・要望","question":"最初に、ＺＥＢとＣＡＳＢＥＥですかね、ＺＥＢが今回の本庁舎で１２施設目、ＣＡＳＢＥＥについては都内では初になるということでしたっけ、この規模の建物としては。そういった認証が取れたことは物すごくすばらしいことだとは思っているのですが、そこについてご説明をお願いしたいと思います。","respondent":"小林新庁舎建設担当課長","answer":"今回の新庁舎につきましても、そういうところまで含めて、運用上の状況も含めて、設計者と我々の中で管理をしていきながら、より適切なＺＥＢの施設の運用に努めてまいりたいと考えているところです。","id":"exchange-005"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。しっかりと建設された後もそういった形でチェックをしていくと。そのチェックというのは、ＣＡＳＢＥＥとかＺＥＢの認定に影響があるのですか。極端な言い方をすると、数値が悪いと認定は取消しみたいな、そういう事後のチェック機能みたいなものも、この認定の中にはあるのでしょうか。","respondent":"小林新庁舎建設担当課長","answer":"他施設で所管がちょっと異なりますが、施設によっては結果をホームページ上で公開しているところもありますので、そういった対応も含めて検討してまいりたいと考えています。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問・要望","question":"ありがとうございました。建築後はそのように進めていただける体制を考えていただきたいと思います。それから、もう一点、防災計画のところで、先日の木曜日、９月１１日の大雨のことで伺います。センセーショナルでした。その辺の対策について。浸水を防ぐ、あるいは排水で何とか全部水を外に出していく、こういう対策がどこまで取られているのかというところをちょっとお伺いしたいと思います。","respondent":"小林新庁舎建設担当課長","answer":"やはり地下に対してそれでもさらに流れるようなことがあれば、当然ポンプとかを設置して排水する機能を設ける必要があるかと思ってありますが、様々そのような対策を設けることによって、地下の浸水に対して防いでいく設計で今進めているといったところです。","id":"exchange-007"},{"speaker":"塚本委員","kind":"確認","question":"分かりました。１階部分が周りの道路よりも少し高いということで、周りからは入ってこない。そういった危険はないのかなというところなのですが、そこは今の説明でいうと、道路より１階が高ければ水は基本的には入ってこないだろうという想定で大丈夫ということなのでしょうかというのを、もう一回確認させてください。","respondent":"小林新庁舎建設担当課長","answer":"周辺の下水に対しての負荷もなるべくかけないような設計になっています。先ほど申し上げたとおり、敷地内につきましても、時間１２０ミリまでは耐えられるような設計になっているといったところです。","id":"exchange-008"},{"speaker":"若林委員","kind":"質問・要望","question":"もう一点だけ。今のは、視覚障害の方に向けてというところでした。２週間ぐらい前に議会として、秋にデフリンピックがあるということで聴覚障害団体の方から研修を受けまして、この庁舎の在り方についても、一言、二言、ご要望とかがあったように記憶をしております。聴覚障害者の方への配慮、いわゆる合理的配慮についても一言、今の段階で言えること、お考えをお示しください。","respondent":"小林新庁舎建設担当課長","answer":"特にトイレの中がなかなか分かりづらいところがありますので、トイレの中にそういったものを設置することによって、災害時、火災時にあっても適切な誘導ができるような仕組みを整えていくといったところにつきまして、広く検討しています。","id":"exchange-009"},{"speaker":"えのした委員","kind":"質問・要望","question":"やはり新庁舎建設に当たっては、安全第一ということで、進めていっていただきたいと思います。幸いけが人が出るような大きな事故にはつながらなかったのですけれども、この工事説明会について、主な内容に工事による危惧の防止策についてとありますが、これ、何か具体的に、また新しい取組等あれば教えてください。","respondent":"小林新庁舎建設担当課長","answer":"そういったところの導入については今後も引き続き施工者と協議していきながら、安全な現場運営に努めてまいりたいと考えているところです。","id":"exchange-010"},{"speaker":"えのした委員","kind":"質問・要望","question":"カメラの設置ですとか、新しい取組、ぜひ導入していただきたいと思います。工事現場の作業員の方ですとか、また近隣の方、ご通行の方の安全対策、しっかりと取り組んでいただきたいと思います。これ、まだ国の話ですけれども、各自治体でも広げていければということで、この辺、もう何か区としてお考えありますでしょうか。お聞かせください。","respondent":"小林新庁舎建設担当課長","answer":"先ほどの安全と重なる部分ではありますが、安全にまずは工事を進めていただいて、適切な時期にきちんと工事をまとめていただくというところをしっかりと管理してまいりたいと考えているところです。","id":"exchange-011"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"３つに分けて質問します。ここまでこういうことをいろいろやった中で、やっとこのＺＥＢ Ｒｅａｄｙが取れたのだという経緯を教えていただきたい。いっぱいあるので全部というふうな話になると思いますが、幾つかでも結構なので、教えていただきたい。ウェルネスオフィスもどこを中心として、Ｓランクになれたのかというところをまず教えていただきたいと思います。建築から教えてください。","respondent":"小林新庁舎建設担当課長","answer":"何か１つというところではなかなか難しいところですが、一つ一つの積み重ねでこのような結果になったかなと思ってあります。ＣＡＳＢＥＥ－建築の建材の部分です。","id":"exchange-012"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"非常に難しかったと思います。先ほどおっしゃったように省エネの機器の場所ももちろん大切だったと思います。積み重ねがあったと思います。だから、稼ぐほうと減らすほうを加味して５２％できたのかと思っている。その辺のからくりをもう少し教えていただければありがたいと思います。電力を稼ぐほうと省エネで使わないほうをどういうふうにされてここまで来たのかというところだけもう１回教えてください。","respondent":"小林新庁舎建設担当課長","answer":"やはり今回は、極力区民の皆さんが目に触れて、知っていただける場所に設置することによって太陽光のことを知ってもらうというところも１つの狙いと思ってありますので、そういった配置の中でうまく太陽光パネルの普及啓発にもつなげられればと考えるところです。","id":"exchange-013"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"今伺って、１％というのはえっと思ったけれども、そんなものなのだなと思いました。だから、コピー機は必要ないよというぐらいまでペーパーレスが進んでいるわけではないですか。このままずっと行ってしまうと、何かすごくスペースが余っていて余裕だけど違うものに活用したほうがいいのではないかという話にならないのかなというところをどう考えていらっしゃるのか改めて教えていただきたいと思います。","respondent":"三井新庁舎整備課長","answer":"今回、実施設計概要に入れさせていただいたのはあくまでもイメージになっておりまして、現在、オフィスレイアウトの調整をしている段階で、これから待合スペースをどういうふうにするかという具体的な検討を進めていく段階になります。","id":"exchange-014"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"ぜひそういうのを考えていただきたいと考えています。先ほど言ったようにイトーキも、あそこで伺ったら、これをやったのはいいけれども、実際動き出してから３年かかったというわけです。もう一つ、いろいろなところを見に行って思ったこと。だから、福利厚生施設としてやるものは、別に障害者のカフェでなくても、そういう食堂でも何でもいいのだけれども、そこの柔軟性というのはいかがでしょうか。","respondent":"三井新庁舎整備課長、小林新庁舎建設担当課長","answer":"なので、福祉部のほうで福祉のフロアということでまとめて今、実施設計概要に書かせていただいていると思うのですが、福祉部の中に社会福祉協議会まで入れるというのは、現実的にはなかなか厳しいのではないかなと。実際に所管も今それに向けた検討を進めているところでございまして、ただ一方で、委員ご案内のとおり、今回、ＯＩＭＡＣＨＩ ＴＲＡＣＫＳができることによりまして。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問・要望","question":"跡地については、まず基本的な考え方の確認ですけれども、今回サウンディング調査ということで１３の民間事業者、特に不動産、建設関係の業者の意見を聞いたということです。要は、区が持っている土地の活用という視点で、そういうものよりはむしろ再開発、また土地活用というような視点に重きを置かれた調査のように感じられるのですけれども、そこはどうなのか。","respondent":"泉広町事業調整担当課長","answer":"こちらはかねてから区議会でもご答弁させていただいてありますけれども、２００億円を今指標にしながら検討を進めているところになってあります。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"今回、そこに限定したわけではないという、民間事業者からの意見も聞くという、そういう段階なのかなということで確認をいたしました。以前このフェーズに入る前のフェーズで、いろいろな地域の関係者の意見を聞く場面もあったかと思います。あのときはあのときで公有地の活用検討で隣接している私立の学校が、何で意見を聞く対象に入るのかなとちょっと疑問に感じたところもありました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"松本委員","kind":"質問","question":"今、ちょうど財源等の話で２００億円の話が出てきたかと思うのですけれども、跡地を活用して２００億円をというのは、区長選挙のときに出てきた話でもあるので、数年前の話になってきているかと思います。資産価値が上がってきているんだから区としての取り分的なところをもうちょっと増やさないといけないとか、そうした協議は区の中で行われているのかどうか伺います。","respondent":"泉広町事業調整担当課長","answer":"そういった状況ですので、まさに検討しています。","id":"exchange-018"},{"speaker":"松本委員","kind":"質問","question":"おっしゃるとおり、どういうふうに財源に充てていくかというのを考えていくと、高めれば高めるほど収益性のある施設になるというのはおっしゃるとおりかと思います。一方で、これからうまく、持っている資産を活用すれば、今後の区民の負担を下げることにもつながっていくわけですから、そこの部分はバランスを考えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"幾つか伺いたいと思っています。１３社。不動産事業者、建設事業者等とあるんだけど、もう少し教えていただきたい。不動産事業者といっても、例えば大手の不動産事業者だとするならば、それはもう建設事業者の中のデベロッパーというのとはまた違っているのかなと思うけれども、もうちょっとそこら辺の内訳を教えてもらえればありがたい。","respondent":"泉広町事業調整担当課長","answer":"今回参加いただいた１３社の内訳です。こちらは委員からお話がありましたとおり、なかなか業者のお名前は開示できないというところになってあります。デベロッパーが過半数を超えているところです。","id":"exchange-020"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"多分そういうことなんだろうと思いますけれども、この「等」というのは、何で「等」をつけたのかをあわせて教えていただきたい。今ゼネコンの話はなかったけれども、大手、スーパーゼネコンとされるようなところがあったのか。は「等」というのはどういう想定であえて「等」とつけたのかというところもあわせて教えてください。","respondent":"泉広町事業調整担当課長","answer":"等としているところにつきましては、一部業種をここでお知らせしてしまうと、かなりお名前が限定されてしまうことも考えられ得ることから、今回は等という形で少しまとめさせていただいているところがあります。","id":"exchange-021"},{"speaker":"石田（秀）副委員長","kind":"提案","question":"もう２００億。こういう提案をもっとちゃんとそれなりにやる意味のであれば、私は区民の皆様だけではなく、ここにこういうものがあるんだ、大井町のこういうところでこういう形のものがあるんだということを広めていく、そういう経済効果を入れるべきだと思います。私もこれはずっと声を上げていくけれども、ぜひそういうことをやっていただきたいと思うんだけど、そこら辺の考え方を教えてください。","respondent":"泉広町事業調整担当課長","answer":"なかなか事例が見つからないというようなご回答をいただいているところはありますけれども、引き続きどういった示し方をできるかというところを含めて検討を進めてまいりたいと思ってあります。","id":"exchange-022"},{"speaker":"藤原委員","kind":"確認","question":"一つ確認をしたいんですが、指標が２００億という形でしたよね。１回で２００億みたいなイメージになってしまうと、私なんかは、じゃあ、売却かなと思ってしまうんです。１回で２００億ではないですよね。つまり２００億という指標があったとしても、例えば毎年２０億ずつで１０年とか、１０億ずつで２０年とか、そういう感覚の指標でいいのか、確認させていただけますか。","respondent":"泉広町事業調整担当課長","answer":"そういう民間事業者の意見も踏まえながら、また区の財政の状況も捉えながら、どういった形が適切ないただき方になるのかは検討してまいりたいと思ってあります。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問","question":"そうすると、まだ具体的には分からないと思うんですけれども、ここがまず解体されて、更地になって、その後いろいろなご意見が出てという形で、現実にこの跡地がどうなったとなるのは、今考えると大体どのぐらい先になるというのは、大体でいいんですけれども、例えば１０年後とか、何かそういうのをつかんでいたら教えていただけますか。","respondent":"泉広町事業調整担当課長","answer":"例えば令和１３年度の終わり頃に解体等が終わりますので、そこからまた新しい建物、何ができるかはまだこれからですけれども、建設にまた３年ぐらいかかることを想定すれば、令和１６年度の末ぐらいに本庁舎の跡のほうに建物ができてくる。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問","question":"最後に数字的なことを伺いたいんですけれども、いろいろ変動はあると思うのですが、第二庁舎まで解体したとしたら、解体料はどのぐらい今の時点で考えているんでしょうか。","respondent":"泉広町事業調整担当課長","answer":"例として、今、周辺の解体が終わっている自治体にヒアリングをして、延べ床でどれぐらいのお金がかかったかをお聞きして、単純に私どもの庁舎の面積で割りますと大体４０億円ぐらいのお金が必要になってくるのではないかというところで、まだこれはすごく粗い数字ですけれども。","id":"exchange-025"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"今の話で１点だけ。私もいろいろな方にお話を聞いたら、やはりこれまでは当たり前のような話があったけれども、この１０年ぐらい、どこの土地もマンション業者の方が出てくると。マンション業者が一番高値買いをする。今こうやってやってきた中で、マンションレベルで土地をざっと買ってきて、今日もニュースでやっていたけど、中古のマンションだって２３区は１億超えたと。これは要望だけにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"松本委員","kind":"質問","question":"今回の資料では示されていなかったのですけれども、地域公共交通会議のほうの資料を見ると、昨年の８月から子育て支援割の導入がされています。一応、８月からの収支を見ると、あまり影響がないように思われるのですけれども、ここはどう解釈すればいいでしょうか。お願いいたします。","respondent":"櫻木地域交通政策課長","answer":"子育て支援割につきましては、利用者数としては、８月以降少しずつ増えてきている状況です。収支の影響としては、やはり大人運賃が半額になるということで、多少影響はあったかとは思いますが、現在のところは、全体としては収支率は向上したです。","id":"exchange-027"},{"speaker":"松本委員","kind":"意見","question":"半額になっているわけですね。半額になって、普通に考えると、売上額でいったら下がりそうだけれども、利用者数がその分増えたから、ある程度、収支の改善につながっているという理解でいいか、もう一度お願いいたします。","respondent":"櫻木地域交通政策課長","answer":"委員ご指摘のとおりの推移と考えております。","id":"exchange-028"},{"speaker":"松本委員","kind":"質問","question":"ただ、これまでの数年間を見ると、頑張ったとしても５０％というのは、第三者的に見るとかなり難しいとは思うのですけれども、現状の改善の方向性とか取組というのはどういうことが考えられるのでしょうか。お願いいたします。","respondent":"櫻木地域交通政策課長","answer":"今の現状から見ると、少し目標には乖離があるという状況でございまして、それに向けて取組を進めていくところです。１つは、やはり地道な周知に努めていって、乗車人数を増やしていくということで、ご利用いただく方を増やしていくことが大きなところかと考えています。","id":"exchange-029"},{"speaker":"松本委員","kind":"質問","question":"そうは言っても、やはりこの乖離というのはなかなか大変なのだろうと思います。だけど、区として補填されているという前提があると思います。その分もちろん、先ほどの子育て支援割とのバランスで考えると、利用者数は減るということにはなると思うのですけれども、収支を考える上では、そこの部分も検討は必要ではないかと思いますが、いかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"これまでシルバーパスをご利用して乗車していただいた方への影響、また、こちらに書かせていただいたとおり、福祉的な側面もあるということで、見直しの可能性としては、委員ご指摘のとおり、様々な可能性はあると思いますが、一定、慎重な判断をしつつ。","id":"exchange-030"},{"speaker":"塚本委員","kind":"質問","question":"そういった意味では、様々な課題があり解決が、すごく難しいというところもあると思います。今日の資料には１行、運転手不足の一つの解決手段である自動運転技術についても注視となっていますけれども、現段階で本格導入みたいなものがどの程度見込まれるのかというのを一応お伺いしておきたいと思います。","respondent":"櫻木地域交通政策課長","answer":"東急バスも京急バスも、自動運転は地方のほうで少し実証運行をやられているということもありますので、その辺り、我々としても注視していきたいと考えています。","id":"exchange-031"},{"speaker":"塚本委員","kind":"意見","question":"具体的な話はやはりまだまだ全然出てきていないのかということを、今のお答えで受け止めました。いずれといたしましても、オンデマンド交通とか、新しい手法で公共交通を補う自治体等の役割というのはこれから増えてくるのだろうと思います。より大胆な予算確保と、歳出等確保しながら進めていくべき分野なのかと思いますので、これは意見ですけれども、今後ともよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"田中委員","kind":"提案","question":"再三ご質問していますが、今回、試行運行期間を、令和７年度までだったものを令和１０年度まで延長するということでして、この事業が継続されるということの地元の方にとっての安心感がある一方で、収支率の改善等々の課題がある。逆に、忖度しているがゆえに、京急バスのほうにそういう提案をしていないということなのか。今までの質疑の中でもう少し突っ込んでお伺いをしたいと思います。","respondent":"櫻木地域交通政策課長","answer":"桜新道またはいすゞ病院といった地域で使えないということにつきまして、区といたしましても、長年、再三にわたって京急バスと協議、申入れをしてきているところでして、理解が得られないという言い方が適切かどうか分からないですが、現時点では。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ交渉を続けていただきたいと思います。そこはぜひ粘り強く交渉を続けていただきたいと思います。同じ事業者であれば容認されるけれども、競合するバス会社のルートに設定するのは大変課題があると、今回の大井地区を見ると、そのように捉えられるのですけれども、そういう背景があるから、なかなか大崎とか荏原地区には導入できないということなのでしょうか。","respondent":"櫻木地域交通政策課長","answer":"大崎につきましては、説明させていただいたとおり、一つの実証運行としてやらせていただくということを計画していますので、ほかの事業者との関係という側面も、運行エリアの調整によっては若干影響してくるところもあろうかと思いますが、基本的には。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"分かりました。は大井ルートの収益率改善に向けて粘り強く対応いただきたいのと、これを踏まえて他地区への横展開もぜひお願いをしたいと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/979437?Template=document&Id=7215#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=22&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":41664,"voices":98}},{"id":"r07-20250930-4","meetingId":"r07-c-settlement","date":"2025年9月30日","dateIso":"2025-09-30","committee":"決算特別委員会","time":"午前 ９時３０分～午後 ５時３６分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を151件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"筒井副委員長","kind":"質問","question":"第４項、款別審査の質疑等についてです。なお、質問時間は、会派におかれましては、１人当たりの質問時間は、答弁時間も含めて、１０分、１５分、２０分のいずれかとし、無所属の委員は、答弁時間も含めて１日につき１０分となります。終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"以上で、決算統計上の数値および、財政健全化法に基づく各指標についての説明が終わりました。 それでは、令和６年度品川区一般会計歳入歳出決算","agenda":"以上で、決算統計上の数値および、財政健全化法に基づく各指標についての説明が終わりました。 それでは、令和６年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"まつざわ委員","kind":"質問","question":"そこで、決算書によりますと、ふるさと納税に含む寄附金全体の決算額、先ほど会計管理者からお話がありました約２７億円は、前年比から８８２.７％と大変驚異的な伸びを記録いたしました。高く評価いたします。この飛躍的な増収の主な要因をどのように分析されているでしょうか。その中で、ふるさと納税制度が果たした役割と、今年度の取組の状況、今後の可能性についてお聞かせください。","respondent":"藤村総務課長、宮澤税務課長","answer":"寄附金全体についてというところのご質問です。私のほうで、一般寄附金というところで、今回の２５億９,０００万円余というところで収入があったところについてお答えいたします。今後の部分ですけれども、引き続き区内の事業者と連携しながら、体験型、また商品型の返礼品の拡充を進めていくとともに、応援型でありますクラウドファンディングや団体応援寄附の取組というのも含めまして。","id":"exchange-002"},{"speaker":"まつざわ委員","kind":"意見","question":"２５億円の寄附、応援したいという、なかなかすばらしい方が品川区にいらっしゃるのだなということと、やはり１億８００万円、寄附があったということは、本当にすばらしいことだと思っています。こうした観点から、これまで取り組んできた事業協働型寄附。要はいわゆるガバメントクラウドファンディングといったことや、寄附の対象といった拡大の取組を強化すべきと考えますが、ご見解をお聞かせください。","respondent":"宮澤税務課長","answer":"寄附の拡大というところで、先ほど申しました、しながわ団体応援寄附を、まず学校法人を対象に始めているところですけれども、寄附の状況等を鑑みながら、社会福祉法人または公益財団法人といった、区内で活動されている団体への拡大について。","id":"exchange-003"},{"speaker":"まつざわ委員","kind":"意見","question":"ふるさと納税、またガバメントクラウドファンディング、この自主財源確保を専門に担う部署のチームを設置して、推進体制を基本的に強化していかないと、自主財源の拡充というのは難しいと思っています。より一層の財源確保に向けまして、全庁的に情報を集約して、また戦略的に取り組む司令塔というものを置くべきと考えますが、ご見解をお聞かせください。","respondent":"宮澤税務課長","answer":"ふるさと納税の取組は、今年度４月より専任の係を新設して取り組んでおります。","id":"exchange-004"},{"speaker":"山本委員","kind":"質問","question":"本日からどうぞよろしくお願い申し上げます。私からは、５２ページの特別区民税、６０ページの特別区財政調整交付金、関連して決算全般について伺います。特別区民税について伺います。１人当たりの税収増でしょうか、人口増でしょうか。品川区では今後、２０５１年まで人口が増える見通しを立てておりますので、特別区民税は人口増に伴って増えていくという見通しでしょうか。ご見解をお教えください。","respondent":"宮澤税務課長、加島財政課長","answer":"１つ、大きいところとしては、納税義務者の増加ということで、令和５年度から令和６年度で５,１００人ほどの納税義務者の増加、また、併せて高所得者層についても、前年と比べて２,２００人ほどの増加という状況です。都区財政調整は今回、５７億円の伸びとなりましたけれども、まずは固定資産税の評価替え等による財政調整財源の伸び、それから算定では。","id":"exchange-005"},{"speaker":"山本委員","kind":"確認","question":"主要財源である特別区民税、財政調整交付金とも、今後も着実に推移するという見通しであるということを確認いたしました。続いて、令和６年度決算において、翌年度への繰越額６７億円余とありますが、こちらはどのように扱うのでしょうか。確認させてください。いかがでしょうか。概算額で結構ですので、均等割での徴収額を併せてお教えいただいた上でご見解を伺えればと思います。","respondent":"加島財政課長、宮澤税務課長","answer":"令和６年度は国策として、定額減税に取り組んだところではありますが、区としては、頂いた税金を財源といたしまして、区民のウェルビーイングに資する施策を積極果敢にやっていくというところを趣旨としておりますので。均等割自体が、区民税部分で３,０００円、都民税部分で１,０００円、合わせて４,０００円というもので、地域社会の会費という性質を持っていて、所得の大小にかかわらず、広く負担いただいているものです。","id":"exchange-006"},{"speaker":"山本委員","kind":"質問・要望","question":"今年７月に名古屋市に会派で視察に伺いましたが、市独自の減税施策により消費喚起が進んだという住民アンケート結果もあると聞きました。今後、ご検討いただくことを要望いたします。先日の一般質問でも要望いたしましたが、財政の見える化をさらに前に進めてほしいと考えます。このように、他区の好事例を研究していただきながら、品川区でも財政の見える化を進めてほしいと考えます。ご見解を伺います。","respondent":"加島財政課長","answer":"世田谷区の例にございました将来の財政見通しというところですけれども、品川区では今現在、総合実施計画で５年間の見通しを立てているところですが、こちらも調査・研究する中でどのような形が取れるのかというのは、今後考えてまいりたいと考えています。","id":"exchange-007"},{"speaker":"山本委員","kind":"質問・要望","question":"ぜひ研究して前に進めていただきたいと思います。将来の見通しについては、計画でお示しいただいておりますけれども、状況の変化によって機動的にアップデートしていくというところもすごく大事だと考えていますので、そういったところも併せてご検討いただきたいと考えています。最後に、決算全般について伺います。令和６年度決算の、行政としての評価について伺います。","respondent":"加島財政課長","answer":"歳出につきましては、まず目下の物価高騰に対する事業者支援といたしまして、省エネルギー対策や業務改善設備更新助成を実施、また子育て世帯の経済的負担軽減の一環として、区立学校学用品の無償化。","id":"exchange-008"},{"speaker":"山本委員","kind":"意見","question":"健全財政を維持しながら、様々な施策を講じていたということで理解いたしました。令和６年度、ウェルビーイング予算３８億円を捻出されて実施されたというところですけれども、この辺りについてもご評価をお聞かせください。","respondent":"加島財政課長","answer":"こちらは、令和６年度ウェルビーイング予算の４つの柱に基づいて取り組んできたところではありますけれども、昨年度中に実施いたしました世論調査では、幸せだと感じている、やや幸せだと感じているという方が８割半ばを超えまして、区民の幸福実感度というものが。","id":"exchange-009"},{"speaker":"山本委員","kind":"質問・要望","question":"全体で高まっているというところではあるのですけれども、各施策に対する効果検証を、それぞれしっかりと進めてほしいと考えております。この辺りは歳出の款別審査でもそれぞれ確認させていただきたいと考えています。先ほど申し上げました将来の財政見通しなどを分析しながら、健全財政が維持できるように進めていただきたいと考えています。コメントがあればお願いいたします。","respondent":"加島財政課長","answer":"新庁舎の建設につきましては、減債基金への積立て、それから決算上では公共施設整備基金、義務教育施設整備基金に、今後の老朽化を見据えて積立てを行っておりますので、そういったことを各年度の中での歳入歳出の動きを捉えて。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは、１４６ページの災害対策職員待機寮利用料に関連して、災害対策職員の災害時の参集についてと、７８ページ、従前居住者用住宅使用料に関連して、災害発生時の従前居住者用住宅への受入れについて、それぞれお伺いします。初めに、災害対策職員待機寮の単身寮、家族寮それぞれについて、簡単な間取りと利用料をお聞きしたいと思います。","respondent":"宮尾人事課長","answer":"それから利用料ですが、単身寮につきましては、広さ等にもよるのですが、大体平均すると３万円程度です。家族寮につきましては５万円台のものが中心ということになってあります。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"確認","question":"確認させていただきました。単身寮３万円台と家族寮５万円台。品川区の賃料としては、かなり安価な設定になっていると思われますが、この理由についてお聞きしたいと思います。","respondent":"宮尾人事課長","answer":"待機寮に入居できる資格といたしまして、以下のことを義務づけしております。災害時の初動連絡等に従事することができるということ、それから各種の防災訓練への参加を義務づけているといったことを条件に入居を認めているというものです。","id":"exchange-012"},{"speaker":"ゆきた委員","kind":"確認","question":"災害のための待機寮ということで、安価な設定ということを確認させていただきました。品川区では、災害対策待機寮が９棟９８戸あり、それ以外でも借り上げが３６戸あると確認しています。以前の確認では、現在９７人の職員が災害対策要員として区内で居住しています。災害対策職員待機寮の存在意義、居住する職員の条件、また地震等の災害から火災を除く理由について教えてください。","respondent":"星災害対策担当課長","answer":"つきましては、延焼火災に対しまして、災害対策職員は現在のところ出動してございません。なお、延焼火災に対する品川区の支援につきましては、延焼中の情報を消防署から入手し、速やかに防災課職員が参集を行い、実施しているところです。","id":"exchange-013"},{"speaker":"ゆきた委員","kind":"質問","question":"すみません。私が聞き逃したのかもしれないのですけれども、過去の実績、災害対策職員の風水害も含めて、全ての実績について教えてください。","respondent":"宮尾人事課長","answer":"令和６年度の実績といたしまして、令和６年度は震度５弱以上の地震が発生していないこともありますので、風水害の対応といたしまして９件、延べ７７名の待機寮生が従事したという実績があります。","id":"exchange-014"},{"speaker":"ゆきた委員","kind":"質問","question":"すみません。これまでの過去の実績を教えてください。","respondent":"宮尾人事課長","answer":"今お答えした実績が、令和６年度１年間の実績ということでお答えさせていただきました。","id":"exchange-015"},{"speaker":"ゆきた委員","kind":"意見","question":"今回の会計決算審査意見書でもありましたが、被災者への効率的な支援、火災現場での迅速な支援、そして災害対策要員のスキルアップのために、一定の基準以上の火災においては災害対策職員待機寮の職員が参集できる体制の構築は必要だと思われますが、こちらについて区の見解をお聞かせいただければと思います。","respondent":"星災害対策担当課長","answer":"先ほどの答弁と一部重なりますけれども、災害対策職員の待機寮生は現在、災害対策本部室が開設される災害に対して対応いただいているところです。それ以外の通常の延焼火災に対しましては、品川区の防災課職員が参集を行い、支援しているところになります。","id":"exchange-016"},{"speaker":"ゆきた委員","kind":"質問","question":"時間もありますので、次の質問に移ります。火災発生時の従前居住者用住宅への受入れについてお聞きしたいと思います。従前居住者用住宅の利用料についてお聞きできればと思います。","respondent":"小川木密整備推進課長","answer":"利用料ですが、従前居住者用の家賃に関しましては、収入の金額に合わせまして設定しています。部屋の間取りによっても金額は変わってありますが、一番安価なところでは３万５,０００円から、一番高いところで１２万２,０００円というような形での設定となっています。","id":"exchange-017"},{"speaker":"ゆきた委員","kind":"質問","question":"現在の従前居住者用住宅、ソレイユ戸越は、火災被災者が居住する常設のお部屋が確保されているところになっていると思われますが、こちらのランニングコストについてお聞きできればと思います。","respondent":"小川木密整備推進課長","answer":"ソレイユ戸越のランニングコストですけれども、こちらに関しましては、維持管理、清掃等といったものにコストがかかってあります。金額については、今、手元にございませんので、そういった委託関係でコストがかかっているといったところでのご説明となります。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"１３３ページ、不燃化特区支援事業、１００ページ、社会資本整備総合交付金、時間があれば７８ページ、従前居住者住宅使用料について伺います。そして、この事業は今年度で期限が切れますが、来年度以降も支援が受けられるように、制度の延長を都に働きかけていただきたいと思いますが、いかがでしょうか。","respondent":"小川木密整備推進課長","answer":"実施地区や助成支援内容は、今年度、東京都と区で協議をしながら、今現在、検討を行っておりまして、区としましては、引き続きしっかりと不燃化促進ができるような形で、地区の継続等のところについては、東京都としっかり検討してまいりたいと考えています。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひしっかりと、継続できるように東京都に働きかけていただきたいと思います。改めて、特定整備路線の放射２号線・補助２９号線の事業費はそれぞれ幾らか教えてください。そして、最新の土地取得率も伺います。","respondent":"高梨都市計画課長","answer":"用地取得率についてですが、放射２号線につきましては５２％の用地取得率、補助２９号線につきましては区間ごとに異なってございまして、３２％から６７％という状況になってあります。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"すごい事業費だなと思います。先ほどありましたけれども、現在の区内には１０地区の不燃化特区があるのですが、特定整備路線沿線地区は３地区あるのです。こちらの補助２９号線の沿道地区、放射２号線沿道地区のそれぞれの不燃領域率を伺いたいと思います。併せてなのですが、道路の予定地内での現在の不燃領域率というのがどうなっているのか、お分かりでしょうか。伺いたいと思います。","respondent":"小川木密整備推進課長、高梨都市計画課長","answer":"不燃化特区として位置づけられております３地区の不燃領域率についてお答えします。特定整備路線の道路の区域内における不燃領域率についてですが、そちらについては東京都から情報を得ているものではございませんし、区としても算出してございません。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"例えば放射２号線を例えにしますと、沿道地区の不燃化領域率は７０.９％と。次に、社会資本整備総合交付金について伺います。伺いたいと思います。区がまずは行うという地域住民との意見交換ですが、再開発準備組合に入っていない方も当然、地域住民ですので、そうした方々も対象に意見交換を行うべきかと思いますが、やっていただけるのでしょうか。伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"地域との意見交換という点ですけれども、現在、地域の意見交換につきまして、誰とやるかというところはまだ検討中ですが、基本的には町会やまちづくり団体等、まちづくりに関する方としっかりと意見交換をしていきたいと考えているところです。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"検討中ということですけれども、まちづくりに関わっている人は、まちづくり団体と町会だけではないですよね。準備組合に、入っていない方もたくさんいるのです。そういう方々も対話の対象にすべきだと思います。伺いたいのですが、品川区の今のご答弁ですと、再開発を進めたいという住民以外とは対話しませんということなのでしょうか。伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"地域との意見交換につきましては、準備組合だけではなく、準備組合に加入されていない方も含めまして、現在、検討しているという状況です。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひそのようにお願いしたいと思います。大崎駅の東口の第４東・西地区についても伺いたいのですが、建設委員会に都市計画案についての報告がありました。伺いたいと思います。国の要綱改正などの情勢の変化や地域の同意状況などを鑑みて、１月下旬、都市計画決定との都市計画決定手続のスケジュールは白紙にして、都市計画案そのものを見直すべきだと思いますけれども、いかがでしょうか。","respondent":"中道都市開発課長","answer":"現在、大崎東口第４地区では都市計画手続を進めている状況でございまして、これは当初の予定どおり進められている計画です。区の総合実施計画にも、令和７年度に都市計画決定を行うという計画となっているです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"それでも進めるのですかという話だと思います。区は、自ら都市計画決定した再開発事業で住まいを奪われた高齢者やマンション区分所有者など零細権利者の生活再建に、最終的に責任を持つべきだと思いますけれども、いかがでしょうか。再開発で転出を決めた方の希望があれば、従前居住者用住宅に入れるようにする、または専用のそうした住宅を整備することが必要だと私は思いますけれども、いかがでしょうか。","respondent":"中道都市開発課長","answer":"まちづくりにつきましては、様々な声があるということは区も把握しております。事業に対するご不安の声といったものを真摯に受け止めるとともに、区といたしましては、こういった様々な声に対しまして丁寧な対応を行うよう、組合に指導してまいります。","id":"exchange-025"},{"speaker":"せらく委員","kind":"質問","question":"私からは、６４ページの集会所使用料についてお聞きしていきます。一般質問で地域センターの自習室開放について伺いましたところ、会議室に空きが少なく、実際に開放できる会議室が少ないことが課題とされていました。集会所などの利用の可能性を探れないかと考えまして、本日は地域センターの集会所の利用状況の実態について伺いたいと思います。","respondent":"平原地域活動課長","answer":"これが、事実上のキャンセルに相当するようなものと考えているところです。","id":"exchange-026"},{"speaker":"せらく委員","kind":"確認","question":"稼働率１つで見ても、かなり地域センターによって差があるのだなと感じました。次に、キャンセル料の規定について伺います。実際にどのように適用免除の判断が行われているのか。直前のキャンセルによってほかの利用者が使えなくなる、いわゆる機会の損失について、区はどのように把握・評価しているのかを確認したいと思います。キャンセル枠というのは、再利用ができる仕組みがあるのか伺います。","respondent":"平原地域活動課長","answer":"直前キャンセルとなりました場合には、還付はないですけれども、こちらは現在、予約システムという形でやっておりまして、システム上、空きという形になりますので、例えば極端に言いますと当日の受付といったものに対応できるようになってあります。","id":"exchange-027"},{"speaker":"せらく委員","kind":"確認","question":"利用機会の公平性を確保する観点からも、キャンセルが直近で二回、三回と続くような団体に対しては、声を伺ったり、活動状況を確認することも必要ではないでしょうか。地域の集会所は、より多くの区民に利用していただくための施設であり、単に料金の徴収で終えるのではなく、実際に区民が利用できる環境を整えることが重要だと考えますが、区のご見解を伺います。","respondent":"平原地域活動課長","answer":"そういったことにつきましては、お声がけするなどの対応をしていますけれども、どのような対応がいいのかというのは、先ほど委員からもございましたとおり、区民集会所は区民の利便に供するものですので。","id":"exchange-028"},{"speaker":"せらく委員","kind":"質問・要望","question":"こちらについては、私も所属している区民委員会で、口頭で報告があったと承知しております。品川区では地域センターの事業のほかにも、児童センターでもティーン向けのイベントがあるなど、スマホを持つような若者対象の事業が複数ある中で、様々な年代への広報戦略について、どうお考えか、方針を伺いたいと思います。","respondent":"上野子ども育成課長","answer":"委員から児童センターの広報についてご質問いただきました。今、ＹｏｕＴｕｂｅ等で子ども向けに児童センターの魅力を発信しています。今後も、様々なニーズ等を確認しながら、広報については検討してまいります。","id":"exchange-029"},{"speaker":"せらく委員","kind":"質問・要望","question":"最後になのですけれども、今日質問をさせていただきまして、地域センターをはじめ、集会所の利用実態は丁寧に把握して、空き枠の有効活用には努めていただきたいと思います。公共施設を区民の財産としてより有効に活用していくことと併せて、様々な公共施設の集会所での実習室開放事業も視野に入れて、子どもたちにとって安全な居場所を提供できるように取り組んでいただきたいと思いますが、見解を伺います。","respondent":"平原地域活動課長","answer":"自習室につきましては、今回、夏休み直前の開設ということで、なかなかこちらも準備に手の届かないところがございましたけれども、しっかりと、居場所、長期休暇中の勉強の場所の確保を行っていくといったところで、地域センターの会議室あるいは今後、区民集会所の活用なども。","id":"exchange-030"},{"speaker":"横山委員","kind":"提案","question":"私からは、９４ページ、デジタル基盤改革支援補助金、１５０ページ、ふるさと納税寄附金についてお伺いいたします。庁内における連携・共有の場づくりについての現状をお聞かせください。庁内での提案や実践を可視化し、参加したグループメンバーだけではなく、会計年度任用職員を含めて、その他の職員の方々にも提案していく仕組みにしていただきたいと考えますが、区のお考えをお聞かせください。","respondent":"西澤ＤＸ戦略担当課長","answer":"庁内における連携・共有については、ＤＸアワードを開催して、成功事例の共有と横展開を図って、特に優れたグループには表彰もしていく予定になっております。","id":"exchange-031"},{"speaker":"横山委員","kind":"確認","question":"例えば、一定金額以上の処理では自動的に複数人の確認が必須になるような承認フローの設定や、システム改修の際に金額や日付などに関するリアルタイムの整合性チェック機能をつけたり、誤りの傾向を可視化して庁内で注意喚起を行う仕組みを導入するなど、様々な工夫が可能だと考えますが、システム導入や仕組みでの防止策も含めて、電子化された業務の正確性を今後どのように担保していくのか。","respondent":"西澤ＤＸ戦略担当課長","answer":"最後に、システムにおける整合性チェックの自動化についてですが、こちらはＡＩを使ったりといったところも今後検討が必要かと思っていますし、ＲＡＧといった独自データベースの活用や、ＡＩエージェントの適用なども効果的と考えております。","id":"exchange-032"},{"speaker":"横山委員","kind":"提案","question":"２点目に、ふるさと納税寄附金についてお伺いいたします。今後も制度の趣旨に沿った建設的な提案をお願いしたいのですが、特別区の枠を超えて、ほかの都市部の自治体との連携の可能性について、今後どのように捉え、取り組んでいくのか、ご見解をお伺いいたします。","respondent":"宮澤税務課長","answer":"委員ご指摘のとおり、特別区全体でも１,０００億円を超えてきているという状況、年々高まる流出額を受け、今年度、他の自治体と連携した要望活動を、特別区長会、また東京都と調整しておりまして、実施時期・内容についてはまだ詳細は未定のところですけれども。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"ぜひ引き続き積極的に、様々な団体や、ほかの都市部との連携も含めて進めていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"おぎの委員","kind":"確認","question":"は１０３ページ、国庫支出金、再開発事業から、近年高騰するマンション価格と区民の安定した居住に関してお伺いします。この千代田区の取組は、都市の国際化と不動産市場の投機化が進む中で、住宅は本来、住みたい人のためにあるという理念を再確認する政策として、他自治体にも波及が期待される先進的な試みだと思います。そこでお聞きします。は品川区の現状を確認したいと思います。","respondent":"中道都市開発課長","answer":"市街地再開発事業において、組合等の事業協力者でありますデベロッパー等のヒアリングを実施しているという状況です。","id":"exchange-035"},{"speaker":"おぎの委員","kind":"質問","question":"品川区も同じ２３区、こちらもやはり何らかの手だてが必要と思われます。品川区でもそういった調査ができるのかと思いますが、調査に関してはいかがでしょうか。東京都は住宅価格高騰対策の一環として、子育て世代が手頃な価格で住めるアフォーダブル住宅を進めるとのことですが、こういったものを品川区ですぐに活用できるのか、また品川区として考えている何か手だてがあればお知らせください。","respondent":"中道都市開発課長、川原住宅課長","answer":"千代田区での投機目的でのマンション取引に関する要請、また、そこに対する取組というものについては、区も認識しております。その結果については、引き続き東京都の事業の決定の状況を注視していきたいと考えてございまして、そういった動向を見ながら、アフォーダブル住宅などを含めて、子育て世帯がより住みやすくなるまちになるために。","id":"exchange-036"},{"speaker":"おぎの委員","kind":"質問・要望","question":"ぜひ東京都とも連携して進めていただきたいと思います。令和７年度の国会議員政策担当秘書資格試験の筆頭問題にもこちらは出題されており、我が国における住宅問題で最も重要な問題を答えよとして、それに取るべき政策提言といったものを問うものでした。そして、国政での審議を注視しつつ、品川区の健全な成長と品川区民の安定した生活をしっかりと支えていただきたいと強く要望して、次の質問に移ります。","respondent":"今井八潮まちづくり担当課長","answer":"一方で、稼働率の低いお部屋に関しましては、講習室やパソコン室などといった、用途がある程度限定的になるようなお部屋でございまして、いずれも４０％程度という状況になっております。","id":"exchange-037"},{"speaker":"おぎの委員","kind":"質問","question":"稼働していない部分の利活用につきまして、今回、「しながわシティラボ」の実証実験型プロジェクトとして採択されました垂直水耕栽培施設についてお伺いします。今回のこの取組では、東京都やランドブレイン株式会社と協力し、こみゅにてぃぷらざ八潮に垂直水耕栽培施設を設置して実証実験を始めるとのことで、先日９月１４日の収穫体験のイベントに参加してきました。","respondent":"今井八潮まちづくり担当課長","answer":"今回、設置いたしました垂直水耕栽培装置ですけれども、こちらの今後の展開といたしましては、こういった最新型の都市型の農業施設を地域の方に知っていただくとともに、今回実施させていただきましたような収穫体験会などを通じまして。","id":"exchange-038"},{"speaker":"おぎの委員","kind":"質問","question":"ハイドロボールの入った小さなポットを壁に設置するということですので、こういった特性を利用しまして、エコルフェスなどで、壁に緑のウオールアートを行うなどまた並行して始めた江東区のベイエリアでは、毎日の植物のお世話に障害者の就労支援を行っているそうで、１８歳の壁が問題となっている障害者の就労支援にも向いているのではないかと思いますが、そういった展開の活用はいかがでしょうか。","respondent":"今井八潮まちづくり担当課長","answer":"障害者就労との連携ですけれども、今回、収穫体験会には、八潮地区内で就労支援事業を実施していただいております品川総合福祉センターの理事長以下職員の方、あるいは利用者の皆様にもご参加いただいたところでございまして、将来的には施設の管理の部分等も含めて。","id":"exchange-039"},{"speaker":"おぎの委員","kind":"意見","question":"まだ実証実験の段階で、子どもの体験や地域の交流、福祉分野の展開など、様々な展開がこの先まだ未知数ですが、私も八潮に行くたびに見に行こうと思います。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"新妻委員","kind":"確認","question":"私からは、１５５ページ、歩行喫煙防止過料について、１６７ページ、粗大ごみからのリユース品売却についてお伺いいたします。本年３月の予算特別委員会でも取り上げましたが、少し中途半端になってしまいましたので、改めてお聞きしていきます。現状の確認をします。令和７年度の現在までの売上げというのをお聞きしたいと思います。委託料は１,０００万円でよろしいでしょうか。","respondent":"篠田品川区清掃事務所長","answer":"粗大ごみのリユースに関するお尋ねです。売上金額ですけれども、今年度につきましては、８月末現在で１７万４,０００円となっています。委託料につきましては１,０００万円ということで間違いございません。","id":"exchange-041"},{"speaker":"新妻委員","kind":"質問","question":"一方で、ごみの減量の視点から見た場合の効果はいかがでしょうか。令和５・６・７年度の現在までの出品数、そして引渡しをした数を教えてください。そして、またこの数について区の評価をお伺いします。","respondent":"篠田品川区清掃事務所長","answer":"先ほど売上げ等のお話がございましたとおり、経費として１,０００万円余の経費がかかっているものに対して売上げが１７万円ですので、そういった点に関しましては課題があるのかなということで認識しています。","id":"exchange-042"},{"speaker":"新妻委員","kind":"質問","question":"品川区は、ジモティーに委託して、ジモティーがやってくださるという流れでありますので、委託料が発生しておりますが、例えば文京区や他区がやっているような、委託料が発生しないやり方、区民と事業者が直接やり取りをしていくという仕組みで、このリユースを推進していくということも必要かと思いますが、今後の区のお考えをお聞きしたいと思います。","respondent":"篠田品川区清掃事務所長","answer":"もともと、委員からもお話があったとおり、リサイクルショップリボンがなくなったということで、その代替の措置という意味合いもあったのですけれども、様々、今般、そういったインターネット等のサイト等を利用した方法というのも、かなり浸透してきてありますので。","id":"exchange-043"},{"speaker":"新妻委員","kind":"質問・要望","question":"歩行喫煙防止の過料について伺います。現状確認ですけれども、令和４年度が９万６,０００円、令和５年度１３万４,０００円、令和６年度は８万５,０００円と、決算書で確認させていただきました。令和７年度の現状、今現在までの過料の徴収の金額を伺い、今後の見通しを併せてお聞きいたします。","respondent":"澤邉生活安全担当課長","answer":"令和７年、ここにつきましては８月末の数字ですけれども、指導件数が７７１件、過料については７６件を取っております。本年７月１日に条例が改正されたということもありますので、今後この条例の趣旨の周知、それから取締りを進めてまいりたいと考えています。","id":"exchange-044"},{"speaker":"新妻委員","kind":"確認","question":"７６件で７万６,０００円ということですね。ありがとうございました。たばこの課題は本当に大きいなと考えています。本年３月の予算特別委員会で、若林副委員長もたばこ税の質疑から、今後の喫煙に関する評価と、また喫煙所整備の考え方、取組を確認しております。時間がなくなってしまいましたので、そこの部分について改めて確認いたしますけれども、７月１日から喫煙に関する取組が強化されました。","respondent":"澤邉生活安全担当課長","answer":"警備会社の委託については、本年度から実施している事業でございまして、昼間が９６回、深夜と早朝が２４回となっております。重ねて喫煙所の整備についてご質問を頂きました。喫煙所の整備につきましては、公用地を含めて検討していますが、なかなか難しい点もあります。","id":"exchange-045"},{"speaker":"新妻委員","kind":"提案","question":"具体的にしていただきまして、よろしくお願いいたします。先日９月２１日に行われた中高生リバースメンター事業のプレゼンテーションでも、「たばこの被害を受けない、与えない社会へ」と題し、問題・課題解決の提案がされておりました。しっかりと具体的に民間にもアピールしていただきながら、望まない受動喫煙対策、たばこ被害を受けないように取組をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"１３５ページ、災害時応急物資確保費、１０７ページ、移動教室経費についてお伺いします。最初に、１３５ページ、災害時応急物資確保費に関連しまして、先日ありました９月の大雨対応についてお伺いさせていただきたいと思います。最初に、品川区内にある土のう置場は、私は５４か所と認識しているのですけれども、確認させてください。","respondent":"森道路課長","answer":"土のう置場です。品川区内で５６か所、１万４,１５０袋を用意しています。","id":"exchange-047"},{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。私のお店も旗の台三丁目商店街に面していまして、私の店も浸水で、膝までつかって、水を掃き出すのに２時間半かかったところであります。東口でも半地下が水没したなど、旗の台も被害があったところであります。９月１８日現在で事業所は２４８件という報告がございましたけれども、今現在どのぐらいなのか教えてください。","respondent":"羽鳥防災課長","answer":"最終の被害状況をお答えします。９月２９日１５時現在です。事業所の被害については３２６件になってあります。住家の床上浸水は５０２件、床下浸水は２７４件という状況です。","id":"exchange-048"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"事業所についても、大小なりとも１万円というお見舞金を頂くのは本当にありがたいことなのですけれども、ぜひ今後、要綱で、もう少し事業所に対してのお見舞金を引き上げていただきたいというのが私の要望であります。これは要望とします。それと、土のうが５６か所ある中で、本当に急に、予想がつかないような今回の大雨でした。その辺のご見解をお聞きしたいと思います。","respondent":"星災害対策担当課長","answer":"確かに水のうは非常に有効になるものだとは思っておりますので、今後、防災訓練もしくは水防の訓練といったところで、区民の皆様に周知していければと考えているところです。","id":"exchange-049"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"水のうは、便器から吹き上がってくるときにでも有効的に防げると思うので、ぜひ今後、対策を深めていただきたいと思います。次に１０７ページ、移動教室経費について質問させてもらいます。所管は違うのですけれども、品川区区民保養所のあり方検討会が合計２回あったという報告を受けました。教育の観点から、移動教室という意味というか意義、目的を、改めてご紹介いただきたいと思います。","respondent":"石井学務課長","answer":"今、様々、有識者検討会の議論や、あと今後の方針についてもいろいろ議論されていますけれども、非常に教育的意義が高く、引き続きやっていきたい。この施設というものについては教育的な意義があると考えています。","id":"exchange-050"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今後これを改修などとなると、経費が１７億円という試算が出ていますけれども、光林荘はぜひ残していただきたい。保養所事業は廃止というので私はいいと思うのですけれども、ぜひこれは教育施設として今後も利用していただきたいと、私から、要望します。今まで日光という場があって、ここが廃止になると、ではどこでどういうふうにやっていくのか。その辺について、お尋ねさせていただきたいと思います。","respondent":"石井学務課長","answer":"例えば慣れた場所で行うことによって教員負担の軽減や、あと子どもたちの安全がどのように確保できるか。そういうところも踏まえて、これから様々な検討を含め、議論していきたいと考えております。","id":"exchange-051"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"所管課と連携して、教育という観点から、ぜひ今後もやっていただきたい、続けていきたいと思いまして、私の要望として、終わりとします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"澤田委員","kind":"質問・要望","question":"本日は、６５ページ、なぎさ会館についてお伺いします。令和６年度の事務事業評価で３年以内の廃止を検討となっていますが、現在もその方向性で間違いないでしょうか。","respondent":"築山戸籍住民課長","answer":"廃止になった場合の跡地活用につきましては企画部門で進めることになりますが、当該施設周辺の将来の姿を見据えながら、行政需要や地域ニーズなどを総合的に勘案し、検討してまいります。","id":"exchange-053"},{"speaker":"澤田委員","kind":"質問・要望","question":"区民の関心が高まっている葬儀・火葬場について、関連してお伺いします。そこでお伺いします。以前から臨海斎場へのアクセスのニーズや課題について、我が会派でも議論を重ねているところですが、臨海部広域斎場組合議会を構成する５区の区長と議長の間で、交通アクセスについてどのような議論がなされているのか、また要望などはあるのか、お聞かせください。","respondent":"築山戸籍住民課長","answer":"臨海部広域斎場組合議会からの要望を受けまして、臨海斎場では令和６年３月に、葬祭業者を通じて臨海斎場へのアクセスの実態調査を行いました。","id":"exchange-054"},{"speaker":"澤田委員","kind":"質問","question":"それと、次は臨海斎場への距離なのですけれども、品川区では近隣５区の中では恵まれているほうかと思います。タクシーで向かった場合には４,０００円前後、費用がかかってしまうため、料金が高いということもさることながら、同時に台数不足もあり、高齢者の方にとっては利用が難しいという声もお聞きしています。区として把握している区民のお声などありましたら、お聞かせください。","respondent":"築山戸籍住民課長","answer":"直接、品川区に区民の声が届いているわけではありませんが、臨海斎場で行ったアンケートから、送迎バスを運行してほしい、バスの本数を増やしてほしいといった声があることを確認しております。区民委員会においてもアクセス改善についてのご要望を頂いているところです。","id":"exchange-055"},{"speaker":"澤田委員","kind":"確認","question":"先ほどの質問にも重ねてしまいましたけれども、いろいろな方面からアクセスの向上を望む声があるのだなということを確認させていただきました。ほかにも、ＡＩオンデマンド交通の活用もあります。喪主が地元地域や最寄り駅などから臨海斎場へのマイクロバスを貸し切る際の費用は３、４万円から６万円近くと高額です。ぜひ前向きにご検討いただければと思いますが、お考えをお聞かせください。","respondent":"築山戸籍住民課長","answer":"その一方で、火葬を含めた葬儀全体に係る区民の費用負担を軽減するため、区としては引き続き、臨海斎場において適正な価格帯を維持できるよう、しっかりと確認していくとともに、現在、区民の葬儀費用負担軽減のための区民葬儀において、２３区共通の補助制度を検討中ですので。","id":"exchange-056"},{"speaker":"澤田委員","kind":"質問","question":"ぜひ人生最後のお見送りをするという機会を、一人でも多くの方が逃すことなく維持できる品川区であってほしいと願っています。続いて、おくやみコーナーについてお伺いします。令和６年１月４日におくやみコーナーが開設され、悲しみの中、手続に追われる区民の負担軽減に大きく貢献してきたと思います。一定期間が過ぎた今、効果検証は行われたのでしょうか。課題などありましたらお聞かせください。","respondent":"築山戸籍住民課長","answer":"当日手続に必要な書類を集める方法を教えてくれたという、感謝の声を多く頂いております。課題としましては、予約の際に、電話かウェブ予約なのですけれども、ウェブ予約がしづらいといった意見、また、予約制ではなくて当日に対応してほしいといった声を聞いているところです。","id":"exchange-057"},{"speaker":"澤田委員","kind":"質問","question":"その中で私が聞いた課題なのですけれども、年金の手続をできるだけ早くしなければいけないということを情報としては知っている方たちというのが、いつまでにやらなくてはいけないのかというところまではご存じなくて、せっかくワンストップでおくやみコーナーで手続が行えるにもかかわらず、先行して年金のみを行ってしまうというお話をお聞きしました。区としてのお考えをお聞かせください。","respondent":"築山戸籍住民課長","answer":"ホームページやおくやみハンドブックにつきましても、区民のお声を踏まえまして、より分かりやすくなるよう、ブラッシュアップしていきたいと考えております。予約につきましても、改善に向けた検討もしてまいりたいと思います。","id":"exchange-058"},{"speaker":"澤田委員","kind":"質問・要望","question":"少しずつ少しずつ改善が進んでいって、より一層、皆さんが使いやすくなるように、取組を行っていただければと思います。最後になりますけれども、故人が国民健康保険に加入していた場合、喪主が申請し、葬祭費を受け取ることが可能であります。品川区でも手続の利便性向上のために、ぜひ電子申請、ＤＸ化をさらに進めていただきたいと要望いたしますが、ご見解をお聞かせください。","respondent":"山下国保医療年金課長","answer":"手続の特性から、窓口での件数が一定、多いところではありますけれども、選択肢の拡充、また利便性の向上という観点から、そちらの電子化についても、引き続き取組を進めてまいりたいと考えています。","id":"exchange-059"},{"speaker":"中塚委員","kind":"質問・要望","question":"６４ページから始まる使用料及び手数料について、区民プールのロッカー代と子どもの料金の無償化を求めて質問いたします。この間、取り上げてきました区民プールのロッカー代１０円ですが、今年の夏からリターン式に変更されて、１０円が徴収されずに戻ってくるようになりました。そこで、ロッカー代の変更についてどのような検討がされたのかを伺います。受益者負担の考えに変更があったのか、伺います。","respondent":"大友公園課長","answer":"これまでは、ロッカー数などの状況を踏まえまして１０円の料金を徴収しておりましたけれども、利用者の利便性向上を図るために、プール営業開始前の設備点検に合わせて、返却式に変更したところです。","id":"exchange-060"},{"speaker":"中塚委員","kind":"質問","question":"利便性の向上ということですけれども、２つ目に受益者負担の考えに変更があったのかと伺いました。改めてご答弁ください。","respondent":"大友公園課長","answer":"１０円の徴取というところについては、運用面のところで徴収していたところですので、受益者負担の考えに変更があったというところではございません。","id":"exchange-061"},{"speaker":"中塚委員","kind":"質問・要望","question":"今年８月１日の来年度予算編成の基本方針、依命通達ですが、使用料及び手数料についての記述が変わりました。私は、子どもからもプール使用料を徴収することについて繰り返し無償化を求めつつ、この受益者負担の克服を求めてきました。そこで今回の依命通達ですが、従来の受益者負担を見直すものなのか、伺います。改めて区民プールの子ども料金を無料にすべきと思いますが、いかがでしょうか。","respondent":"崎村企画課長、大友公園課長","answer":"こういった状況を踏まえて、施設所管課において受益者負担についてしっかりと検証・検討していただくために、より分かりやすい表現とさせていただいたというのが、今回の依命通達の変更の理由です。この受益者負担の考えから、料金を無料にするという考えは、現在のところございません。","id":"exchange-062"},{"speaker":"中塚委員","kind":"質問","question":"維持管理・人件費などは、受益である利用者が負担すべきだという説明だと思います。義務教育の無償化か。保育園やすまいるスクールは無償化を進めてきましたが、なぜ区民プールだと、同じ子どもでも料金を取るのか。ならば私は、同じ子どもなのだから、区民プールも少なくとも子どもから取るのはやめようと判断すべきだと思いますけれども、いかがでしょうか。","respondent":"大友公園課長","answer":"一部、繰り返しの答弁となりますけれども、利用用途を限定し、また利用者も限られる施設ではありますので、受益者負担の考えが基本となっているところです。","id":"exchange-063"},{"speaker":"中塚委員","kind":"質問","question":"プールは人気があるからとご説明でしたが、認可保育園もとても人気があると思います。待機児童問題が深刻なときには、この議会でも何度も様々な議論がありました。伺いたいのは、区民プールは同じ子どもでも、なぜお金を取るのか。保育園やすまいるスクールでは無償化してきましたが、ほかの事業とプールは何が違うのか。改めて伺います。","respondent":"大友公園課長","answer":"先ほども申しましたとおり、受益者負担の考えが基本となるというところではありますけれども、さらにより多くの利用を図るということで、無用の予約を防止するという目的もあって、こちらは利用料金の徴収をしているというところになってあります。","id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"これまで小学生と中学生とされてきましたが、なぜ子ども料金は中学生までなのか、その根拠はどこから来ているのか、伺います。１８歳選挙権の議論ですので、やはり小学校・中学校・高校生までを子ども料金とすべきだと思いますけれども、いかがでしょうか。これはプールだけでなく、品川区の施設全体にも関わりますけれども、ぜひこれを機にご検討いただきたいと思いますが、いかがでしょうか。","respondent":"大友公園課長","answer":"その結果、高校生は大人料金とさせていただいておりまして、中学生と小学生、それぞれ料金を設定しています。区民プール以外の各施設について、それぞれの施設ごとの考えもあるですので、一律で変更するということは難しいのではないかと考えております。","id":"exchange-065"},{"speaker":"松永委員","kind":"質問","question":"私からは、１３４ページの災害対応力向上支援事業補助金について、１３５ページの災害時応急物資確保費について、１５５ページの歩行喫煙防止過料について、併せて１５０ページのふるさと納税寄附金について伺います。こうした方へ、どういった方法で対応されているのでしょうか。その外国人に対して、もしいらっしゃったら、どういった形で対応されているのか、伺いたいと思います。","respondent":"澤邉生活安全担当課長","answer":"そのときの周知の方法ですけれども、基本的にはチラシを持っておりますので、それをお示しして、品川区の条例が改正した旨についてご説明します。外国人の方の過料徴収については、現在まで把握はありません。よろしくお願いします。","id":"exchange-066"},{"speaker":"松永委員","kind":"提案","question":"そこでご提案なのですけれども、結構先ほども述べさせていただきましたが、品川区版の携帯灰皿というのは結構人気があって、それを買いたいのだけれども、どうすればいいかというので、伺ったことがあるのですけれども、そうしたところも、ふるさと納税も含めて、一品に加えていただければどうかということと、あとは、１９９１年７月から１９９５年５月まで。","respondent":"澤邉生活安全担当課長、宮澤税務課長","answer":"しかしながら、なかなか難しい点もございまして、現在はどちらかといいますと、民間の店舗や土地といったところを中心に、補助事業を充てまして、鋭意、設置を図っているところです。クラウドファンディングにつきましては、区が実施するクラウドファンディングに応援していただければ、ふるさと納税、控除の対象になっているです。","id":"exchange-067"},{"speaker":"松永委員","kind":"質問","question":"ぜひ、喫煙される方の観点も含めてご検討いただければと思います。１３４ページの災害対応力向上支援事業補助金について伺います。今後３０年以内に、７０％から８０％と言われております南海トラフ、首都直下型地震というのが喫緊の課題となっております。例えば、消火器やＷｉ－Ｆｉ、発電機、スタンドパイプなど、いろいろあると思うのですが、どの部類になるのでしょうか。お知らせください。","respondent":"羽鳥防災課長、遠藤防災体制整備担当課長","answer":"私からは、災害対応力向上支援事業補助金のうち、防災区民組織育成費についてお答えします。こちらは、都が防災区民組織に向けて補助している事業です。私からは、災害時応急物資確保費、初期消火体制強化費についてご回答いたします。災害時応急物資確保費についてですが、こちらは、携帯トイレを７６０箱、１箱当たり２００回分、合計１５万２,０００回分を購入しております。","id":"exchange-068"},{"speaker":"松永委員","kind":"質問・要望","question":"内容が分かりました。その中で家庭用消火器についてなのですが、これは、消費期限というのですか、期限があるです。その機会として、例えばマンションの防災訓練や、各総合防災訓練が今後行われると思いますので、せっかくみんな集まってこういった訓練をやるので、そうしたところで消火器についての確認をする。取りあえず時間になりますので、以上にします。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"つる委員","kind":"質問","question":"５２ページ、特別区民税で、ミドル期シングルやベーシックサービス、それから社会的処方の関係について伺っていきたいと思います。その中で、東京都についてはもう既に、ミドル期シングルというのが５０.２％というのが出ていて、また２３区で見ても３割弱がそういう層になってきているということ。","respondent":"宮澤税務課長","answer":"いわゆるミドル世代で中年世代というところで抜き取りますと、４０代・５０代の全体の納税義務者数の中で大体約６０％以上、４０代・５０代の納税義務者数のうち約６５％近くが単身世帯という状況という傾向にあります。","id":"exchange-070"},{"speaker":"つる委員","kind":"提案","question":"これは、議会からの質問や、区民のお声、アンケートなど、様々なところを行政がしっかりと受け止めていただいて、行政でしっかりと施策をつくっていただくという部分もあろうかと思うのですが、そうした声も含めて、公的負担のところにおけるベーシックサービスの展開の議論の場というところについて、今現状、議会側からも様々な提案があると思うのですが、そこの部分の議論の場というのは、どういう場所で。","respondent":"崎村企画課長","answer":"今年度の施政方針でも申し上げましたけれども、人間が自分らしく暮らしていく上で不可欠な生活の基礎となる行政サービスを、所得制限なく全ての人に提供するというような考え方、委員がおっしゃるようなベーシックサービスの考え方に基づいて。","id":"exchange-071"},{"speaker":"つる委員","kind":"提案","question":"人口の動向といったことを考えると、本当にそれを早い段階で考えていくこと。まさに今、品川区が自治体としても、ある意味で国を先駆的に引っ張っている施策展開をしているのかなという理解もある中で、そういう部分でしっかりと、これまでも会派としても様々な提案をさせていただきましたけれども、しっかりとそこで、共感・納得を頂けるような施策展開をお願いしたいと思います。これは社会的処方です。","respondent":"東野福祉計画課長","answer":"このミドル期シングルの層といいますと、なかなかつかまえにくい部分というのがあると思うのですけれども、例えば今取り組んでおります重層的支援体制整備事業と孤独・孤立対策のプラットフォームの事業があります。","id":"exchange-072"},{"speaker":"つる委員","kind":"質問・要望","question":"いろいろ多岐にわたる施策の話だったかと思いますけれども、とにかく品川区にいることで、本当にそれぞれ区民の一人一人に、まさに幸福を感じていただくということが、品川区のまさに売りになっていくと思いますので、これからもそうした施策展開を、全国に先駆けてやっていただきたいと思います。様々な款別質疑で伺っていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、９７ページのすまいるスクール運営費から伺います。アレルギーの対応についてのご指摘です。念のために、繰り返しですが、指導した内容が悪いと言っているのではなくて、それを求めるなら、契約書の仕様書に明記して、それに対応する契約金額の上乗せも必要なのではないかという趣旨の質問ですので、それを踏まえてお答えいただければと思います。","respondent":"上野子ども育成課長","answer":"委員からのご質問ですけれども、仕様書の中に、そういったアレルギーに対する対応についての記載があるかというご質問だったかと思いますけれども、仕様書の「児童指導および生活安全指導」という項目がございまして、そちらに。","id":"exchange-074"},{"speaker":"吉田委員","kind":"質問","question":"それは読みました。業務委託契約の仕様書ですね。昼食指導の項目があります。ただし、食物アレルギーがある児童に対しては個別に対応すること。それで、その次の項目には、医療行為を除くアレルギー発症時の対応とあります。それで、私の見解では、エピペンの使用は明らかに医療行為と考えるのですけれども、医療行為ではないのでしょうか。ごめんなさい。その点についてお聞かせください。","respondent":"上野子ども育成課長","answer":"医療行為を除くアレルギー発症時の対応というのが、エピペンの使用に当たるかどうかというところですけれども、医療関係者のみ対応できるというものではないと考えておりますので、研修の中で、そこは対応できる範囲内と、こちらでは考えております。","id":"exchange-075"},{"speaker":"吉田委員","kind":"質問・要望","question":"おっしゃるとおり、医者以外でも、緊急の場合に医者を待っていられないので、なのでエピペンというものの使用が求められたし、それをされたのだと思います。ただ、やはり医療行為なのではないかというのと、それを契約相手に求めるのであれば、契約書の中に、せめて仕様書の中に明記すべきだと思うのですけれども、契約の在り方として伺っていますので、その点についてお聞かせください。","respondent":"上野子ども育成課長","answer":"繰り返しになってしまうのですけれども、医療関係者のみ対応するものではないという見解の下に仕様書を作成しておりますので、こちらについては記載のとおりで問題ないと、こちらは考えているところです。","id":"exchange-076"},{"speaker":"吉田委員","kind":"質問・要望","question":"本来であれば対等な関係なのですけれども、どうしても区から受託しようとしている事業者と区の関係でいうと、区のほうが優位に立ってしまうのではないかと想像するのですが、そうであるならば、優位に立ったほうがきちんと、この中身にはここまで含まれておりますということを説明して契約を結ぶべきだと思うのですけれども、この契約については、そうだとおっしゃる。","respondent":"上野子ども育成課長","answer":"委員がご指摘の、すまいるスクール仕出し弁当昼食対応補助業務委託ですけれども、こちらにつきましては、昼食場所の準備、仕出し弁当の受領、保管場所の……。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"今回の決算書でも大きく増収になっています。前年度決算と比較して、主な項目でどれだけ増えているのか、まず伺います。そして基金も、出納閉鎖時で幾らになったのか伺いたいと思います。午前中の質疑で、２,２００人ですか、高所得者が増えていると。これが、どこの層が増えているのかというのも伺いたいと思います。","respondent":"加島財政課長、宮澤税務課長","answer":"令和６年度特有の歳入増の事情といたしましては、地方特例交付金という形で、定額減税が実施された際の減収補填特例交付金２０億円が増となっております。特別区民税につきましても、納税義務者数の増等により１１.７億円の増。午前中、高所得の方の増加という部分ですけれども、いわゆる合計所得金額が１,０００万円以上の方です。","id":"exchange-078"},{"speaker":"のだて委員","kind":"提案","question":"高所得者の方も１,０００万円以上の方が増えているということで、これだけ豊かな財政力があるということが分かりました。その一つとして、義務教育の無償化をさらに進めるために、移動教室無償化を提案したいと思います。今年度から中学生の修学旅行費無償化が始まりましたが、移動教室は無償化されませんでした。ぜひこの移動教室も無償化できたらと思いますが、いかがでしょうか。","respondent":"石井学務課長","answer":"現在、移動教室の宿泊費やバスの借り上げ費用等は公費負担をしており、これは従前から実施しているものです。一部、食費負担等はありますけれども、教育に必要な部分では十分に無償化されていると考えています。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問・要望","question":"食費の部分は負担しているということですので、事業費から見れば約６８０万円ですので、区の財政力であればすぐできると思います。ぜひやっていただきたいと思いますけれども、何か課題があるのかどうか、伺いたいと思います。さらに、５年生では林間学園も行われています。この林間学園も無償化していただきたいと思いますが、いかがでしょう。","respondent":"石井学務課長","answer":"無償化事業を今後推進していくことに関しましては、なるべく負担の大きいところで、そこから財源を振り分けていくという考えで、これまで実施してまいりました。令和７年度の修学旅行無償化につきましては、まさに保護者負担のすごく大きなところで無償化を実施しています。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問・要望","question":"この林間学園でぜひやっていただきたいと思うのですが、林間学園の意義をどのように考えているのか伺います。無償化にもぜひ踏み出していただきたいと、改めて伺いますが、いかがでしょうか。","respondent":"石井学務課長","answer":"これらはきちんと検討せねばならないことであると考えています。","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ無償化も進めていっていただきたいと思います。学校は区民避難所にもなります。防災面で考えると、スフィア基準では女性と男性の便器数、３対１が示されています。ぜひ今後、学校改築をしていく上で、女性の便器を増やすことを検討すべきだと思いますが、いかがでしょうか。現在のこの女性と男性の便器の数、そして比率が何対何か、伺いたい。","respondent":"荒木学校施設担当課長","answer":"平時の学校改築時におけるトイレの器具数の考え方ですが、空気調和・衛生工学会が提唱する衛生器具の適正個数算定法に基づき、適正な個数を確保しているという状況です。男女比は１対１としております。","id":"exchange-082"},{"speaker":"えのした委員","kind":"質問・要望","question":"私からは、１５１ページのトイレトラック購入分、１６８ページの環境政策加速化事業補助金、時間があれば、９９ページのヤングケアラー支援事業についてお伺いします。会派で要望し、２３区で初めて導入されたトイレトラックを歓迎しております。１,４２３万２,３００円。そこでお伺いします。ガバメントクラウドファンディングを実施した効果についてお知らせください。","respondent":"遠藤防災体制整備担当課長","answer":"委員のクラウドファンディングを実施した効果についてお答えいたします。委員からご紹介いただいたとおり、１,４００万円を超える寄附を頂いたことから、今回のトイレトラックの購入に関しまして、財政負担を大きく軽減することができたところです。","id":"exchange-083"},{"speaker":"えのした委員","kind":"質問","question":"財政負担も軽減されて、区民の直接の支援、そしてまた名前ですか、企業、個人名。本当にいいアイデアだと思います。愛着が湧くいいアイデアだと思います。そこで、また改めてお伺いしますが、クラウドファンディングはどのような形で実施されたのでしょうか。教えてください。","respondent":"遠藤防災体制整備担当課長","answer":"理由といたしましては、税務課で実施しているといったところと、他社のサイトの利用料金を比較したところ、最も安いといったところを確認させていただきましたので、ふるさとチョイスを選定して、こちらでふるさと納税を実施したといったところになってあります。","id":"exchange-084"},{"speaker":"えのした委員","kind":"確認","question":"私も、ふるさとチョイスを確認して調べたところ、国内最大級のふるさと納税総合サイトで、企画・運営するのは、品川区に本社を構える株式会社トラストバンクということで、募集当時のテレビＣＭでお笑い芸人のサンドウィッチマンさんが出演していましたので、周知啓発にも認知度や効果が高かったのかと考えています。今後の展開についてはいかがでしょうか。お知らせください。","respondent":"遠藤防災体制整備担当課長","answer":"トイレトラックの今後の展開ですが、防災力強化に向けた発信を行っていくといったところで、区民の関心を引くために、いろいろ機会を捉えて実施していきたいと考えております。","id":"exchange-085"},{"speaker":"えのした委員","kind":"確認","question":"防災力の強化は大変重要だと考えています。１７件の派遣。私も、しながわシティラン、そして運河まつりを確認させていただきましたが、実際に被災した際にはトイレトラックを使用していただくわけですから、ぜひ区民の方にも、防災訓練などでも使用できないかと考えていますが、区のご見解をお伺いいたします。","respondent":"遠藤防災体制整備担当課長","answer":"訓練の際には、トイレトラックが階段を通じてトイレの個室に入るという性質上、比較的広い場所で展開するといったところで、訓練を通じて皆様方に周知していくことを考えているところです。","id":"exchange-086"},{"speaker":"えのした委員","kind":"提案","question":"以前の決算特別委員会でも、平時の有効活用のご質問、またご提案で、これを活用した際の清掃費について質問したところでありますけれども、ぜひ体験を通じて、だからこそ寄附につながったりとも考えておりますので、この課題を解決できるように要望します。そこでお伺いします。令和６年度に、環境教育に関する講座やイベント等の取組を実施されていれば教えてください。","respondent":"中西環境課長","answer":"環境に関する取組についてのお尋ねです。環境課では、エコルとごしにおきまして、年間７６回ほどのワークショップや講座、それから８回ほどのアウトリーチ講座、３回の大型イベント、８回の企画展示などを実施したところです。","id":"exchange-087"},{"speaker":"えのした委員","kind":"確認","question":"年間７６回、環境講座をおこなっていると、確認ができました。大型イベント、これはエコルフェスのことだと思いますが、私も毎年、初回から伺っており、今年も４月に開催された「エコルフェス－ＳＰＲＩＮＧ－」では、大変多くの親子連れでにぎわっており、地域に根差した行事に育っていると実感しております。そこでお伺いします。ブルーカーボン、グリーンカーボンの取組があれば教えてください。","respondent":"中西環境課長","answer":"ブルーカーボンに関してですが、昨年度ですが、ＮＰＯの方にお願いいたしまして、アマモを通じて海について学ぶ、海の教室というものを３回、実施しまして、ブルーカーボン、生態系について学ぶ機会を提供したところです。今年度です。","id":"exchange-088"},{"speaker":"えのした委員","kind":"質問・要望","question":"品川区はアマモ。これは、コアマモと多分、同じような種類なのでしょうか。サンゴも確認が取れました。特徴でもある河川や運河などの水辺があります。ブルーカーボン、グリーンカーボン等に関する取組を評価して、今後、拡充も要望いたします。品川区では、健康ポイント事業も実施されておりますが、ゼロカーボンポイント等の取組も、区民の方への啓発や理解に有効だと考えますが、区のご見解をお伺いします。","respondent":"中西環境課長","answer":"この枠組みでどういったものを、入れるのか、ご家庭だけにするのか、事業者まで対象にするのかといったところ、それから、区で実施しているほかのポイント事業との連動性など、課題も様々あろうかと思いますが、ゼロカーボン達成に向けた取組の手法の一つとして。","id":"exchange-089"},{"speaker":"えのした委員","kind":"意見","question":"他自治体の動向でおっしゃったように、プラスチックハンガー、これは私もワイシャツをクリーニングに出すので、本当に日々、もったいないなと思いながら、資源に入れているところであります。今後も社会全体として、そして子どもや子育て世代を中心としたウェルビーイングの向上を図り、さらなる周知啓発も含め、ゼロカーボン達成に向けた取組を進めていただけるようお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-090"},{"speaker":"やなぎさわ委員","kind":"提案","question":"ちょうど１年前の１０月の決算特別委員会で、私がこの問題を取り上げまして、同性カップルも異性のカップルと同じように、事実婚の方と同じように、表記を夫・妻（未届）としてみてはどうかという提案をさせていただきました。というところで、直近の３月の予算特別委員会のときに３つほど挙げられていた課題なのですけれども、どのようにこれを解決されたのか、その内容も含めてお伺いしたいと思います。","respondent":"築山戸籍住民課長","answer":"課題の解決についてです。１つは、実際に（未届）の運用をした場合に、発行場所や時間等に制限がかかるという問題がございました。こちらにつきましてはシステムが標準化されておりまして、アナログでの対応となることが理由です。","id":"exchange-091"},{"speaker":"やなぎさわ委員","kind":"質問","question":"当事者の方に寄り添った様々な対応を取っていただいて実現したということで、まさにこれは「しあわせ多彩区」ではないかと思います。誠に感謝申し上げます。というところで、これは本来であれば、国が全国一律の制度として取り扱うべきだと個人的に思うのです。国に区長も１２月に申入れをしたということですが、その後の国の動きというのはどのように把握されていますでしょうか。","respondent":"築山戸籍住民課長","answer":"国からの反応は、今のところございません。","id":"exchange-092"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ぜひこれは、課長会や、森澤区長であれば２３区の特別区長会で、今後も議題に上げていただいて、国を動かしていただければと思います。これは要望で終わります。令和６年の目玉の施策でありました介護職員等居住支援手当ですけれども、これは全体で５.４億円の予算、介護職員、ケアマネジャーを合わせて４.４億円ぐらいの予算かと承知しておりますけれども、この手当の執行率はいかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"介護職員の居住支援手当についてのご質問にお答えします。こちらの決算額につきましては、記載のとおり１億８,５１４万４,０００円となっております。予算に対しての執行率は４１.５％ということになります。","id":"exchange-093"},{"speaker":"やなぎさわ委員","kind":"質問","question":"４１％というのは少し寂しいなと思っています。これはつまり、大体３,１５０人ぐらいを人数として見積もっているのですけれども、そのうちの、全体１,２００人ぐらいしか受け取れていないです。この原因というのはどのように分析されていますでしょうか。","respondent":"菅野高齢者福祉課長","answer":"実際の支援人数につきましては１,６０２人で、３,７２０人を見込んでいたので、その約７割の方という人数となっております。","id":"exchange-094"},{"speaker":"やなぎさわ委員","kind":"提案","question":"実際、予算特別委員会で取り上げられたときも、別にこういった質疑などはなかったし、私もこういったことは予想外だったので、当然、トライ・アンド・エラーで修正していけばいいのかなと思っているところで、個人的な私の提案としては、そういう事業所に対しては、もう事業所はやらないと言っているので、その部分の介護職員に対してだけ、例えば個人申請をしてもらうなどといったことで。","respondent":"菅野高齢者福祉課長","answer":"ご提案いただいた部分もありますが、今まで執行率が低かったことの課題として、今年度につきましては、５月に受付を開始しまして、７月から順次交付ということで、一時金の手当の立替えが事業者のほうでないように、早めに交付させていただいているなどの対応をしています。","id":"exchange-095"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"それと併せてやはり、この問題、介護職員の給料が低いというのは、もう国の問題に帰結すると思います。ぜひ今後も様々、会議体、課長会も含めて、国に対して介護事業所の報酬引上げを求めていっていただきたいと思うのですけれども、その点について最後にご意見があればお願いします。","respondent":"菅野高齢者福祉課長","answer":"介護報酬の引上げ等につきましては、国の動向を注視しながら、実態に合うように適正な介護報酬を望んでいきたいと思います。","id":"exchange-096"},{"speaker":"大倉委員","kind":"質問・要望","question":"１３５ページの災害時応急物資確保費、関連して、先ほどもありましたが、雨の対応と、１０７ページの学校ＩＣＴ活用経費で伺えればと思います。事前に登録制ということだと思うのですが、こういったところの登録者の数や、今後の周知、こうした方たち、品川区の中でも事業所が困っているなら助けたいというお声が結構ありましたので、その辺をしっかり進めていければいいのかなと思って質問します。","respondent":"石井学務課長、羽鳥防災課長、豊嶋生活福祉課長","answer":"１人１台端末が来年度全部更改することに合わせまして、センターサーバーの接続方式から各校の直接接続方式という形で、接続方式を変更することにより。見舞金につきましても、中身をもう一度精査して、内容の見直し等、検討を進めてまいりたいと考えています。今回、一日、二日の募集期間でおよそ２０名程度集まったと聞いてあります。","id":"exchange-097"},{"speaker":"大倉委員","kind":"質問・要望","question":"確認したいのですが、４年だと、使用頻度が高いところだと電池がもたないのではないかと。それで、あればぜひリースの期間も含めて対応を考えていただきたいと思いますが、いかがでしょうか。そうしたことも含めて、事前の周知というところを、ぜひこういった災害時の対応を募っていくというのは一定できるのではないかと考えていますので、その見解について伺いたいと思います。","respondent":"石井学務課長、豊嶋生活福祉課長、藤村総務課長","answer":"令和２年３月に導入して、これを５年契約という形で、今進めてきたところです。社会福祉協議会との災害ボランティアの説明をします。寄附金についてですが、災害時の寄附金ということで、ガバメントクラウドファンディング等を活用してというようなお話でございましたが。","id":"exchange-098"},{"speaker":"大倉委員","kind":"質問・要望","question":"ＩＣＴのほうは、ぜひ聞いてみてください。利用が多いところは、そういった活用がしにくく、事業のさらなる充実のところでハードルになったりしないようにしていただきたいというところ。寄附についてもボランティアについても発信等、周知をしっかりしていただいて、事前に登録していただいて、こういったことを進めていくと、品川区にさらに愛着が湧くのかなと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"須貝委員","kind":"質問","question":"５２ページからの歳入に関連して、令和６年度主要政策報告書、７ページに対して質問します。そして、ウェルビーイング予算。今回はその言葉が出てこないのですが、以前は、ウェルビーイング予算を捻出するために、スクラップ・アンド・ビルドをして、そういう予算を捻出しているということをおっしゃっておりましたが、今回はどうなのでしょうか。教えてください。","respondent":"加島財政課長","answer":"先ほど、幸福を感じている区民というところで答弁申し上げましたのが、令和６年度中に実施いたしました世論調査の中で調べましたところ、８割以上の方が実感しているというお答えがあったことを申し上げたところです。","id":"exchange-100"},{"speaker":"須貝委員","kind":"質問","question":"もともと財政調整や特別区民税による収入がこれだけあるならば、わざわざ捻出しなくてもお金は生まれるわけで、以前、濱野区長のときも、毎年６０億円から７０億円は、基金にお金を回さない限り、プラスとして出ていたのです。それを一部、基金に回すから、濱野さんのときは３０億円から４０億円の黒字だった。本来はもっとあるわけで、基金にさらに回しているわけです。教えてください。","respondent":"加島財政課長","answer":"公共施設、それから義務教育の施設の整備基金につきましても、将来の施設の更新を見据えて着実に積立てを行ったものですので、私どもとしては、この基金の積立ては、将来需要に備えた必要な積立てだと考えております。","id":"exchange-101"},{"speaker":"須貝委員","kind":"質問","question":"先ほど、幸せを感じる人が８割いらっしゃるという話でしたが、我々がまちの中で聞いている話は、ほとんどの方が、もう物価が高くて生活が大変です。それで、年間でもう１０万円、１２万円という出費が増えているのです。実際、大変なのです。そういうことを考えたら、こういう方たちに対してもっと支援、目を向けるということは、やはり区として大事ではないですか。それについてご見解をお聞かせください。","respondent":"加島財政課長","answer":"苦しんでいる区民に目を向けて、そこに合った施策をですけれども、確かに令和６年度を振り返ってみますと、完全失業率も低位で推移していましたし、令和６年の春季労使交渉というものの賃上げというのは３３年ぶりに伸びたところです。","id":"exchange-102"},{"speaker":"須貝委員","kind":"質問・要望","question":"実際、大変ではないのですか。そこで、今、品川区はどうですか。この物価高を見れば分かるのではないですか。なぜですか。これは、多くの国民の声であり、多くの区民の声ではないですか。それで大丈夫ですか。違うのではないですか。もっとその方たちの身になって、気持ちになって寄り添う品川区というものに、やはり決算なり予算なりを持っていかなければ、何のために皆さん、やっているのですか。","respondent":"加島財政課長","answer":"令和７年度はそれをさらにアップデートいたしまして、高齢者につきましても補聴器の助成額の拡大を図っておりますし、家具転倒防止設置助成などを所得制限なく無償化、そのほかにも様々な施策に取り組んでいるところです。","id":"exchange-103"},{"speaker":"塚本委員","kind":"質問","question":"私からは、１４ページから１９ページの一般会計、歳入の全般についてと、１０３ページの道路維持管理費、これは下水道のことについても関連して質問したいと思います。それから、１４２ページの衆議院議員選挙費の３点で。現状で、実施する側、施設側の事情等もいろいろあるとは思うのですけれども、現状についてと、今後どのように取り組んでいくおつもりがあるかというところについてお聞きします。","respondent":"今井選挙管理委員会事務局長","answer":"投票支援につきましては、例えば代理投票などにつきましても、東京都のマニュアルに従ってご説明しております。指定施設の説明会は必ず毎回の選挙でやっておりますので、今後とも丁寧に対応していきたいと考えています。","id":"exchange-104"},{"speaker":"塚本委員","kind":"質問","question":"ここについては、歳出のほうに引っ張られるというか、そういう問題もあって、歳入がどんと増えたから歳出もどんと増やそうみたいな話にはなかなかならないのかなというのは承知しているのですけれども、ただし、そういったいわゆる不用額みたいなものが増えているというところだけを見て、安易に歳出・歳入というものを、言ってみれば減税などというところに行くのではなくて、歳入をしっかりと、今。","respondent":"加島財政課長","answer":"こちらを深める中で将来需要をきちんと見極めて、区としてどれくらいの基金が必要なのか、また歳出予想額がどの程度になってくるのかというのは、きちんと予測を立てた上で、今後の区財政というものを運営していかなければいけないと考えております。","id":"exchange-105"},{"speaker":"塚本委員","kind":"質問・要望","question":"この調査の詳細を見ると、２３区は調査対象となった下水管の距離が、区部で１８キロですか。それで、２３区全体として１年以内に対応が必要な緊急度１というものと、また５年以内に対応が必要だという緊急度２というものが、２３区として、それぞれ２００メートル、１,１００メートルと出ていますが、これについて、品川区の対象はどのようになっているのか教えていただきたいと思います。","respondent":"関根河川下水道課長","answer":"その結果ですが、マンホールとマンホールの間の下水道管を１区間とカウントしたときに、原則１年以内に対応を実施する緊急度１が２区間、５年以内に対策を実施する緊急度２が６区間あると聞いております。","id":"exchange-106"},{"speaker":"塚本委員","kind":"質問・要望","question":"区道においては、品川区でもある。都道、国道についてもあるかもしれないということです。この対応につきましては、今後、緊急の、１年以内と言われるものについては、本当にすぐさま対応していくことが求められると思いますけれども、緊急度２のところについても含めて、いわゆる品川区内に耐用年数５０年を超えた下水道管がたくさんある。５０％以上あると。","respondent":"森道路課長","answer":"今おっしゃられた緊急輸送道路は大変重要な動線ですので、一刻も早い改善が望まれると考えています。区としても空洞調査を行っておりますので、そういった結果も下水道局と共有しながら、しっかりと対策を進めていきたいと考えております。","id":"exchange-107"},{"speaker":"西本委員","kind":"確認","question":"先ほど吉田委員から、すまいるスクールのアレルギー対応でエピペンの話が出ました。よく分からなかったので確認です。エピペンは医療行為ですか。医療行為ではなくていいのですか。医療行為であるならば、研修をしないといけないと思うのですが、今回の夏、仕出し弁当を含めて、いろいろ職員の方々に外部委託されたと思うのですが、研修をしっかりとされたのでしょうか。そこをお聞かせください。","respondent":"上野子ども育成課長","answer":"委員のご質問のアレルギー対応のところですけれども、エピペンは医療行為ではないと考えております。それから研修についてですけれども、こちらから指導員、それから委託業者にも、併せて研修は実施しております。","id":"exchange-108"},{"speaker":"西本委員","kind":"質問","question":"おかしいですよね。今ちょっと調べました。調べましたら、エピペンは医療行為と書いてあります。私が調べるのを間違ったのでしょうか。医療行為です。これは、研修しないといけないのです。緊急事態のときに、やっていい。誰でも、エピペンを持って、ぶすっとできますか。できないでしょう。研修しないといけないでしょう。それをきちんとやったのですか。そこをお聞かせください。","respondent":"上野子ども育成課長","answer":"委員のご指摘の研修ですけれども、研修については区としてきちんと対応しております。","id":"exchange-109"},{"speaker":"西本委員","kind":"質問・要望","question":"一応やりましたと。次に、主要施策の成果報告書、７４ページで、経常収支比率は７８.１％ということで、おおむね７０％台行っているということで、非常に黒字財政、健全財政だと言っているのですが、先ほどもいろいろと質問がありました。これは本当に苦しいと思います。本当に困っていることにこそ使っていただきたいと、非常に私は思いますが、その使い方について、どうお考えになりますか。","respondent":"上野子ども育成課長、加島財政課長","answer":"先ほどのアレルギー対応の研修ですけれども、研修を実施して、緊急時に対応するということを想定しているものになります。本当に困っている人にどう対応していくかというところにつきましては、本日も１日ご質疑いただいておりますけれども、地域福祉や孤独孤立対策、またはセーフティネットや生活保護制度など、様々な社会制度と併せて。","id":"exchange-110"},{"speaker":"西本委員","kind":"質問・要望","question":"しっかりそこを見極めて、令和８年度の予算に反映していただきたいと思います。次に、私立保育園についてですけれども、今、私立保育園は６５か所ぐらいあるのですか。それで、１１月の入園可能数を見ると、今の時点で１,１５７人、可能なのです。ですから正直、少子化である現在、閉園する現状もあるし、それにもかかわらず、まだ新設するというのもあるのです。これをどう考えていますか。","respondent":"芝野保育入園調整課長","answer":"私立保育園ですが、全体的には、在籍率が今９０％近くということで、十分、満たされているというところではありますが、地域によっては、やはり需要が足りないところなどというところがありますので、そちらについては。","id":"exchange-111"},{"speaker":"西本委員","kind":"質問","question":"もちろん、地域的には足りないところもあると思います。でも、数からすれば十分なのです。心配は、やはり少子化でありますから、子どもの取り合いにもう既になっているわけです。はい、終わりではなくて、せっかく支えていただいた方々なので、さらに、少し分野は違うかもしれないけれども、有効活用できる、協力していただくというような仕組みをつくれないかなと思うのですが、いかがでしょうか。","respondent":"芝野保育入園調整課長","answer":"私立保育園に対する支援や、あと民間の有効活用のご質問ですが、支援のほうはこれからも引き続きしっかりとさせていただきまして、園の運営の厳しい状況というのは認識しておりますので、しっかり支援をしていきたいと考えております。","id":"exchange-112"},{"speaker":"西本委員","kind":"意見","question":"もう今、研究していくには遅いと思いますが、ぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-113"},{"speaker":"西村委員","kind":"質問・要望","question":"１３４ページ、災害対応力向上支援事業補助金、時間が許せば１３７ページ、治水対策推進助成事業を伺ってまいりたいと思います。先ほどから質問が出ておりますけれども、先日、９月１１日に起きた水害対応について伺ってまいりたいと思います。地域の方々の様々な声を伺いながら、本当に皆さんが助け合って、つながり合ってくださっていた大切さを、改めて強く感じています。","respondent":"羽鳥防災課長","answer":"こちらで様々な情報を共有して運用していたところですけれども、やはり、区民の方にも分かりやすく情報を伝えるということに加えて、庁内に対しても分かりやすく情報を伝えるということが重要だということは再認識したところです。","id":"exchange-114"},{"speaker":"西村委員","kind":"質問・要望","question":"まさに地域センター、支え愛・ほっとステーションもありますので、今後も有事の際には区民の方が地域センターに問い合わせるということは想定されることですので、ぜひお願いしたいと思います。次に、学校の対応についても確認させていただきたいと思います。今回、特に水のたまるエリアが分かったと思いますので、今後の対応に活かしていただきたいと思いますが、ご見解をお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"今回も多くの学校で留め置きを行いましたが、同様の天候不順があった際に備え、雷鳴がある場合の対応や、警報が解除された後の通学路の点検など、児童・生徒の安全を第一に考え、実効性のある対応策を検討してまいります。","id":"exchange-115"},{"speaker":"西村委員","kind":"質問・要望","question":"先ほど庁内の指揮系統と言いますか、そういったご答弁があったと思いますけれども、実際に災害対策本部の動きや区内の被災情報は、先ほどおっしゃったシステムで、全庁的に共有されていたと伺いました。防災課から全庁への被害状況の報告も求められたと思いますが、その結果はどのように現場や職員の皆さんに還元されたのか、伺いたいと思います。","respondent":"羽鳥防災課長","answer":"災害時の指揮系統、情報伝達についてです。災害発生後、毎日、日次の被害状況を、区長をはじめ、関係部課長に共有しています。適宜、対策本部会議、区長報告会という形で、顔を合わせて課題を共有し、今後の対応策というのも話をしてきたところです。","id":"exchange-116"},{"speaker":"西村委員","kind":"質問・要望","question":"災害時の庁内連携の強化を、ぜひとも引き続きお願いしたいと思います。次に、水防訓練について伺いたいのですけれども、同じように区民の方の声から、土のうの用意が間に合わなかった、ポンプや土のうの場所が分からなかったなどという声が聞かれています。そこで、該当地域の水防訓練をぜひ推進してほしいと思います。お考えをお聞かせいただきたいと思います。","respondent":"星災害対策担当課長、羽鳥防災課長","answer":"確かに委員がおっしゃるとおり、水防の訓練というのは非常に重要だと認識しております。今回、町会、商店街、また防災協議会等々から訓練の依頼がありましたら、積極的に行っていきたいと考えているところです。そういったところも含めて、今後、災害時の情報発信のやり方について検討してまいりたいと考えています。","id":"exchange-117"},{"speaker":"西村委員","kind":"質問","question":"最後にシミュレーションについて伺いたいのですが、災害時の様々な計画・シミュレーションをしてきていただいたと思います。想定どおりできたのかというご質問は、ご答弁が難しいかもしれませんが、予想外もあるかもしれませんが、本来は机上で全てのことを予想してできているようになっているはずと理解しております。１２０ミリの雨が降るということは想定に入っていたのか。","respondent":"羽鳥防災課長","answer":"これに対する対応といたしましては、日々訓練を重ねております。そういった訓練の成果ではあります。そういった訓練をやることで、想定外のときにも各部が自主的に対応できたと認識しています。","id":"exchange-118"},{"speaker":"田中委員","kind":"質問・要望","question":"私は、諸収入のうちの１５８ページ、東京臨海高速鉄道株式会社貸付金元利収入、りんかい線に関してと、１６０・１６６ページ、競馬組合関係でお伺いしたいと思います。品川区は現在１.７７％の株主でもあります。一方で私は、品川区としては、ぜひ株主としてずっと居続けてほしい、株をぜひ売却しないでいただきたいと思うのですけれども、今のお考えをお聞かせいただきたいと思います。","respondent":"高梨都市計画課長","answer":"やはり品川区内には、大崎、大井町、品川シーサイド、天王洲ということで、りんかい線の拠点もありますし、委員からご紹介がありました運輸事業の関係性といったところも、しっかりと注視してまいりたいと考えています。","id":"exchange-119"},{"speaker":"田中委員","kind":"質問・要望","question":"私はぜひそういう視点からも、地元の自治体としての意見ももちろん強く言っていただきたいのですけれども、株主としての視点での意見を言っていただきたい。私は、地元の行政として言うのももちろんなのですが、株主としての立場からも、ぜひしっかりと発言していただきたいと思いますが、その視点はいかがでしょうか。","respondent":"高梨都市計画課長","answer":"現在、ＪＲ東日本により建設が進められている羽田空港アクセス線につきましては、事業主体については、どうなるかというところについては区には情報がなく、今現在、ＪＲ東日本により事業が進められているという認識です。","id":"exchange-120"},{"speaker":"田中委員","kind":"質問・要望","question":"私は、これは区の視点であればそういう考え方も１つあるのかもしれませんが、一方で、利益が上がることも目的というか主体とする株主の立場からすると、いや、そうではなくて、もっと利用者を増やしてほしいという観点の考え方もできるのではないかと思われるのですが、そういう視点も含めると、あるいは働き方改革の一環からしても、やはり通勤時間の短縮につながるりんかい線の利用について。","respondent":"宮尾人事課長","answer":"りんかい線を使用するということになりますと、最後の区間のところだけが、賃金がかなり割増しになってしまうということで、これは全庁的に考えますと、かなりの負担、経費の増というところがありますので、ここは慎重に考えたいと思います。","id":"exchange-121"},{"speaker":"田中委員","kind":"質問・要望","question":"競馬場に関してであります。競馬場は、もうご案内のとおり、１９５０年に開設されていますので、今年ちょうど７５年が経過しております。品川区にとっての競馬場の存在というのは、どういう位置づけになっているのか、まずお聞かせいただきたいと思います。","respondent":"藤村総務課長","answer":"観光面というところで言えば、やはり大井競馬場というのが１つの観光拠点ということになっておりますので、区のみならず周辺自治体から、多くの方が来られるスポットになっているのではないかと考えております。","id":"exchange-122"},{"speaker":"田中委員","kind":"質問・要望","question":"私はこの１号交付金を一般財源に入れて、今、いろいろな形で活用されておりますが、連携協定もあるように、周辺のまちづくりを株式会社とも行っていくという観点からすると、この１号交付金は、ある意味、特定財源として、競馬場周辺のまちづくりについて、しっかり有効活用していくという使い方に、今後は進めていくべきではないかと強く思うのですけれども、お考えをお聞かせいただきたいと思います。","respondent":"藤村総務課長","answer":"この１号交付金の、今、一般財源に入れているところを、何か特定財源にというところですが、こちらにつきましては全庁的に考えた上で、どういった形にしていくかを今後の検討事項としたいと思います。","id":"exchange-123"},{"speaker":"田中委員","kind":"質問・要望","question":"最後、７３ページのしながわ中央公園の多目的広場に関してなのですが、多目的広場の一般利用ではなくて、特に学校が優先的に使用する枠ができております。私は、特定の学校に貸し続けるというところに、この課題に対する思いとしての原点が、ずっとあるのですけれども、今現在、学校優先というのは、具体的にどこにどう、何回ぐらい貸しているのか、お聞かせいただきたいと思います。","respondent":"守屋スポーツ推進課長","answer":"私から、しながわ中央公園の多目的広場の学校の優先利用についてお答えいたします。実績につきましては手元にございませんが、主に青稜中学校・高等学校や品川翔英中学校高等学校が活用されているということで認識しております。","id":"exchange-124"},{"speaker":"田中委員","kind":"意見","question":"申込みの基準を見ると、もう半年に１回ぐらいのタイミングでしか借りていないのですけれども、先行して毎年のように使うようにしてしまっては、地元の公立学校が急遽、何かの事情で、今回の水害のようなことも含めて利用できない場合には、私はその場合こそ、地元の公立学校に優先的に使ってもらうような形に改めるべきだと思いますが、最後にすみません。お聞かせください。","respondent":"守屋スポーツ推進課長","answer":"現状としては、そういったところの意見を頂きながら、現状の貸出し方で進めさせていただきたいと思います。","id":"exchange-125"},{"speaker":"田中委員","kind":"意見","question":"その私立学校のパンフレットに、しながわ中央公園が自らの施設かのような写真がありますので、そこは私は改めるべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-126"},{"speaker":"高橋（し）委員","kind":"質問","question":"１７３ページの議会費の議員研修会について伺います。昨年の６月にハラスメントの防止について、区政相談員の和田氏の講演がありました。今年も４月に同趣旨の研修を行いました。結果については、部長級の３割がパワハラを受けた経験があるということが都政新報などで報じられました。品川区の職員は、区民の財産であります。この第９８条の内容についてご説明をお願いします。よろしくお願いします。","respondent":"大澤区議会事務局長","answer":"議会として、調査の結果を請求するということであれば、議会として区長部局に請求するということになるかと存じます。","id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"意見","question":"第９８条は第１項で、地方公共団体の議会は当該普通地方公共団体の事務、途中は省略しますが、これに関する書類および計算書などを検閲し、また中略しますが、報告を請求して、当該事務の管理、議決の執行および出納を検査することができますと。そこで、もし今、局長がお答えしたのですが、この請求があった場合に、行政側、つまり区長は断ることが可能なのか、お尋ねします。","respondent":"川村コンプライアンス推進担当課長","answer":"ご質問の制度について、勉強不足で申し訳ないところがありますが、請求があった場合は、制度にのっとって適切に対応してまいる必要があると考えています。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"制度の趣旨に基づいてということですね。真鶴町や横手市、太田市、伊達市、鎌倉市などで、この第９８条によって、書類の検閲、報告、事務監査または監査委員に対しても求めています。ということで、第９８条で請求できるということを改めてここで確認したいと思います。２つ目ですが、一方で議会はどうかということになります。今年の８月１４日の時点で、１２８団体の１４４条例が確認されます。","respondent":"大澤区議会事務局長","answer":"ほかの議会では、倫理条例やセクハラに関してきちんとした規定を持っている議会もあるとは認識しておりますが、品川区議会においては、まだそこまで踏み込んだ条例や規程をつくっているわけではございませんので。","id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"提案","question":"２３区全ての区議会の議会規則を、見たのですが、やはり２３区全部の区で、規律や懲罰の規定があります。こういったことを検討して研究しながら、資料等を集め、そして条例制定および倫理条例やハラスメント関係の条例をつくる際に、区議会事務局のほうで資料の収集や、その条例に基づく作業等の協力をしていただきたいと思うのですが、その辺りはいかがでしょうか。","respondent":"大澤区議会事務局長","answer":"議員の方から調査等の依頼があれば、これまでと同様に対応してまいります。","id":"exchange-130"},{"speaker":"松本委員","kind":"質問・要望","question":"私からは、１５０ページのふるさと納税寄附金、５２ページの特別区民税について伺います。ふるさと納税について１つだけ、区民の方から要望があったことなので、質疑というか要望させていただきたいと思います。品川区のオリジナルデザインを付した返礼品の区民向け販売を希望いたしますが、いかがでしょうか。","respondent":"宮澤税務課長","answer":"区民の方のニーズというところがあるということでありますので、区民向けの一般販売については、有料頒布物として取り扱っていけるかどうかというところと、あと販売価格等々をよくよく検討した上で、検討していきたいと考えています。","id":"exchange-131"},{"speaker":"松本委員","kind":"質問・要望","question":"多くが５０％にも達していない。この点について、当区では同様の乖離が生じていないのか、念のため伺いたいと思います。もちろん、監査の中でそういうものが発覚すれば、それで是正していけばいいのですけれども、できれば自分たちで気づけるものについては、気づけるようにしたほうがいいと思いますので、この点について念のため、当区においても一応、調査していただきたいと思いますが、いかがでしょうか。","respondent":"宮澤税務課長","answer":"システム間連携がされていないという点や、税の収納事務というのはとても複雑な面もあります。来年１月にシステム標準化という移行等もありますので、先ほどご指摘いただいたところも含めて、適切な賦課事務、賦課徴収事務に努めてまいります。","id":"exchange-132"},{"speaker":"松本委員","kind":"意見","question":"そうした傾向もあり、総務省が全市区町村を対象に、２０２４年に日本を出国した外国人労働者らの個人住民税の徴収実態に関する調査を始めたとの報道が８月にありました。調査期間は８月１日から９月１日とのことで、当区も総務省に対して回答を提出していると思うのですけれども、調査内容である、２０２４年１月から１２月に出国した人の個人住民税の滞納件数や滞納税額について、お願いいたします。","respondent":"宮澤税務課長","answer":"外国人の方の滞納状況です。今ちょっと条件というところがあるのですが、令和６年度というところでの数値になります。令和６年度の外国人の滞納者の数というのが７８０人。そのうち１７７人の方が出国しているという状況です。","id":"exchange-133"},{"speaker":"松本委員","kind":"質問","question":"出国したのが１７０人程度ということで、残りの５００人から６００人の間ぐらいの方が現在、滞納なのかなというところでお伺いいたしました。なので、こうした問題というのは、途端に外国人の滞納者がこうですという数よりも、なぜそうなったのかというところが大事かと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私からは、８８ページの生活保護費、それから生活困窮者支援費について、生活保護世帯と低所得者世帯のエアコン設置助成を求めて質問したいと思います。それから、７８ページの区営住宅使用料について、子育て世代への家賃助成等を求めたいと思います。私は、生活保護の世帯や低所得者世帯が、自己負担なくエアコンを設置できる助成をぜひともしていただきたいと思いますが、いかがでしょうか。","respondent":"豊嶋生活福祉課長","answer":"ただ、この暑さも踏まえまして、この間の第３回定例会でもありましたとおり、今後、生活保護世帯の方にもエアコンの支給ができるような助成について、現在、スキームの検討を進めているです。","id":"exchange-135"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それが１点です。この夏季加算については、多くの団体からも、夏季加算を求める声が国にも届けられていると思うのですけれども、ぜひ区としても夏季加算を国に求めていただきたいと思うのですが、いかがでしょうか。低所得者の方も電気代のことを心配しないでエアコンが使えるように、電気代補助というのもぜひつくっていただきたいと思うのですが、いかがでしょうか。","respondent":"豊嶋生活福祉課長","answer":"はエアコンの設置ができるように、現在、区としては検討を進めているところですので、エアコンの設置の助成と、それから適切にエアコンを使用するというところで、何とか熱中症を防ぐ手だてとしていきたいと、区としては考えてあります。","id":"exchange-136"},{"speaker":"鈴木委員","kind":"質問・要望","question":"もう、それぐらいしかいないのだな、その割には周りにいるなと思いながら聞いていたのですけれども、そういう点では、ぜひエアコンを自己負担なく設置していただきたいということと、電気代補助というのは、もともと本来、国がやるべきという夏季加算というのは、ぜひとも区としても求めていただきたいと思います。区営住宅使用料について、特に子育て世帯について伺いたいと思います。","respondent":"川原住宅課長","answer":"申し訳ございません。ただ、現在の入居、８月末現在の年齢別構成というところでは、２０代の世帯、また３０代の世帯、４０代、子育てをしていると想定される世帯数では４０世帯いるといったところです。","id":"exchange-137"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう中で、子ども計画の就学前人口の年齢別推移というのを見ますと、生まれた子どもが年を追うごとに転居していき、四歳、五歳になるまでには５００人近くが減ってしまうという状況になっていると思います。私は、品川区に住み続けたい人が住み続けられるように、ファミリー世帯への家賃助成や転居費用の助成制度もつくっていただきたいと思いますが、いかがでしょうか。","respondent":"川原住宅課長","answer":"委員ご指摘の家賃助成とは制度は異なるのですけれども、低所得者層向けもしくは中低所得者層向けの区営住宅・区民住宅も維持管理を徹底しておりますので、今後の子育て世帯の住まいの在り方というところは検討してまいりたいと思います。","id":"exchange-138"},{"speaker":"こんの委員","kind":"質問","question":"私からは、７４ページ、高齢者等住宅使用料、７８ページ、区営住宅使用料と区民住宅使用料、８４ページ、放置自転車等保管手数料、１２０ページ、サービス付高齢者住宅家賃軽減補助金、１２６ページ、医療保健政策包括補助金、順不同でお聞きしたいと思います。","respondent":"五十嵐保健予防課長","answer":"ほかには任意予防接種としまして、帯状疱疹のワクチンを、５０歳以上の方に、定期接種以外の方には任意接種としてやらせていただいているところです。高齢者の方につきましては、任意接種としまして肺炎球菌ワクチンを実施させていただいているところです。","id":"exchange-139"},{"speaker":"こんの委員","kind":"意見","question":"今、ご説明というか、お知らせを頂いた予防接種は、区民の皆さんの健康と命を守る観点でしてくださっていて、区独自の補助を実施してくださっている。その辺の、いわゆる独自費用助成を実施しようとするときの検討の背景というか、そういうものがありましたらお知らせください。","respondent":"五十嵐保健予防課長","answer":"任意予防接種の助成につきましては、その時々の状況を鑑みながら実施させていただいているところです。例えばＭＲワクチン等は、はしか、風疹などにかかるとお子さんが重症化してしまうこともありますので、定期予防接種を逃した方につきましては実施しています。","id":"exchange-140"},{"speaker":"こんの委員","kind":"質問・要望","question":"それぞれ、そのとき必要なものに応じて、区独自でこうした補助をつくってくださっているということが分かりました。その中で、まだまだ国の定期接種を待っていて、なかなか区の費用助成がなされていない予防接種もあるかと思います。そこで、昨年私も第３回定例会の本会議の一般質問で、乳幼児と高齢者などのＲＳウイルス感染症の重症化を防ぐために必要な予防接種の費用助成を求めてまいりました。","respondent":"五十嵐保健予防課長","answer":"区としましては、様々な任意予防接種について助成してまいりましたが、今まで実施してまいりました予防接種に関しましては、今までずっとやられていた予防接種で安全性が確認されているものを補助してきたという状況になってあります。","id":"exchange-141"},{"speaker":"こんの委員","kind":"質問・要望","question":"安全性が確認されて、動向を見ますです。そうした考え方は理解はしておりますけれども、なるべく早めに進めていくことが必要ということで、今回またこうして要望させていただきましたが、この点についても前向きに、積極的に注視していただきながら、進めていただきたいと考えています。次に参ります。その管理費の額と、その管理費はどのように使われているのか、その辺をまず確認させてください。","respondent":"樫村高齢者地域支援課長","answer":"大井林町についての管理費の用途についてのお尋ねです。こちらにつきましては、共用部分等の管理といったものに費用を充てているところです。","id":"exchange-142"},{"speaker":"こんの委員","kind":"質問","question":"共用部分に使ってくださっているということで、分かりました。共用部分ではない専用部分の修繕。いろいろな不具合が起きたときのお部屋の中の修繕というのは、どのように行われているのでしょうか。そうしたことは、指定管理をしてくださっている事業者と、区としても把握し対応してくださっていることを、区としてはどのように認識されているのか、お伺いしたいと思います。","respondent":"樫村高齢者地域支援課長","answer":"そういったところの対応についての把握ですけれども、基本的には、お住まいの方とオーナーの方で、管理者と調整していただいており、そちらで対応していただいているところですけれども、何か問題がある場合には、区にも連絡を頂いて。","id":"exchange-143"},{"speaker":"こんの委員","kind":"質問","question":"ですので、なるべく管理者と入居者との関係性というのは大事なので、その辺のところを、どうか管理者の方は多分、入居者の方への対応はきちんとしてくださっているとは思うのですが、一方でそういう声が入ってきてしまうと、どうなのかなというところもありますので、区としては管理者のご対応なども、見ていただくというか、把握していただくというか、お仕事をお願いしているこちらとしては。","respondent":"樫村高齢者地域支援課長","answer":"委員がご指摘のとおり、現在につきましては、管理者から何かあった場合に区に連絡を頂くという形を取っておりますが、それだけですと、実際の入居者のそういった細かいお声などが届かない場合もありますので、適宜。","id":"exchange-144"},{"speaker":"こんの委員","kind":"質問・要望","question":"「いろいろと言いにくいな」、「管理者の方に声をかけたいな」、「聞いてほしいな」、こうしたことが言いづらい雰囲気があるという声も入ってきておりますので、もしあれでしたら、そうした入居者のお声も聞いていただけますと、管理者とのそうしたことも、区として修繕というか、そうしたこともできるのかなと思いますので、ぜひその点、入居者のお声もぜひ聞いていただきたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-145"},{"speaker":"藤原委員","kind":"質問","question":"７８ページ、区民住宅使用料、区営住宅使用料、１４６ページ、財産収入、これは国債のことについて伺います。５２ページ、特別区民税、６０ページ、特別区財政調整交付金を伺いますが、まず初めに財産収入、国債です。区民税。毎年、２３区の中で徴収率がトップですよね。課長、新しくその立場に就かれたわけですけれども、いわゆる品川区の伝統の徴収率１位というのは維持できているのか、教えてください。","respondent":"品川会計管理者、川原住宅課長、宮澤税務課長","answer":"先月ぐらいまではかなり大きい金額で運用していたのですが、償還が来まして、少しまた今月、購入させていただいているという状況です。残りの１２世帯については、夫婦もしくは親子、またお子様との３人以上の家庭といった形です。令和６年度の住民税の収納率です。２３区で１位という状況です。","id":"exchange-146"},{"speaker":"藤原委員","kind":"質問・要望","question":"だけれども、今ルールがあると思うのですけれども、利率を見て、そろそろ利子で収入を得るという考えを、もう少し強くしていったほうがいいと思うのですけれども、いかがでしょうか。だけど、日本の方という思いがあるので、その辺についていかがでしょうか。それは所管だから。名称も企画部長から企画経営部長になったのですから、そこはしっかりやっていただきたいと思うので、答弁ください。","respondent":"品川会計管理者、川原住宅課長、久保田企画経営部長","answer":"今、金利も非常に上がってきているところなので、そういう動向を見極めながら、債券購入についてはいろいろと研究しながら買っていきたいと考えています。日本に永住・定住することを認められた方、日本国に１年以上在住していて、住民票を提出できる方という要件が一定度数ありますので。品川区全体の財産管理や公有地の有効活用といったところの視点も大事ですので、企画課と施設整備課と経理課が連携して。","id":"exchange-147"},{"speaker":"藤原委員","kind":"質問・要望","question":"住宅課長、私の質問の仕方が悪かったのです。窓口での説明を伺ったのではなくて、私は、日本の方を多く入れていただきたいという思いで質問をさせていただきました。その答弁がなかったので、また伺います。国債で６０億円と出ました。これは要望ですので、次に財政調整に行きます。財政調整は毎回伺っているのですけれども、私は、やはり品川区にお金が欲しいのです。欲しいから、こういうふうに伺うのです。","respondent":"加島財政課長","answer":"都市計画交付金ですけれども、確かに今まで２００億円でしたのが、今年１００億円増額となって３００億円となりましたけれども、先ほど委員からもございましたとおり、実際、特別区の都市計画事業に対する需要は９００億円と試算しておりますので、３００億円では到底。","id":"exchange-148"},{"speaker":"せお委員","kind":"提案","question":"１３９ページ、給食運営費についてお伺いします。こちらは東京都の補助金としての歳入ですけれども、対象としては食材費のみだと理解していますので、６億円余となっています。そこで、今年度予算化されました学校給食における有機農産物等活用推進事業ですが、予算案が発表された後、私たち会派で地元の複数の青果事業者と意見交換を行い、予算特別委員会で問題提起や提案をさせていただきました。","respondent":"石井学務課長","answer":"例えば地元の青果事業者や調理現場、栄養士と、丁寧に意見交換をしながら、この間、進めてまいりました。４月から関係各所とそういった意見交換を続け、さらに６月からは、その中で得られた知見を基に、事業の具体化についてここまで取り組んでまいりました。","id":"exchange-149"},{"speaker":"せお委員","kind":"提案","question":"ぜひ、引き続き丁寧に進めていただいて、その都度報告いただければと思います。前回も、足立区の「おいしい給食担当課」のお話をさせていただきましたけれども、給食プロジェクトのような取組を構築していただくのも１つですし、大人が補助しながらワークショップなどを行うのも、自分たちが決めた給食ということで、楽しみも加わって、満足度も高まるのではないでしょうか。こちらの見解を伺います。","respondent":"石井学務課長","answer":"こういった中で、今までの給食の取組に加えて、さらにどうやったら魅力ある給食を運営できるか。これについては、教育委員会としてもしっかり考えていきたいと考えています。","id":"exchange-150"},{"speaker":"せお委員","kind":"質問・要望","question":"様々な事例なども聞けて、本当によかったと思うのですけれども、もう、ぜひ子どもたちの声というところを一番に考えて、進めていっていただきたいと思っています。ですから、新しい施策に対しては、その結果、起こる課題に対しても、当初から抱き合わせで施策を打っていただいて、当初からの予算確保をお願いしたいです。こちらは企画課か財政課か、すみません、ご見解を伺います。","respondent":"加島財政課長","answer":"私どもといたしましては、予算編成に当たりまして、区の政策方針との整合性が取れているか、それから実現可能性、体制や規模感、実現可能性があるか、また費用対効果に見合っているかといったことは査定の際に照らし合わせつつも。","id":"exchange-151"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/239858?Template=document&Id=7251#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":118190,"voices":370}},{"id":"r07-20250930-10","meetingId":"r07-cm09","date":"2025年9月30日","dateIso":"2025-09-30","committee":"議会運営委員会","time":"午後 ０時４５分～午後 ０時４７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/350163?Template=document&Id=7173#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":1237,"voices":11}}]);
